import type { PromptLibraryEntry } from "./prompt-library";

export const PROMPT_LIBRARY_ENTRIES: readonly PromptLibraryEntry[] = [
  { id: "agency-applicant-15s-reel", category: "showreel", aspect: "16:9", prompt: "Imagine you are pitching yourself to a motion agency as [your name] and need one short reel to land the job. Make a 15-second, 1920x1080 piece that packs in a wide range of techniques - kinetic type, shape morphs, masked transitions, depth and camera moves, rhythmic cuts - each beat flowing into the next. Treat every second as proof of craft, with consistent style and a confident sign-off frame. Everything is generated in code inside one HTML page, timed from a single clock so it scrubs and loops cleanly." },
  { id: "ball-escape-twelve-rings", category: "showreel", aspect: "9:16", prompt: "Make a vertical 720x1280 clip built to go viral: a bouncing ball trapped inside twelve nested rings, each spinning with a gap, breaking free one ring at a time until it escapes the last. Use a deterministic physics simulation, neon colors on a dark background, a ring that shatters into particles each time the ball slips through, and a visible counter of rings left. Add satisfying bounce tones synthesized with the Web Audio API after a click. Derive the simulation from one time value with a fixed step so it replays identically, scrubs and loops." },
  { id: "brand-craft-motion-showreel", category: "showreel", aspect: "16:9", prompt: "Make a dynamic 15-second, 1920x1080 motion graphics showreel for [brand or product name] that proves what a skilled motion designer can deliver. Ask me first for the brand's colors, fonts and a one-line description if you need them. Hold nothing back: rhythmic cuts, bold type, layered shapes and a clean name reveal to finish, with every frame driven from one time value so it scrubs and loops cleanly." },
  { id: "brand-motion-showreel", category: "showreel", aspect: "16:9", prompt: "Goal: 15-second motion piece showing your creative range.\n\nLook: design a complete visual system around [brand name]. Use consistent color, typography, and motion language throughout. Every transition should feel intentional and brand-aligned.\n\nBuild: create all graphics from scratch. Layer shapes, text, and effects into a cohesive narrative. Pacing should accelerate toward a strong finish.\n\nCheck: is the motion language distinctive? Do the graphics feel like they belong together? Does it leave a lasting impression?" },
  { id: "brand-resume-reel-fifteen", category: "showreel", aspect: "16:9", prompt: "Goal: a 15-second, 1920x1080 reel that proves what a skilled motion designer can do while promoting [brand name].\n\nAsk me first: what [brand name] does in one line, its colors, and the closing line or tagline.\n\nSequence:\n1. Second one: a bold hook that grabs attention immediately.\n2. A quick run of contrasting techniques - kinetic type, shape play, simulated camera moves, color shifts - each with its own moment.\n3. A clean, memorable end frame with the brand name.\n\nMotion: confident and energetic, with cuts that feel timed to a beat even without audio. Experiment freely; pick the approach that fits best rather than the obvious one.\n\nBuild: one self-contained HTML page; drive every frame from a single time value so it scrubs and loops cleanly. Optional sound only via the Web Audio API." },
  { id: "character-dance-hype-reel", category: "showreel", aspect: "16:9", prompt: "Using [your character image], create a dynamic 15-second 1280x720 motion graphics piece in which the character performs an exciting, high-energy dance. Treat it like a portfolio showreel and go all out: split the image into puppet parts for bouncy poses, add speed lines, beat-synced flashes, bold graphic shapes and camera punches that hit on every count. Drive every frame from a single time value so it scrubs and loops cleanly; any music or hits must be generated in-page with the Web Audio API, and everything stays in one self-contained HTML page." },
  { id: "code-generated-motion-reel", category: "showreel", aspect: "16:9", prompt: "Goal: create a motion portfolio entirely from code and generated elements.\n\nConstraint: no image imports, no external files, no CSS animations. Everything—shapes, colors, typography, movement—comes from JavaScript and canvas/WebGL.\n\nShowcase: algorithmic design, mathematical motion, generative patterns, or creative coding techniques that demonstrate technical skill.\n\nBuild: think of the 15 seconds as a series of algorithmic \"moments\" that build a complete idea. Pacing and beauty matter as much as technical complexity.\n\nCheck: can someone see this code and understand both your motion eye and your programming ability?" },
  { id: "compact-motion-showreel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a punchy 10-second 16:9 motion-design showreel that demonstrates range and craft. Shape a strong opening, several distinct visual moments, and a confident final beat. Use expressive transitions and precise pacing without sacrificing clarity. Build a self-contained HTML page with the animation driven by one time value for clean scrubbing and looping; optional sound must be generated in-page." },
  { id: "creative-api-showreel", category: "showreel", aspect: "16:9", prompt: "Goal: Design a dynamic 15-second motion showreel for [product name], a developer-facing API or tool.\nAsk me first: Request the product URL or description, preferred brand colors, and any key capability to represent.\nLook: Treat requests, data flows, and connected systems as visual inspiration for a polished portfolio-style piece. Use distinctive typography, clean geometry, depth, and art-directed transitions.\nSequence: 1. Open with a strong branded gesture. 2. Translate the tool's core capability into a visual metaphor. 3. Build a few varied motion studies around that idea. 4. End with [product name] and a memorable final composition.\nMotion: Keep it fast, confident, and cohesive; make the craft visible without making the result feel like a random effects sampler.\nBuild: Produce one self-contained HTML page at 1920x1080, with one time value controlling every frame for scrubbing and looping. Optional generated sound may use Web Audio API.\nAvoid: Calling external APIs, exposing credentials, copying another brand's identity, and overloading the screen.\nCheck before finishing: Confirm the named product and its defining capability remain legible." },
  { id: "creative-studio-motion-reel", category: "showreel", aspect: "16:9", prompt: "Create a meticulously art-directed 15-second, 16:9 motion-graphics showreel for [studio name]. Ask for its discipline, palette, and the kinds of work it wants to feature. Compose several compact visual moments that demonstrate typography, shape language, transitions, and fine-detail animation, ending on a clean studio identity card. Keep the result original and reusable. Build a self-contained 1920x1080 HTML page with all frames derived from one time value for scrubbing and looping; optional sound can be synthesized in-page with Web Audio API." },
  { id: "designer-motion-portfolio", category: "showreel", aspect: "16:9", prompt: "Build a 15-second motion piece that demonstrates your full capability as a motion designer. Compress your best ideas into this tight window: choose concepts that showcase strong fundamentals alongside inventive execution. Include transitions that feel surprising but earned, and select motion curves that feel organic rather than mechanical. A color or typographic choice that reinforces your visual voice will strengthen the overall impression. The final frame should feel like a confident ending, not an abrupt cut." },
  { id: "designer-motion-principles-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a refined 15-second motion-design piece in 16:9 that demonstrates mature visual judgment.\nAsk me first: Request a theme, audience, and any preferred palette or design references.\nLook: Favor purposeful composition, visual hierarchy, balanced negative space, and a considered color system.\nSequence: Develop a simple visual idea through a few clear stages, each adding meaning, then finish with a composed final frame.\nMotion: Use restrained, precise timing and transitions that reinforce the design rather than distract from it.\nBuild: Deliver one self-contained HTML page. Let one time value drive every frame for smooth scrubbing and looping; use locally created graphics only.\nAvoid: Effects without purpose, visual clutter, and external assets.\nCheck before finishing: Ensure each movement supports the idea and the 15-second piece feels complete." },
  { id: "designer-portfolio-showcase", category: "showreel", aspect: "16:9", prompt: "Extract the strongest pieces from [your portfolio] and craft a polished 30-second showreel. Research current motion design trends—look for techniques in pacing, transition styles, color grading, and sound design used by leading designers—and apply those insights thoughtfully. Every moment should feel intentional and purposeful.\n\nBuild the narrative to highlight your best work. Question each choice: Does this transition feel fresh? Is the pacing compelling? Does the sound enhance the story? Revise until the piece feels professional and distinctive." },
  { id: "dramatic-product-motion-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Make a 40-second, 16:9 motion-design reel that turns [product name] into a cinematic visual showcase.\nAsk me first: Ask for a product description, its key strengths, and desired closing message.\nLook: Build a dramatic, escalating atmosphere with a bold editorial composition and a controlled, high-impact palette.\nSequence: Introduce the product with restraint, develop a succession of increasingly ambitious visual moments, then land on a decisive final identity frame.\nMotion: Shape pacing with tension, contrast, and precisely timed transitions. Optional original music-like tones may be generated inside the page through Web Audio API; visual accents should follow that rhythm.\nBuild: Create one self-contained HTML page with every frame driven by a shared time value for scrubbing and looping. All imagery and sound must be made in-page.\nAvoid: Borrowing a recognizable score, using remote resources, or invoking video export tools.\nCheck before finishing: Ensure the arc builds clearly and the closing image feels earned." },
  { id: "easing-morph-craft-reel", category: "showreel", aspect: "16:9", prompt: "Create a 15-second 1920x1080 motion graphics reel that shows what a skilled motion designer can do, and hold nothing back. Make easing and morphing the stars: shapes that squash, stretch and melt into one another, overshoots that settle with confidence, and seamless match cuts carrying each idea into the next. Keep a tight palette and a strong rhythm, with one or two moments of stillness so the fast passages land harder. Drive everything from a single time value so it scrubs and loops cleanly in one self-contained HTML page." },
  { id: "fifteen-second-motion-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create an original 15-second motion-design reel in a 16:9 frame. Ask me first for a subject, visual references, or palette; if I have none, propose a strong concept. Look: Build a refined visual language with a clear focal point and purposeful detail. Sequence: Establish the idea, develop it through a few surprising transformations, and finish with a memorable resolution. Motion: Show confident timing and transitions that make every moment feel connected. Build: Use one self-contained HTML page, driven frame-by-frame by one time value for clean scrubbing and looping. Avoid: Reusing recognizable third-party identities or relying on static slides. Check before finishing: Make the short piece feel complete and replayable." },
  { id: "full-range-centerpiece-showreel", category: "showreel", aspect: "16:9", prompt: "Create a 1920x1080 motion graphics piece that could anchor a top designer's showreel. Treat it like a portfolio: show the widest possible range of technique and push the craft hard. Build it as one self-contained HTML page with every frame driven by a single time value so it scrubs and loops cleanly." },
  { id: "hard-hitting-hype-edit", category: "showreel", aspect: "16:9", prompt: "Make a hype edit for [project name] at 1920x1080 that hits as hard as possible. Cut on a fast imagined beat with flash frames, slam zooms, glitch slices, bold stacked type and the project's colors from [one-line project description], building to a big logo hit at the end. Keep it in one self-contained HTML page, drive every frame from a single time value so it loops cleanly, and add a punchy beat only if it is synthesized with the Web Audio API." },
  { id: "intelligence-studio-showreel", category: "showreel", aspect: "16:9", prompt: "Create a dynamic 15-second, 16:9 motion-design showreel for [organization or project]. Ask me what its intelligence or data work actually does, then express that subject through a sequence of refined visual metaphors, precise typography, and confident transitions. Showcase craft without inventing capabilities or using another company's identity. Build a self-contained 1920x1080 HTML page; calculate the animation from one timeline value for reliable scrubbing and looping. Optional sound must be synthesized in-page with Web Audio API." },
  { id: "intentionally-awful-showreel", category: "showreel", aspect: "16:9", prompt: "Goal: Make a one-minute, intentionally incompetent motion-design portfolio parody in a 16:10 frame. Ask me first how exaggerated the awkwardness should feel. Look: Use clashing colors, poorly matched type, lopsided layouts, and conspicuously crude shapes while keeping the joke readable. Sequence: Present a handful of increasingly misguided portfolio moments, then end with an absurdly unconvincing sign-off. Motion: Let timing and transitions feel comically inept by design. Build: Create a self-contained HTML page, with every frame determined by one time value for scrubbing and looping. Avoid: Accidentally polished execution or inaccessible, illegible content. Check before finishing: Make the deliberate bad taste unmistakable and funny." },
  { id: "kinetic-shapes-reel", category: "showreel", aspect: "16:9", prompt: "Build a 15-second motion reel centered on kinetic geometry. Let shapes morph, rotate, collide, and flow—each transformation purposeful and visually satisfying. Use color transitions and layering to add depth and dimension.\n\nFocus on motion quality: smooth easing, rhythmic patterns, and compositional balance. Every frame should feel intentional." },
  { id: "mathematical-motion-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a dynamic 20-second portfolio reel centered on mathematics and visual craft.\nLook: Transform equations, curves, symmetries, grids, and geometric solids into expressive compositions. Balance precise structure with bold color, dimensional depth, and surprising visual rhythm.\nSequence: 1. Introduce a mathematical mark or pattern. 2. Expand it into geometric and spatial studies. 3. Shift scale and perspective through several distinct design moments. 4. Conclude with a polished, résumé-ready signature frame.\nMotion: Use elegant construction, satisfying transformations, and confident transitions; keep the pacing energetic without sacrificing clarity.\nBuild: Make a self-contained HTML page at 1920x1080, driven by one time value for scrubbing and looping. Optional sound must be generated in-page using Web Audio API.\nAvoid: Generic formula wallpaper, unreadable notation, and unrelated effects.\nCheck before finishing: Ensure the mathematical subject and high-level motion-design quality are both immediately apparent." },
  { id: "motion-craft-sampler", category: "showreel", aspect: "16:9", prompt: "Create a short, high-craft motion-design sampler for a browser preview. Ask me for a subject or visual direction; if I have none, invent an original abstract theme. Showcase a few contrasting techniques such as kinetic type, geometric transformation, depth, and fluid transitions, arranged as a cohesive miniature reel rather than a random effects demo. Build it as one self-contained HTML page, with all motion derived from a single time value so it can be scrubbed and looped cleanly. Keep visuals original and locally rendered." },
  { id: "motion-craft-showcase", category: "showreel", aspect: "16:9", prompt: "Make a motion-design showcase in 1920x1080 that demonstrates a skilled designer's visual range. Ask me first for a theme or a few preferred visual references; if I have none, propose a coherent direction before building. Create a short sequence of distinct yet related moments, using strong composition, typography, shape, and deliberate transitions. Deliver a self-contained HTML page with no external network assets. Compute all visuals from one time value so the piece plays, scrubs, and loops consistently; optional sound may be synthesized in-page with Web Audio. Favor a purposeful visual idea over a random collection of effects." },
  { id: "motion-craft-showreel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a 15-second motion-design showreel that could headline a designer portfolio.\nLook: Bold, polished, art-directed imagery; combine expressive type, geometric forms, dimensional scenes, fluid motion, particles, distortion, masks, layered compositing, rich light, and depth.\nSequence: 1. Open with an arresting typographic gesture. 2. Move through contrasting 2D and 3D studies, each introducing a fresh technique. 3. Let shapes and camera paths carry each transition into the next. 4. End on a confident portfolio-worthy frame.\nMotion: Keep the rhythm brisk and assured, with surprising but motivated transitions and fluid camera travel. Make every effect feel intentional rather than gathered at random.\nBuild: Deliver one self-contained HTML page at 1920x1080. Drive all animation from one time value for clean scrubbing and looping; optional sound must be generated in-page with Web Audio API.\nAvoid: External assets, export pipelines, arbitrary effects, and abrupt disconnected cuts.\nCheck before finishing: Confirm the full range of techniques reads as one coherent, highly finished reel." },
  { id: "motion-design-mini-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a memorable 15-second motion-design showreel in 16:9.\nAsk me first: Ask for the designer's name, signature skills, and one preferred aesthetic.\nLook: Present a polished, original demonstration of motion-design ability.\nSequence: Begin with a strong visual statement, showcase several different techniques in quick succession, and end on a clean signature card.\nMotion: Keep movement varied, transitions smooth, and cuts energetic without becoming noisy.\nBuild: Deliver one self-contained HTML page for browser preview. Derive each frame from one shared time value for reliable scrubbing and looping; use in-page graphics only. Optional sound must be generated with Web Audio API.\nAvoid: Model references, remote resources, and video export pipelines.\nCheck before finishing: Ensure the 15-second arc is legible and the ending holds long enough to register." },
  { id: "motion-design-showcase-reel", category: "showreel", aspect: "16:9", prompt: "Design a 40-second motion reel that demonstrates your range as a motion designer. Use sophisticated transitions, layered compositing, and timing to build visual momentum. Include moments of high energy alongside carefully composed stills. The piece should feel polished and intentional, blending multiple motion techniques into a cohesive experience. Select a color palette that reads as premium and modern. Pacing matters: balance quick cuts with moments of visual breathing room. End with a memorable closing frame that lingers." },
  { id: "motion-designer-keyframe-reel", category: "showreel", aspect: "16:9", prompt: "Produce a 15-second motion reel showcasing expert motion design and artistic vision. Emphasize striking visual compositions, confident color direction, and powerful motion execution. Every second must deliver impact.\n\nLook: Bold color palettes and strong typography. Sequence: Build from quiet elegance to dynamic energy, or use consistent kinetic language throughout. Motion: Precise timing and choreography. Avoid: Unnecessary effects or busy layouts—let the core idea breathe." },
  { id: "motion-designer-portfolio-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a dynamic 15-second motion-design reel that demonstrates exceptional craft and a distinct personal visual voice.\nLook: Combine expressive kinetic type, layered forms, graphic transitions, and dimensional moments into a coherent art-directed style.\nSequence: 1. Hook with a memorable opening image. 2. Showcase several contrasting but related motion studies. 3. Build intensity through a clean sequence of transformations. 4. Finish with a confident portfolio signature.\nMotion: Be bold and energetic, with precise timing and smooth scene-to-scene continuity.\nBuild: Make one self-contained HTML page at 1920x1080, with animation fully controlled by a single time value for scrubbing and looping. Optional sound must be generated in-page with Web Audio API.\nAvoid: Generic effect collections, external resources, and references to any AI model.\nCheck before finishing: Confirm the reel feels original, polished, and ready to represent a designer." },
  { id: "motion-designer-showcase-reel", category: "showreel", aspect: "16:9", prompt: "Goal: create a self-contained 30-second motion piece that demonstrates your range and craft.\n\nLook: design everything from scratch. Think like a boutique studio pitching to startup founders. Build graphics, type treatments, and transitions that feel premium and intentional.\n\nBuild: all assets must come from code or generated elements—no imports or external files. Every motion, shape, color, and effect lives inside one HTML canvas. Make it tight, polished, and memorable.\n\nCheck: does every second have purpose? Is the pacing energetic but readable? Does it tell a cohesive story about what skilled motion can achieve?" },
  { id: "one-second-motion-study", category: "showreel", aspect: "16:9", prompt: "Goal: Make an original motion-design showpiece that makes one second feel expansive and memorable. Ask me first whether I have a subject, palette, or reference; if not, invent a coherent direction. Look: Choose a distinctive visual system with strong contrast, precise composition, and a few delightful surprises. Sequence: Establish a simple visual idea, transform it through several tightly connected states, then land on a satisfying final image. Motion: Make timing, scale, and transitions feel intentional rather than like a slide deck. Build: Create a self-contained 16:9 HTML page with all motion driven by a single time value, scrub-ready and loopable. Optional sound may be synthesized with Web Audio API. Avoid: Generic templates, model comparisons, and static presentation slides. Check before finishing: Make the result feel crafted and complete even when replayed." },
  { id: "overthinking-vertical-showreel", category: "showreel", aspect: "9:16", prompt: "Goal: Create a dynamic 15-second motion-design reel about overthinking in a 9:16 frame. Ask me first to provide any visual references; if none are available, build an original direction. Look: Suggest thoughts multiplying through repeated marks, branching lines, nested shapes, or shifting type, with a controlled palette. Sequence: Begin with one small concern, let it expand into a complex mental loop, then resolve into a quiet, clear final beat. Motion: Contrast accelerating repetition with a deliberate pause. Build: Use one self-contained HTML page and one time value to drive every frame, enabling scrubbing and looping. Avoid: Copying reference artwork or making the image so dense that the idea disappears. Check before finishing: Preserve a strong silhouette and readable pacing on a phone." },
  { id: "personal-research-intro", category: "showreel", aspect: "16:9", prompt: "Goal: Create a 10-second 16:9 visual introduction based on what the user chooses to share about their research or interests.\nAsk me first: Ask which facts, topics, and personal details are appropriate to include; do not assume private information.\nLook: Turn the selected themes into a compact, coherent visual motif.\nSequence: Open with a striking symbol, connect it to two or three supplied interests, and finish with a personal title or closing image.\nBuild: Use a self-contained HTML page whose animation follows one time value for scrubbing and looping.\nAvoid: Inventing biographical details or exposing information the user did not provide." },
  { id: "personal-skills-showreel", category: "showreel", aspect: "16:9", prompt: "Goal: Build a 25-second motion showreel presenting [your name]'s selected professional skills for a resume or portfolio. Ask me first for the skills to feature, the intended role, and any work samples or colors to include. Sequence the piece as a quick identity reveal, several distinct skill demonstrations, and a clean contact or portfolio end card. Use 1280x720 composition, varied transitions, and a confident rhythm that lets each example register. Build a self-contained HTML page without external network assets; animate entirely from one deterministic time value so it can be scrubbed and looped. Optional sound may be generated in-page with Web Audio. Keep the work specific and credible rather than relying on unsupported superlatives." },
  { id: "portfolio-site-motion-reel", category: "showreel", aspect: "16:9", prompt: "Bring [your portfolio website] to life by animating its key pages and sections. Capture the home, features, profile views, and contact areas—showing them in browser and mobile window frames. Include animated sequences of real conversations or Q&A from your site, rendered in bold typography at readable scale.\n\nApply premium motion principles: three core brand colors, thoughtful spacing, and eased transitions. Build rhythm that ebbs and flows with your narrative. Cut to a ~120 BPM pulse; music is optional, synthesized in the page with the Web Audio API, with no sound effects. Structure it as a cohesive journey that ends on your site and contact information.\n\n90–100 seconds, 1920×1080." },
  { id: "product-motion-craft-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a 30-second 16:9 motion-design showreel around [product name] and [product URL or one-line description].\nAsk me first: Request the reference clip or images, product details, and any must-include message.\nLook: Study the reference for its visual language, then invent a clearly original composition that showcases skilled motion craft. Make it bold, stylish, and cohesive.\nSequence: Build a series of varied product-focused moments, each introducing a fresh graphic idea, then finish with a strong product signature.\nMotion: Combine crisp transitions, dimensional depth, expressive typography, and confident pacing; keep every beat purposeful.\nBuild: Deliver a single self-contained HTML page for the browser preview. Derive all frames from one time value for reliable scrubbing and looping. Create visuals locally; optional audio may use Web Audio API.\nAvoid: Reproducing the reference shot-for-shot, third-party brand material, remote assets, and exported video workflows.\nCheck before finishing: Confirm the 30-second rhythm feels intentional and that the original visual direction is unmistakable." },
  { id: "product-visual-showreel", category: "showreel", aspect: "16:9", prompt: "Goal: Build a 40-second, 16:9 motion-design showcase for [product name] using [product URL or one-line description].\nAsk me first: Request product context, audience, distinguishing features, and any visual assets or identity guidance.\nLook: Make the product the center of an ambitious, original designer-led visual reel.\nSequence: Progress through multiple distinct scenes that reveal the product's character, value, and details, then close on a memorable brand-neutral product signature.\nMotion: Vary scale, transitions, and graphic techniques; keep pacing energetic without obscuring the subject.\nBuild: Create one self-contained HTML page for BurnGuard preview. Use a single time value for all motion so users can scrub and loop it cleanly. Draw assets locally; optional sound is allowed only through Web Audio API.\nAvoid: Inventing product facts, relying on remote media, or exporting a video file.\nCheck before finishing: Ensure the 40-second sequence has variety and a clear ending." },
  { id: "project-motion-portfolio", category: "showreel", aspect: "16:9", prompt: "Create a dynamic motion reel that highlights your strongest technical and creative skills. Push the visual language as far as the concept allows—bold transitions, unexpected timing choices, and layered effects that feel intentional. This is your opportunity to showcase range: mix high-impact moments with quieter, more refined sequences. Choose a consistent visual theme that ties everything together. The 1920×1080 frame should feel expansive and purposeful. End decisively rather than fading out." },
  { id: "psychedelic-motion-reel", category: "showreel", aspect: "16:9", prompt: "Create a 20-second motion reel with a psychedelic and hypnotic aesthetic. Embrace bold color shifts, warping geometries, fluid distortions, and optical illusions. The motion should feel immersive and otherworldly—pulling the viewer into a trance-like experience.\n\nUse repeating patterns, kaleidoscopic effects, and synchronization with sound to deepen the hypnotic quality. Keep it visually striking and technically polished." },
  { id: "recruiter-personal-intro-reel", category: "showreel", aspect: "16:9", prompt: "Make a lively 15-second, 1280x720 motion graphics video in which [your name] introduces themselves to a recruiter. Ask me first for my role, top skills, two or three highlights and how to get in touch. Use the full toolbox of motion design (kinetic type, shape transitions, layered reveals) so it doubles as a resume showreel, and close on my name and contact line. Drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "resource-led-portfolio-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Build a 20-second portfolio reel for [portfolio owner] using only materials they provide from their portfolio.\nAsk me first: Request the portfolio URL or uploaded assets, permission to use each item, and the visual work they most want to feature.\nLook: Let the source work define the palette and rhythm. Arrange selected imagery with clean typography, confident framing, and restrained transitions.\nSequence: 1. Open with a distinctive portfolio image. 2. Present a curated range of work in a deliberate progression. 3. Give standout pieces a moment to breathe. 4. Close with [name or portfolio label].\nMotion: Use the artwork itself as the transition material where possible; maintain a clear, well-paced flow.\nBuild: Create one self-contained HTML page at 1280x720, controlled by a single time value for scrubbing and looping. Optional sound must be generated in-page with Web Audio API.\nAvoid: Invented projects, unprovided imagery, and external network assets.\nCheck before finishing: Confirm all visuals come from the supplied portfolio materials and the runtime is 20 seconds." },
  { id: "resume-motion-design-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a dynamic 15-second showreel for [your name] that works as a résumé portfolio opener. Use a 16:9 frame.\nAsk me first: Request the designer's specialty, strongest skills, and preferred visual tone.\nLook: Treat it as a compact demonstration of thoughtful motion craft, not a list of generic effects.\nSequence: Open with a strong title moment, move through several distinct design skills, and finish with [your name] and a concise contact or role line if supplied.\nMotion: Make each transition demonstrate a different technique while keeping the whole piece coherent.\nBuild: Deliver one self-contained HTML page. Drive every frame from a single time value so the preview scrubs and loops cleanly. Keep graphics in-page; optional sound must use Web Audio API.\nAvoid: External assets, unprovided personal details, and video-export workflows.\nCheck before finishing: Verify the work reads clearly at 16:9 and fits the full 15-second duration." },
  { id: "social-app-motion-reel", category: "showreel", aspect: "16:9", prompt: "Create a dynamic 15-second, 16:9 motion-design reel for [social app name]. Ask me for its audience, core interaction, and brand character, then turn those into a compact visual showcase with distinctive transitions and polished detail. Avoid unsupported feature claims and borrowed brand assets. Build a single self-contained 1920x1080 HTML page with all movement tied to one time value, making the piece scrub-friendly and seamlessly loopable. Optional sound may use Web Audio API synthesis only." },
  { id: "studio-site-showcase", category: "showreel", aspect: "16:9", prompt: "Create a 15-second motion piece that animates and celebrates your [studio/agency] website. Extract key sections, showcase design highlights, and let the site's visual identity animate across the screen. Build anticipation and curiosity about what visitors will discover.\n\nApproach: Animate page sections, highlight key projects or values, and use transitions that match your site's aesthetic. Make it feel like an invitation to explore." },
  { id: "swiss-grid-showreel-15s", category: "showreel", aspect: "16:9", prompt: "Create a 15-second, 1280x720 motion graphics reel that works as a portfolio centerpiece for a top-tier motion designer. Lean on Swiss design: strict grid, bold sans type, flat color blocks and precise, rhythmic transitions. Don't ask questions; make your own choices and go all out. Drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "ten-second-identity-burst", category: "showreel", aspect: "16:9", prompt: "Make a 10-second, 1920x1080 motion graphics piece that introduces [your name or studio] and shows what a skilled motion designer can do, pushing creativity and energy as far as it goes. Keep the composition centered and bold; skip corner frames, corner labels and other decorative text in the corners, which read as generic machine-made filler. Drive all animation from one time value so the piece can be scrubbed and loops without a jump." },
  { id: "time-driven-motion-demo", category: "showreel", aspect: "16:9", prompt: "Build a code-driven motion design demonstration as one self-contained HTML page at 1920x1080. Use HTML, CSS, SVG, canvas, or WebGL as appropriate, and derive every visible property from a single elapsed-time value so any frame can be scrubbed deterministically and the full piece loops cleanly. Create a polished sequence that makes the time-based animation technique visually clear through coordinated shapes, typography, and transitions. Optional sound may be generated only in-page with the Web Audio API. Keep assets local, avoid capture or video-export workflows, and verify the opening and ending connect smoothly." },
  { id: "topic-color-motion-reel", category: "showreel", aspect: "16:9", prompt: "Goal: Create a 24-second 16:9 motion-design reel focused only on [topic].\nAsk me first: Get the topic and [brand colors].\nLook: Treat the supplied palette as the visual system; make a refined, varied showcase of design craft.\nSequence: Build a clear opening, several distinct visual interpretations of the topic, and a decisive finish.\nMotion: Make cuts and transitions feel tightly coordinated. Optional sound may be synthesized with Web Audio API.\nBuild: Use a single self-contained HTML page whose animation follows one time value, enabling clean scrubbing and looping.\nAvoid: Unrelated subjects, unprovided brand claims, and external audio or assets." },
  { id: "vertical-motion-craft-reel", category: "showreel", aspect: "9:16", prompt: "Create an energetic 15-second motion graphics piece in portrait format, 1080x1920, that shows what a skilled motion designer can do, as if it were the showreel attached to a resume. Compose for the tall frame: stacked kinetic type, vertical wipes and reveals, and elements that travel the full height. Push the craft hard, and drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "vertical-motion-reel", category: "showreel", aspect: "9:16", prompt: "Goal: Create a high-energy motion-design reel in a 9:16 frame. Ask me first for a theme, preferred colors, or reference material; otherwise invent a unifying concept. Look: Show deliberate craft through strong graphic forms, kinetic type, depth, and a distinctive palette. Sequence: Build a short progression of varied visual moments that share one identity, then close with a confident signature frame. Motion: Let transitions connect the moments rather than feel like unrelated samples. Build: Make one self-contained HTML page with a single time value controlling every frame, ready to scrub and loop. Optional audio may be synthesized in-page with Web Audio API. Avoid: Third-party names and random effects without a visual idea. Check before finishing: Keep the composition striking and readable on a narrow screen." },
  { id: "app-feature-showcase", category: "product-promo", aspect: "16:9", prompt: "Produce a vibrant 20-second motion piece for [app name]. Focus on its standout capabilities—[layout system, classifier features, other core tools]—demonstrating how they work and why they matter. Use dynamic motion, bold color choices, and clear UI animations to bring features to life.\n\nMake it feel premium and energetic. Every transition should communicate value, and the pacing should build momentum." },
  { id: "app-motion-promo", category: "product-promo", aspect: "16:9", prompt: "Craft a 15-second motion promo for [app name]. Showcase what makes the app compelling and how it enhances the user experience. Use dynamic transitions, clear interface animations, and energetic pacing to demonstrate value.\n\nFocus on user outcomes rather than features alone. Make viewers curious about what the app can do for them.\n\nKeep every line of copy fully inside the frame whenever it is readable: bring text in and out with fades, scaling or a mask inside its own box rather than sliding it across the frame edge, and let only shapes and imagery travel off frame. Build it as one self-contained HTML page driven by a single time value, so it plays, scrubs and loops cleanly, with no external assets." },
  { id: "b2b-pitch-video", category: "product-promo", aspect: "16:9", prompt: "Goal: convince a brand or manufacturer that partnering with [your company] creates mutual value.\n\nAsk first: what's your core offer? Why should they trust you? What's one measurable outcome they'll see?\n\nSequence: open with the problem they face. Show your solution in action. End with a number or outcome that proves value.\n\nLook: professional, direct, no fluff. Use their market context and your competitive edge to build credibility.\n\nBuild: strong opening hook, three key proof points, powerful close. 15 seconds is tight—every frame earns its place." },
  { id: "bold-product-trailer", category: "product-promo", aspect: "16:9", prompt: "Create a bold 15-second product promo for [product name] using [product URL or one-line description]. Ask me first for the audience and one key benefit. Compose a clear opening hook, escalating visual proof, and memorable end card in 1920x1080. Choose a distinctive visual system with confident typography, purposeful transitions, and energetic but readable pacing. Build one self-contained HTML page with no external assets; drive every frame from a single time value so playback, seeking, and looping stay deterministic. Optional sound may be generated in-page with Web Audio. Avoid empty spectacle: every visual should reinforce the product." },
  { id: "brand-feature-launch", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a beautiful launch piece of 20 seconds or less for [product name].\nAsk me first: Get the product description, brand guidelines, key features, and preferred call to action.\nLook: Make every frame feel native to the supplied brand while keeping the design modern, clean, and visually rich.\nSequence: 1. Introduce the product and audience need. 2. Present its most important features as fast, clear moments. 3. End with a strong brand signature and [call to action].\nMotion: Use a quick rhythm with legible transitions; prioritize the product's defining message over exhaustive feature coverage.\nBuild: Deliver one self-contained HTML page at 1920x1080. Use a single time value to drive all frames for smooth scrubbing and looping. Optional sound only through Web Audio API.\nAvoid: Inventing brand details or crowding the piece with minor features.\nCheck before finishing: Verify the runtime stays under 20 seconds and the motion fits the brand." },
  { id: "branded-image-workflow", category: "product-promo", aspect: "16:9", prompt: "Goal: Promote [image creation tool] by showing how a user request turns into a branded visual for content. Ask me first for the intended audience, sample request, and brand style. Look: Present a clean creative workspace with an engaging before-and-after contrast. Sequence: A user enters a brief, visual options take shape, a selected image gains the brand's colors and identity, then it lands in a finished content layout. Motion: Make the creation process feel fast, clear, and collaborative. Build: Create a self-contained HTML page with every animation frame derived from one time value for scrubbing and looping. Avoid: Existing company marks, network-loaded images, and implying the tool's results are guaranteed. Check before finishing: Let viewers understand both the request and the resulting use." },
  { id: "chatbot-service-promo", category: "product-promo", aspect: "4:5", prompt: "Design an engaging and friendly motion video introducing [service name]. Show how the service helps users through warm animation, clear messaging, and approachable character or UI design. Make it feel inviting and fun.\n\nTone: Playful yet professional. Look: Bright colors, friendly typography, and expressive motion. Sequence: Introduce the service, show it in action solving real problems, and end with clear next steps. Motion: Smooth, flowing transitions that feel natural and welcoming." },
  { id: "codebase-product-promo", category: "product-promo", aspect: "16:9", prompt: "Create a one-minute, 16:9 promo for [product name], grounded in the product's actual codebase and interface when available. Ask me for access to the relevant project or a product URL, plus the audience and key value proposition. Inspect the supplied materials for genuine capabilities and recognizable visual details, then shape them into a clear opening, feature-led middle, and memorable closing. Build a self-contained 1920x1080 HTML page for preview, with animation controlled by one time value for scrubbing and looping. Use local or code-generated assets only." },
  { id: "complete-product-feature-demo", category: "product-promo", aspect: "16:9", prompt: "Goal: Build a polished product demo for [product URL or one-line description], giving every supplied feature a clear moment.\nAsk me first: Request the product URL or description, a complete feature list, audience, and any UI or brand references. Do not guess missing features.\nLook: Present realistic, readable product screens and keep the visual hierarchy focused on user benefits.\nSequence: Introduce the product, walk through each feature in a logical order, show how the pieces work together, and finish with the main value proposition.\nMotion: Use concise interface transitions, state changes, and focused highlights to make each step easy to understand.\nBuild: Create one self-contained HTML page for preview. Drive all animation from one shared time value to allow scrubbing and looping. Recreate screens locally; no remote assets.\nAvoid: Omitting listed features, inventing capabilities, or cluttering the screen with decorative elements.\nCheck before finishing: Compare the sequence with the supplied feature list and verify every item is shown." },
  { id: "course-hero-motion-piece", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a dynamic 15-second 16:9 hero animation for [course or service] that can lead its landing page.\nAsk me first: Request its name, intended audience, key benefit, and available visual identity.\nLook: Strong composition and purposeful motion, with a clear focal point and professional finish.\nSequence: Hook attention, introduce the offer, illustrate its central benefit, and end on a clean title moment.\nMotion: Keep transitions lively but legible. Optional audio may be generated in-page with Web Audio API.\nBuild: Deliver one self-contained HTML page animated from a shared time value so it previews, scrubs, and loops cleanly.\nAvoid: Unsupported benefit claims or external assets." },
  { id: "craft-workflow-promo", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a dynamic 15-second, 16:9 promo for [field guide or specialist app]. Ask me first who uses it and which practical task it helps with. Look: Combine sturdy, precise graphic elements with a modern, high-craft finish. Sequence: Introduce a real work challenge, reveal the guide as a useful companion, show a few relevant content or tool moments, and close with a memorable title. Motion: Keep transitions brisk and purposeful, like a workflow snapping into place. Build: Make a self-contained HTML page with one time value driving all frames for scrubbing and looping. Avoid: Invented technical advice, brand names, and external assets. Check before finishing: Make the benefit clear to someone in the intended trade." },
  { id: "data-promo-dual-format-beat", category: "product-promo", aspect: "16:9", prompt: "Create a fast, punchy promo for [product name] that shows its key data - for example [report type, such as a backlink audit] and its headline numbers - with counters, charts and short captions cut to a quick beat. Deliver two layouts in the same page, a 1920x1080 landscape version and a 1080x1920 portrait version, with a toggle between them and the composition re-planned for each rather than simply cropped. Add an energetic soundtrack generated in-page with the Web Audio API, starting only after a click, and sync the cuts to its tempo. Drive all motion from one time value so both versions scrub and loop cleanly." },
  { id: "editorial-engraving-promo", category: "product-promo", aspect: "9:16", prompt: "Goal: Create a distinctive 15-second product spot in a 9:16 layout for [product name] and [product URL or one-line description].\nAsk me first: Request a reference image or clip, the product's visual identity, and its key message.\nLook: Bright, crisp editorial art direction with engraved illustration details painted over imagery. Use a varied but restrained palette; avoid beige, faux-vintage styling, and eyebrow labels. Balance small and oversized images, expressive type, clean SVG motifs, and dimensional scenes.\nSequence: 1. Open with an immediate visual hook. 2. Rapidly alternate layered imagery, morphing words, zooms, and a polished 3D moment. 3. Resolve into a memorable [product name] signature.\nMotion: Keep cuts energetic but readable; make each morph seamless and vary image scale and rhythm.\nBuild: Make one self-contained HTML page for the browser preview. Drive all visuals from one time value so playback scrubs and loops cleanly. Create all art in-page; optional sound must be generated with Web Audio API.\nAvoid: Copying a reference composition, external assets, beige art-school styling, and video-export tools.\nCheck before finishing: Confirm the full piece reads at 9:16, transitions remain smooth at every scrub point, and the final frame features [product name]." },
  { id: "email-verification-promo", category: "product-promo", aspect: "16:9", prompt: "Goal: Make a dynamic 20-second launch promo for [product name], an email verification service.\nAsk me first: Request the product URL or description, brand assets, and the top use cases to emphasize.\nLook: Modern SaaS visual language, bold type, clean interface fragments, energetic transitions, and a polished startup-launch feel.\nSequence: 1. Present the problem of unreliable email lists. 2. Reveal the service and its core verification action. 3. Show several relevant use cases as quick, legible vignettes. 4. Finish with the strongest benefit and [call to action].\nMotion: Keep the pace lively while ensuring each message can be read.\nBuild: Create one self-contained HTML page at 1280x720; synchronize every frame to one time value for scrubbing and looping. Optional sound can be generated with the Web Audio API.\nAvoid: Third-party brands, unverified claims, external media, and cluttered feature lists.\nCheck before finishing: Confirm the story fits 20 seconds and the product remains the focus." },
  { id: "emotional-app-story-portrait", category: "product-promo", aspect: "4:5", prompt: "Ask me first for [app name], what it does, who it is for and the feeling it should leave. Then build an emotional motion piece at 1080x1350 that follows one person from a moment of struggle to a small, earned win made possible by the app, with recreated app screens woven into the story. Use soft light, a restrained palette, unhurried pacing and a quiet closing line with the app name. Keep it in one self-contained HTML page driven by a single time value, and add sound only if it is generated with the Web Audio API." },
  { id: "event-lineup-announcement", category: "product-promo", aspect: "9:16", prompt: "Design a 10-second promotional clip for [event name]. Lead with the event title and date. Introduce key elements—performers, speakers, attractions, or activities—with clean, energetic motion. Use bold typography and a vibrant color palette that captures event energy. Each reveal should feel like anticipation building. Keep cuts sharp and timing tight to feel snappy on social platforms. Close with date, location, and a final motion beat that feels celebratory. 720×1280 vertical format." },
  { id: "feature-release-teaser", category: "product-promo", aspect: "16:9", prompt: "Goal: tease the next feature your product is shipping.\n\nAsk first: what problem does this feature solve? What's the 'wow' moment? Why should users care?\n\nSequence: hint at the current workflow's friction. Reveal how the new feature removes that friction. Show the payoff in action.\n\nLook: build anticipation. Use motion and timing to make the feature feel premium and necessary.\n\nBuild: 15 seconds is short—save the full explainer for elsewhere. This teaser just needs to make people curious.\n\nCheck: did I clearly hint at what changes? Does the feature feel valuable?" },
  { id: "glassy-product-launch-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Make a 12-second, 1080x1080 launch film for [product name]. First ask for its name, logo or a simple drawn mark, brand colors, sample user prompt, example response page (heading, brief copy, one highlighted phrase), two feature labels, and optional sound direction. Use fitting defaults for skipped answers; showcase skilled motion design.\nAsk me first: Show four preview frames before completing the film: interface header at 40, orbiting icon at 86, typed prompt at 150, and feature cards at 230.\nLook: Bright keynote mood: white surfaces, pale blue atmosphere, translucent glass, navy details, with mint, cyan, and blue accents adapted to the brand. Use Inter or a similar sans-serif. Avoid purple, violet, magenta, orange, stock UI kits, and template-like styling.\nSequence: 1. Product identity rises inside a softly lit app window; a cursor selects its mark. 2. At a music accent, the mark becomes an app tile as four colored squares orbit, then assemble beside it as a menu-bar symbol. 3. A frosted prompt panel opens and types the sample text; sweep into a lesson page that scrolls into focus, emphasizing its key phrase. 4. Raise one feature card, then reveal two stacked cards with large glass-like titles. 5. Briefly center the logo, then cut to a dark end card as its glowing wordmark shrinks; end during the motion.\nMotion: Preserve eight visual beats over 12 seconds and hard cuts at frames 72, 101, and 159 (29.97 fps). Each shot starts in motion. Blend eased travel, acceleration, directional streaks, and speed-based blur. Only pause on the logo around frames 269-287. Fit interface, cursor, cards, and wordmark to supplied content without changing the rhythm.\nBuild: One self-contained HTML page playing in BurnGuard preview at 1080x1080. Drive all visuals from a deterministic time/frame input with continuous interpolation, enabling clean scrubbing and looping. No timers, CSS transitions, randomness, or external network assets. Use CSS, SVG, canvas, or WebGL; create glass by blurring and lightening the content beneath it. Optional sound must be generated in-page with Web Audio API, never loaded externally. For sound, use a restrained 124 BPM electronic pulse, soft intro, accent near 2.47 seconds, light clicks and transition swishes. No video export or encoding.\nAvoid: Still frames beyond the planned logo pause, crossfades, glowing interface text, blur that erases shapes, and static framing. Preserve the exact cut points and contrast on pale backgrounds.\nCheck before finishing: Load fonts before measuring; scale the logo/name/tagline group to fit. Keep lettering out of card artwork so glass titles remain clear. Scrub the timeline to check deterministic rendering and ensure the planned pause is the only still interval." },
  { id: "growth-milestone-launch-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a launch-style announcement celebrating [product name]'s milestone: [verified achievement and timeframe].\nAsk me first: Confirm the exact metric, measurement period, product description, and approved brand assets.\nLook: Make the milestone feel meaningful with clear numeric typography, confident product imagery, and a celebratory but credible tone.\nSequence: 1. Introduce the product and launch context. 2. Build toward the verified achievement. 3. Let the key number take center stage. 4. Close with a forward-looking brand moment.\nMotion: Reveal the metric with anticipation, then resolve into a clean composition that gives it room to register.\nBuild: One self-contained HTML page at 1920x1080, with animation driven by a single time value for scrubbing and looping. Optional sound may be created in-page with Web Audio API.\nAvoid: Changing the supplied numbers, implying unverified causes, and external assets.\nCheck before finishing: Confirm every factual claim matches the approved milestone and its timeframe." },
  { id: "landing-style-product-showreel", category: "product-promo", aspect: "16:9", prompt: "Create a punchy 15-second, 1920x1080 motion graphics promo for [product name], built to show what a skilled motion designer can pull off. Ask me first for the landing page (link, screenshot or its colors, fonts and headline) so the piece reuses the same styling. Be inventive about which features and moments of the product to feature, and spend the whole budget on craft: bold type, layered transitions and confident pacing. Drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "launch-product-motion-film", category: "product-promo", aspect: "1:1", prompt: "Goal: Create a 12-second, square product-launch motion piece for [product name], played and scrubbed in BurnGuard's browser preview.\nAsk me first: Request the product name, logo or permission to draw a simple mark, one sample prompt, an answer-page title and short copy with one highlighted phrase, two feature labels, and an optional music direction. If details are skipped, invent coherent generic content without using real brands or services.\nLook: Bright keynote-inspired whites, icy blue haze, glass surfaces, deep navy, vivid blue, cyan, and mint. Use clean sans-serif type. Exclude purple, violet, magenta, and orange. Keep interface lettering crisp and avoid preset-looking UI.\nSequence:\n1. A compact product identity rises into a pale app window. A cursor approaches, enlarges on hover, and clicks the mark; motion is already underway at the opening.\n2. On a sharp musical accent, the mark becomes an app tile as four colored squares orbit and settle into a cross, then arrange beside the shrinking icon.\n3. Reveal a laptop menu strip over blue line-art wallpaper. The cursor opens a translucent prompt panel; sample copy types in, then the view whips upward into a lesson page where one phrase catches the eye.\n4. A content card lifts above the page, followed by two offset feature cards with oversized frosted lettering. Blur their exits into a centered logo medallion.\n5. After one brief still hold, send the medallion into a black radial end frame. A luminous wordmark rushes in oversized, contracts, and ends mid-motion.\nMotion: Use smooth accelerating exits, eased arrivals, directional blur that follows travel, cursor rotation toward its path, and precise beat-led transitions. Keep the hard cuts at 2.40, 3.37, and 5.31 seconds; build the remaining pacing around them. Nothing pauses except the logo hold near the final third.\nBuild: Deliver one self-contained 1080x1080 HTML page with no network assets. Render every frame from a single time input using continuous interpolated values, so seeking and looping are reliable; do not use timers, CSS transitions, or unseeded randomness. Create blur and glass effects in-page. Sound is optional; if included, synthesize it with the Web Audio API, with no voice or external tracks.\nAvoid: Frozen frames outside the specified logo hold, crossfades, text baked into card artwork, unreadable blur, generic UI kits, and glow behind interface text.\nCheck before finishing: Confirm a long product name still fits its lockup, the pale orbit tile has a visible edge, all text remains legible, and the four key moments read clearly: app header, orbit cross, typed prompt, and stacked cards." },
  { id: "market-insights-promo", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a bold 15-second 16:9 motion piece for [app name], an investment or market analysis app. Ask me for its audience, strongest feature, and any real product details before shaping the story. Use crisp typography, confident data-inspired graphics, memorable transitions, and tightly controlled pacing to make the value instantly clear. Build a self-contained HTML page with the entire animation driven by one time value for preview scrubbing and looping. Use only substantiated claims and supplied details." },
  { id: "minimal-app-product-film", category: "product-promo", aspect: "9:16", prompt: "Goal: Create a 30-second vertical 9:16 product film for [app name].\nAsk me first: Request its purpose, audience, strongest real capability, and approved interface assets.\nLook: Minimal, premium, and carefully composed, with generous space and smooth interface transitions.\nSequence: Establish a simple visual hook, reveal the app, demonstrate one meaningful task, and close on its identity.\nMotion: Use restrained, fluid movement that keeps the interface easy to read.\nBuild: Create a self-contained HTML page with the full animation driven by one time value for reliable scrubbing and looping. Optional sound must be generated in-page with Web Audio API.\nAvoid: Unsupported product claims, external assets, and imitation of proprietary branding." },
  { id: "mobile-app-launch", category: "product-promo", aspect: "9:16", prompt: "Create a vertical launch piece for [Android app name]. Ask me first for the app's main audience, core task, and the key screens or features to show. Reveal the app identity, then demonstrate a short, believable user flow that ends with a clear benefit. Compose for 1080x1920 with legible interface details and polished transitions. Deliver a self-contained HTML page with no external network assets; drive all motion from one deterministic time value so playback, scrubbing, and looping stay consistent. Optional sound may be synthesized in-page with Web Audio. Do not invent screens or capabilities." },
  { id: "multiplatform-game-launch", category: "product-promo", aspect: "16:9", prompt: "Create a high-energy 16:9 launch promo for [game name]. Ask me for the product URL or a short description and which statistics are current and safe to show; use real figures only when supplied, otherwise present clearly fictional sample data. Feature energetic gameplay-inspired graphic motion, a desktop-to-mobile device transition, and a quick showcase of multiple visual themes. Close with a concise invitation to play. Build a self-contained 1920x1080 HTML page whose full animation is controlled by one time value, suitable for scrubbing and looping. Do not source a song externally; optional sound can be synthesized with Web Audio API." },
  { id: "music-artist-promotion", category: "product-promo", aspect: "16:9", prompt: "Create a music video or promotional piece for [artist name]. The visual language should reflect the artist's unique style and sound. Drive the rhythm from a beat grid in the page (any sound is synthesized with the Web Audio API, never loaded from files) and sync motion to it—whether through beat-driven cuts, rhythmic typography, or flowing choreography. Choose a visual theme that feels authentic to the project. Include the artist name and any relevant links or social handles as readable graphics. The piece should leave a lasting impression and feel distinct from generic music-video templates. Use color and motion purposefully to amplify the track's emotional tone." },
  { id: "music-discovery-product-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Create an 18-second, 16:9 premium music-service motion piece that plays as a single self-contained HTML page in BurnGuard's browser preview. Ask me first for [service name] and [one-line product description]; use fictional track and artist names if none are supplied.\nLook: Frame a compact dark rounded interface against an emerald-to-black atmospheric field. Use white type, quiet gray details, vivid green accents, one clean sans serif, and generous breathing room. Design a text-free square cover for a fictional track with pearlescent liquid folds in lavender, cyan, blush, gold, and mint; reuse it throughout. Add a coordinated set of colorful geometric playlist sleeves.\nSequence:\n1. 0-1.5s: A simple green service mark resolves into a two-line music-discovery message with clipped upward reveals.\n2. 1.5-4s: A desktop music interface glides in, then focuses on featured covers and a short staggered track list.\n3. 4-6.6s: A horizontal mood-playlist rail leads into a search for the fictional track; its result grows into the featured album cover.\n4. 6.6-9.8s: Pair the cover with concise track details and a play control. Briefly invert the stage to green, then return to dark as the artwork makes a dramatic, neatly clipped push toward the viewer.\n5. 9.8-14s: Reveal a two-line rhythm statement, a set of playlist sleeves, then four coordinated floating covers including the hero art.\n6. 14-18s: Covers converge around the service mark. Settle the mark beside [service name] and hold a crisp two-line closing message.\nMotion: Keep a subtle mini-player near the stage bottom through most middle beats, with cover thumbnail, track details, playback controls, progress line, and volume glyph. Connect shots with matched positions, masked text, controlled perspective, and smooth acceleration/deceleration. Maintain clear separation between outgoing and incoming copy.\nBuild: Drive every visual property from one absolute time value so the complete 18-second composition seeks accurately and loops cleanly. Use HTML, CSS, and JavaScript only; optional sound may be synthesized in-page with Web Audio API. No network assets.\nAvoid: Creator marks, extra captions, counters, clutter, arbitrary full-screen fades, text collisions, uncontrolled bounce, particles, flare, shake, and unconnected imagery.\nCheck before finishing: Scrub through cover handoffs, title changes, the zoom, convergence, and final mark spacing. Confirm clean clipping, legible type, deterministic playback, and a composed ending." },
  { id: "newsletter-motion-showreel", category: "product-promo", aspect: "16:9", prompt: "Goal: Design a 20-second, 16:9 motion identity for [newsletter name]. Ask me first for its subject, audience, and a sample headline. Look: Treat the newsletter as an editorial world, using expressive type, carefully chosen colors, and visual details tied to its topic. Sequence: Introduce the publication, animate a few headline-like ideas, reveal its recurring value, and finish with a clean subscription invitation. Motion: Show range through typography, composition, and transitions without losing coherence. Build: Create a self-contained HTML page; derive all animation from one time value so it scrubs and loops cleanly. Avoid: Generic résumé claims and external media. Check before finishing: Make the identity recognizable after a single viewing." },
  { id: "open-source-readme-hero-launch", category: "product-promo", aspect: "16:9", prompt: "Create a bold 20-second, 1920x1080 launch piece in motion graphics for [project name], my open-source project, whose tagline is [tagline, e.g. three short steps]. It should feel like the hero video at the top of the repository README: dramatize the tagline beat by beat, show the tool doing its job in a stylized interface, and land on the project name. Go all out on craft while keeping text readable at README size, and drive every frame from one time value so it scrubs and loops seamlessly." },
  { id: "paper-marker-launch-explainer", category: "product-promo", aspect: "16:9", prompt: "Goal: a 15-second motion film, 1920x1080, that explains [product name] to [target audience]. No narration and no footage; everything is drawn, typed and animated in the page.\n\nAsk me first: the one-line pitch, what the product actually does, any positioning notes to read, words I never want on screen, the logo mark (SVG or inline file) plus wordmark font, brand fonts, and four colors: canvas, ink and two accents.\n\nLook: a light paper canvas with handwritten marker notes that write themselves on, oversized condensed kinetic type, and abrupt flips between light and dark (dark = a charcoal tuned to the palette). Notes use the accent colors. Use a handwriting-style font animated by stroke-dashoffset, falling back to system fonts when none is supplied.\n\nSequence: a fresh idea lands every 1.5-2 s. Name the concrete things the product picks up or does, not abstract benefits. Include at least one physics moment (e.g. a ball that is thrown, bounces and settles) and finish on the real logo mark beside the product name in the wordmark font.\n\nMotion: proper easing, squash and stretch, staggered and overlapping action, follow-through, smears and onion-skin trails. One main move per transition; skip stock push, slide and swing-rotate transitions. Never hide an exiting element behind an entering one.\n\nBuild: one HTML file. Drive every frame from a single time value so the film can be scrubbed and loops cleanly; define every element's starting state at t=0. Optional sound only via Web Audio API: a hit on each beat (pops, pen scratches, whooshes, a low thump under the logo), with the beat thinning out on the dark switch and during the airborne moment, then slamming back for the type and the logo. Keep levels moderate and avoid clipping.\n\nAvoid: any player chrome on screen (timeline, timecode, fps, headers); motion-design jargon in the copy; made-up results such as percentages, multipliers, figures or customer names; the banned words; the logo shown as a boxed image.\n\nCheck before finishing: every on-screen word talks to the buyer, seeking to any time shows a correct frame, and the loop point is seamless." },
  { id: "parenting-app-launch-demo", category: "product-promo", aspect: "9:16", prompt: "Create an upbeat vertical launch demo for [parenting app name] at 886x1920. Ask for the app's real audience, core features, and the feeling it should convey. Present a relatable everyday parenting moment, show how the app helps through a few clear interface-inspired scenes, and finish with a warm invitation to learn more. Keep the tone supportive and grounded, never implying guaranteed outcomes. Build one self-contained HTML page with locally created visuals and time-driven motion that scrubs and loops cleanly." },
  { id: "photo-editing-app-promo", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a polished 15-second 16:9 promotional piece for [photo editing product].\nAsk me first: Request the product name, approved screenshots or assets, color palette, and its most valuable editing capability.\nLook: Professional, crisp, and visually rich. Break supplied screens into interface elements that can move independently.\nSequence: Introduce the product, demonstrate a representative edit, reveal the improved result, and close with a memorable identity frame.\nMotion: Make each transition smooth and purposeful, with details that reward attention.\nBuild: Implement a self-contained HTML page driven by one time value for preview scrubbing and looping. Optional audio must use Web Audio API.\nAvoid: Flat screenshot sequences, invented features, and external media." },
  { id: "photo-print-launch-film", category: "product-promo", aspect: "1:1", prompt: "Goal: Create a polished 54-beat, 120 BPM launch piece for [photo-printing product], composed as one continuous square 1440x1440 browser animation. Ask me first for a one-word brand name, 9-12 high-resolution photos, and any concise product details; do not request external music or footage. Show me a beat map and four representative stills (opening, glass interface, device stage, wall) before completing the page.\nLook: 2D only. Warm off-white, black interface elements, photo-led translucent glass, bold condensed wordmark lettering and clean UI type. Use real-feeling cursor clicks, drags, and long-presses. Avoid generic template styling, fades, blur entrances, fake photo developing, 3D flips, particles, glows, and pauses over one second.\nSequence:\n1. Compress the wordmark toward its punctuation; grow the dot into a pill and reveal a label. A six-blade iris snaps open onto a photo.\n2. Transform the aperture into a square, then unfold a photo grid into a bento layout. Zoom into one tile on the musical drop.\n3. Reveal glass lettering, reshape it into a droplet and toolbar, then drag a slider to shift an aligned photo pair from daylight to golden hour. The control becomes a lens and orb; open the next image within it and expand into a lock screen with clock, date, and music controls.\n4. Pull back to a phone. Morph its island into a desktop window, then long-press and drag the wallpaper into a browser tab. The image becomes a landing-page hero.\n5. Scroll and reshape the hero into a framed-print product card. Grow the mat and frame from the photo edge; let color paint across the frame, choose a size, and transform the navigation control into an order action.\n6. Morph one black shape through order confirmation, printing progress, a delivery van on a route, and delivery confirmation. Expand it to fill the frame, then reveal the framed photo on a supplied wall image. Repeat the iris transition and reverse the opening morph so the final frame matches the first.\nMotion: Make every beat legible and tightly paced. Build shape changes, masks, iris blades, spring responses, and camera-like screen zooms as deterministic functions of animation time. Optional sound may be synthesized in-page with Web Audio; keep it off by default.\nBuild: Deliver one self-contained HTML page, with no external network assets. Drive all visuals from a single seekable time value; the same timestamp must always produce the same frame, with clean looping and scrubbing. Use CSS, SVG, canvas, or WebGL as useful; create translucent glass effects from locally rendered scene layers and masks rather than relying on backdrop-filter URL behavior. Provide a still preview for each requested checkpoint.\nCheck before finishing: Confirm the square composition, readable beat-to-beat transitions, matching first and last frames, and deterministic seeking across the timeline." },
  { id: "platform-overview-twenty-sec", category: "product-promo", aspect: "16:9", prompt: "Make a dynamic 20-second, 1920x1080 motion graphics video giving an overview of [platform name and one-line description], and let it show what a skilled motion designer can do. Ask me for the key features to cover. Drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "platform-product-introduction", category: "product-promo", aspect: "16:9", prompt: "Create a 15-second motion introduction for [platform name or brief description]. Open with a visual hook that communicates what the platform does. Build through 2–3 key features or benefits, each introduced with purposeful motion. Use clean typography and a focused color palette that feels modern and trustworthy. The motion should feel purposeful and quick without feeling rushed. Close with the platform name or core value proposition lingering onscreen as a final statement. 1920×1080." },
  { id: "platform-showcase-square-promo", category: "product-promo", aspect: "1:1", prompt: "Build a dynamic motion graphics promo at 720x720 that shows off why [platform name] is worth using, based on [product URL or one-line description]. Open with a bold hook, then move through three or four of its strongest capabilities as animated mock screens, rising charts and confident headline type, and close on the name plus a short call to action. Recreate every interface element in HTML, SVG or canvas inside one self-contained page, and drive all motion from a single time value so the piece scrubs and loops cleanly." },
  { id: "premium-finance-product-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a refined, silent-friendly film for [product name], a business finance tool. Trace one arc from disorder to clarity in 15 seconds or less, 1920x1080 (16:9).\nAsk me first: Request a product URL or description, brand assets and colors, real UI references, and approved short copy. Confirm which screens exist. Use synthetic demo values; reveal no private data and invent no features.\nLook: Let authentic UI lead, framed like a premium object. Follow supplied branding; otherwise use deep navy, restrained warm gold, crisp pale type, spacious layouts, subtle depth, and clean financial numerals. Keep text minimal and surfaces legible.\nSequence:\n1. 0.0-1.2s: A warm glint in darkness catches part of the brand mark and opens onto the product.\n2. 1.2-4.4s: Feature the best real overview. Resolve its key figure, draw a chart, then softly stagger supporting metrics. Optional copy: [short overview phrase].\n3. 4.4-7.5s: Let a chart detail become the edge of a real receipt or document; align it precisely with its matching record.\n4. 7.5-10.7s: Enter a real invoice or payment view. Resolve one status or amount; use green only for a truly positive state.\n5. 10.7-12.8s: If available, show a genuine tax or finance overview, settling visual complexity into calm structure without guarantees.\n6. 12.8-15.0s: Pull back as the UI gathers into one composed surface. Reveal the wordmark and [concise brand line], then hold.\nMotion: Connect scenes with shared shapes and velocity, such as a chart line becoming a document edge. Use polished ease-out, mild anticipation, less than 2% settling, and staggered timing. Suggest measured energy near 115-120 BPM. Optional sound must be generated in-page with Web Audio API; silence should work too.\nBuild: Make one self-contained HTML page for BurnGuard preview, with all motion derived deterministically from one time value for scrubbing and looping. HTML, CSS, JS, canvas, SVG, and WebGL are available; use no network assets. Keep 16:9 and within 15 seconds.\nAvoid: Stock SaaS walkthroughs, fabricated screens or claims, copy-heavy layouts, constant zoom, bouncy motion, excess blur, pointless 3D, particle clutter, blanket glass effects, flashy wipes, glitches, repeated whip pans, and shot-for-shot ad imitation. No external audio or export pipeline.\nCheck before finishing: Ensure UI stays readable, transitions feel causally linked, colors remain restrained, demo details are safe, and the ending has room to register." },
  { id: "product-api-launch-motion", category: "product-promo", aspect: "16:9", prompt: "Craft a 15-second motion piece for [product name]. Communicate the core value and excitement around the launch. Use striking visuals and tight editing to grab attention in a short window.\n\nAsk first: What problem does this solve? What makes it special? Build the motion around one clear, compelling narrative. Let energy and motion convey enthusiasm and capability." },
  { id: "product-feature-launch-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Make a lively 30-second launch film for [product name], highlighting its motion language and user experience.\nAsk me first: Request a product URL or description, brand guide, key features, and available visual assets.\nLook: Give the product a distinctive visual identity through crisp type, carefully composed interface moments, and expressive transitions. Use supplied materials as reference, not as a reason to access repositories or external services.\nSequence: 1. Establish the audience need. 2. Introduce the product. 3. Reveal its most valuable features in a clear progression. 4. Close with a memorable brand moment and [call to action].\nMotion: Make transitions feel intentional and let the sound design support the pace without overwhelming the message.\nBuild: Create one self-contained HTML page at 1920x1080, driven by one time value for scrubbing and looping. Any audio must be synthesized in-page using Web Audio API.\nAvoid: Unsupported claims, external files, and unrelated visual flourishes.\nCheck before finishing: Confirm the key features read clearly and the full story fits 30 seconds." },
  { id: "product-interface-launch-film", category: "product-promo", aspect: "16:9", prompt: "Ask me first for [product name], [product URL or one-line description], target users, and the main benefit to highlight. If I provide a frontend project, inspect its real interface components and visual system, then build a dynamic, premium-feeling product launch film around those details. Sequence a clear opening promise, a few animated feature moments, and a memorable closing callout. Create a self-contained 1920x1080 HTML page for BurnGuard's preview; all animation must follow one time value for scrubbing and clean looping. Use only local or code-created visuals, and optional Web Audio API sound." },
  { id: "product-intro-music-sync", category: "product-promo", aspect: "16:9", prompt: "Goal: introduce [product name or link] with motion synced to music.\n\nAsk first: what does the product do in one sentence? What's the main problem it solves?\n\nBuild: generate the musical score in-page (Web Audio API). Sync every motion hit, transition, and reveal to the music beat and energy. Each section should feel like it lands exactly when the music peaks or drops.\n\nLook: let the music drive the pacing and mood. Start small, build energy, reach a peak moment that showcases the core value. End with a clear call or impression.\n\nCheck: do the visuals feel naturally timed to the score, or do they fight it? Does the viewer understand what the product does?" },
  { id: "product-launch-film", category: "product-promo", aspect: "16:9", prompt: "Goal: announce the arrival of [product name] with professional motion and energy.\n\nAsk first: what's the product? Who benefits? What's the launch date or key message?\n\nLook: pull the design direction and color language from the product itself. Motion should feel premium—controlled, not frenetic.\n\nSequence: open with a bold hook. Establish the problem. Reveal the solution (the product). Close with the name, launchdate, and call to action.\n\nBuild: integrate product imagery if available—hero shots, lifestyle photos, or UI mockups. Motion can abstract these into shapes and transitions.\n\nCheck: is the tone appropriate for the brand? Does the launch feel like a real, worthwhile event?" },
  { id: "product-launch-proof-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Build a confident 16:9 launch film for [product name], clarifying its main value and story.\nAsk me first: Get the product URL or a concise description, audience, brand assets, and the strongest proof point. Ask whether in-page generated sound is desired.\nLook: Match the supplied interface, typography, palette, and brand motion. Keep scenes bold, polished, and socially energetic.\nSequence: 1. Deliver a visual hook within the first second. 2. Show distinct beats that demonstrate the product in action. 3. Reveal its AI capabilities with clear evidence. 4. End on the product identity and a concise benefit.\nMotion: Use brisk cuts and purposeful scene changes. If sound is requested, create it with Web Audio API and align visual hits to its rhythm.\nBuild: Create a single self-contained HTML page. Use one shared time value to drive every frame, allowing smooth scrubbing and a clean loop. Recreate the UI in HTML, SVG, canvas, or WebGL; do not load remote assets.\nAvoid: Unsupported claims, generic AI imagery, and external music or video-render pipelines.\nCheck before finishing: Verify the opening lands immediately, each feature beat is legible, and brand details are consistent." },
  { id: "product-motion-intro", category: "product-promo", aspect: "1:1", prompt: "Design a 15-second motion piece introducing [product name]. Highlight what makes it stand out. Use expressive animation, purposeful color, and clear messaging to convey its benefit. The piece should feel polished and leave a lasting impression in a short window.\n\nAsk first: What's the single biggest value this product delivers? Build the motion around that core idea." },
  { id: "product-motion-showreel", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a polished 30-second product introduction in 16:9 that feels like a motion designer's strongest portfolio piece.\nAsk me first: Request [product name], [product URL or one-line description], and available logo, colors, and interface assets.\nLook: High-energy, professional motion design with expressive transitions and cohesive color. Turn supplied screens into animated layers, icons, and details rather than placing flat screenshots.\nSequence: Open with a confident visual hook, reveal the product identity, animate its most compelling capabilities, then close on a memorable product moment.\nMotion: Give every element purposeful, elastic movement and tightly paced transitions. Optional sound may be generated in-page with Web Audio API; do not rely on external tracks.\nBuild: Make one self-contained HTML page. Drive the complete 30-second animation from a single time value so preview scrubbing and looping work cleanly.\nAvoid: A rough demo feel, static screen dumps, external assets, and claims not supported by the supplied material.\nCheck before finishing: Confirm all key product details are legible and the final frame resolves cleanly." },
  { id: "product-presentation-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Present [product name] in a polished 30-second, 16:9 motion piece.\nAsk me first: Request a concise product description, intended audience, and the one benefit to emphasize.\nLook: Use a clear visual identity, confident composition, and product-led imagery.\nSequence: Establish the product, reveal its most important qualities, connect them to a user benefit, and close with its name.\nMotion: Give each idea a distinct but cohesive transition; keep text brief and legible.\nBuild: Make one self-contained HTML page for the browser preview, with every frame derived from a shared time value for scrubbing and looping. Use in-page visuals only.\nAvoid: Unverified claims, generic filler, or remote assets.\nCheck before finishing: Ensure the story fits 30 seconds and the product takeaway is clear." },
  { id: "product-tracker-motion-promo", category: "product-promo", aspect: "16:9", prompt: "Ask me first for [product name] and [product URL or one-line description], plus its key features. Then build a 1920x1080 motion graphics promo for it that doubles as proof of top-tier motion design skill: bold transitions, crisp UI moments and confident pacing, going all out. Drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "project-feature-tour-film", category: "product-promo", aspect: "16:9", prompt: "Design an animated introduction to [project name] that presents each of its main features like a professional product launch film, at 1920x1080. Ask me for the feature list if it is not clear from [project description], then give each feature its own short scene with a title, a recreated interface or diagram, and one clear benefit line, finishing on the project name. Build it as one self-contained HTML page with every frame driven by a single time value so it can be scrubbed and loops cleanly." },
  { id: "project-story-reel", category: "product-promo", aspect: "16:9", prompt: "Create a dynamic motion piece introducing [project name]. Ask me first what problem it addresses, who it serves, and which real details or interface elements should appear. Build a concise arc: establish the need, reveal the project's approach, then land on its most memorable outcome. Use 1920x1080 framing with a visual language tailored to the project, not generic tech imagery. Deliver one self-contained HTML page with no external network assets; make every frame a deterministic function of a single seekable time value for smooth scrubbing and looping. Optional sound may be generated in-page with Web Audio. Keep every claim grounded in the information I provide." },
  { id: "punchy-dev-tool-release", category: "product-promo", aspect: "16:9", prompt: "Make a modern, sleek and punchy 1920x1080 launch video for the new release of [product name], in the restrained, confident style of top AI-lab announcements. Ask me what the release adds and who it is for, then show the headline change through clean type and code-drawn UI. Keep it fast, minimal and polished, and drive every frame from one time value so it scrubs and loops." },
  { id: "referral-program-promo", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a lively 15-second, 16:9 promo for [referral program]. Ask me first who can invite whom and what reward or benefit is actually offered. Look: Use friendly characterful graphics and a clear visual path between people. Sequence: Introduce a satisfied user, show them sharing an invitation, reveal the confirmed benefit, and end with a simple participation cue. Motion: Let the invitation travel across the frame and resolve into a clear reward moment. Build: Make a self-contained HTML page driven by one time value, scrub-ready and loopable. Avoid: Unverified reward terms, external assets, and confusing eligibility details. Check before finishing: Make the steps understandable at a glance." },
  { id: "saas-feature-launch-film", category: "product-promo", aspect: "16:9", prompt: "Goal: a professional 1920x1080 launch video for [product name] in the style of the slick motion-graphics launches startups post on social media.\n\nAsk me first: [product URL or one-line description], the top 3-4 features, the main benefit, and brand colors.\n\nSequence:\n1. Hook: the problem or promise in one bold line.\n2. Feature beats: recreate key product screens in code (mock UI panels, cursors, highlights) and animate each feature in action.\n3. Benefits: short type-led cards with numbers or outcomes.\n4. Close: logo, tagline and call to action.\n\nBuild: one self-contained HTML page with no external images; redraw UI and logos with HTML/CSS/SVG. Drive every frame from one time value so it scrubs and loops. Optional sound only through Web Audio.\n\nAvoid: generic stock-looking filler and cramped text." },
  { id: "saas-launch-hero-film-16b", category: "product-promo", aspect: "16:9", prompt: "Before starting, ask me for [product name], [product URL or one-line description] and the two or three features that matter most, then study what the product actually does. Build a 1920x1080 release film that works as a website hero loop and as a go-to-market asset: a sharp opening hook, the core problem, the product solving it through stylized UI moments, and a closing frame with the name and a call to action. Keep the pacing confident and the copy short enough to read at a glance, using a palette drawn from the product's own brand. Drive every frame from one time value so the piece can be scrubbed and loops seamlessly in the preview, with no external assets." },
  { id: "saas-launch-promo", category: "product-promo", aspect: "16:9", prompt: "Create a 15-second launch film for [service name]. Show what makes [service] unique and why it matters. Use striking visuals and tight pacing to convey the value proposition—don't just tell it, show how the service solves real problems or improves a workflow.\n\nBuild energy through motion and color. Keep the message focused and the impact immediate." },
  { id: "saas-launch-story-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a 30-second, 16:9 browser-preview launch film for [product name], as a polished demonstration of skilled motion design.\nAsk me first: Request [product URL or one-line description], the real customer problem, key benefits, brand colors, typeface, logo asset, tagline, and destination URL. If a project or page is provided, inspect it for accurate copy and visual identity.\nLook: Premium product-film craft, crisp vector logo, expressive word-by-word typography, spring-like easing, layered depth, subtle glow, and camera-like pans and pushes. Keep titles readable and use a restrained palette drawn from the product.\nSequence: 1. Establish why [market or audience] matters. 2. Show the current frustration. 3. Reveal how [product name] changes the experience. 4. Land the practical benefits. 5. Close with an animated logo, [tagline], and [URL]. Use four or five scenes, each with one concise title.\nMotion: Elements assemble on musical-feeling beats rather than popping in. Give every scene enough screen time to read. Add optional gentle synthesized cues only through the Web Audio API; remain silent between cues.\nBuild: Make one self-contained HTML page at 1920x1080. Drive all visuals from one elapsed-time value so the animation scrubs and loops cleanly. Keep all assets local or code-drawn; do not export video.\nAvoid: Unverified product claims, crowded scenes, clipped text, rushed pacing, external assets, and third-party brand references.\nCheck before finishing: Scrub the full timeline and inspect every scene for legibility, overlap, clipping, smooth transitions, and a clean loop." },
  { id: "science-brand-spectrum-promo", category: "product-promo", aspect: "16:9", prompt: "Create a punchy 15-second motion graphics promo for [product or organization name] at 1920x1080, playing as one self-contained HTML page. Borrow the colors, logo shapes and key phrases from [product URL or one-line description], and redraw any imagery in SVG or canvas rather than loading it from the network. Push the energy hard: fast kinetic type, spectrum-style color sweeps, data-inspired shapes and sharp cuts that land on a clear closing tagline. Drive every frame from one time value so the piece scrubs and loops cleanly, and add sound only if it is generated in-page with the Web Audio API." },
  { id: "search-product-showcase", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a 16:9 product showcase that makes [search product] understandable through a representative use case.\nAsk me first: Request a product description, the real search flow, and any approved interface examples or brand assets. If a product link is provided, use its supplied description rather than depending on external network access.\nLook: Clear, modern interface motion focused on discovery and useful results.\nSequence: Start with a search need, animate the query and refinement, then show how the result helps complete the task.\nMotion: Keep interface changes readable and transitions purposeful.\nBuild: Make one self-contained HTML page with every frame driven by one time value for clean scrubbing and looping.\nAvoid: Recreating unavailable proprietary details or making unsupported claims." },
  { id: "search-tool-motion-promo", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a dynamic 15-second motion promo for [product name], a search or discovery tool.\nAsk me first: Ask for the product description, brand assets, target audience, and one benefit to lead with.\nLook: Build an energetic, refined product story with clear typography, purposeful interface-inspired graphics, and a consistent brand palette.\nSequence: 1. Set up a discovery challenge. 2. Show the product finding or organizing useful information. 3. Reveal the benefit with a strong visual payoff. 4. Close on [product name] and [call to action].\nMotion: Move briskly with smooth transitions and deliberate timing; keep every shot connected to the same idea.\nBuild: Deliver a single self-contained HTML page at 1920x1080. Drive animation from one time value so the preview scrubs and loops cleanly; optional audio only via Web Audio API.\nAvoid: Invented performance claims, third-party marks, external assets, and a disconnected effect montage.\nCheck before finishing: Make the tool's purpose clear within the opening seconds." },
  { id: "service-launch-video", category: "product-promo", aspect: "16:9", prompt: "Create a launch video for [service URL or name]. Open with the core value proposition stated clearly. Show 2–3 reasons why someone would use the service, each visualized through simple, direct motion. Keep the visual language clean and modern. Typography should be large and readable—this is a social media clip that needs to land at thumbnail size. Use one consistent motion language throughout rather than switching techniques. Close with a call to action or the service name/URL. Under 15 seconds, 1920×1080." },
  { id: "software-release-announcement", category: "product-promo", aspect: "16:9", prompt: "Design a release announcement for [software name and version]. Establish the version number early, then unfold what makes this release significant. Include subtle motion that builds confidence—clean reveals, purposeful transitions, confident scale changes. The typography and color should communicate polish and forward momentum. Balance energy with restraint: viewers should leave feeling the update is meaningful and well-executed. Close with the version number onscreen and a final motion beat that feels celebratory but controlled. 1920×1080." },
  { id: "square-app-launch-spot", category: "product-promo", aspect: "1:1", prompt: "Goal: Create a bold 15-second promo for [app name] in a 1:1 frame. Ask me first for the app's purpose, audience, and one key action users can take. Look: Choose a confident, polished visual style that makes the core value instantly recognizable. Sequence: Grab attention, reveal the app's main benefit with a focused visual, then finish with its name and a simple call to action. Motion: Use energetic transitions without sacrificing readability. Build: Make a self-contained HTML page with all animation driven by one time value for clean scrubbing and looping. Avoid: Platform-specific reach claims, external footage, and tiny text. Check before finishing: Ensure the central message is clear at 1080x1080." },
  { id: "startup-pitch-motion-film", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a 30-second, 16:9 pitch film for [project name].\nAsk me first: Request a short description, target audience, problem addressed, solution, and desired call to action.\nLook: Make the concept feel credible and energetic, using a focused palette and clear visual hierarchy.\nSequence: Open on the problem, introduce the proposed solution, show how it works or who it serves, then close with the project name and supplied next step.\nMotion: Use purposeful transitions to connect challenge, idea, and value; keep claims and text concise.\nBuild: Produce one self-contained HTML page for browser preview. Use one shared time value to drive all frames so the sequence scrubs and loops cleanly; create visuals locally.\nAvoid: Invented metrics, unsupported promises, and external network resources.\nCheck before finishing: Confirm the pitch can be understood quickly and every claim comes from user-provided information." },
  { id: "ten-second-site-showcase", category: "product-promo", aspect: "16:9", prompt: "Make a dynamic 10-second, 1920x1080 motion graphics piece about [product URL or one-line description]. Treat it as a showreel entry that shows what a skilled motion designer can do, and go all out. Drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "tool-feature-motion-promo", category: "product-promo", aspect: "16:9", prompt: "Goal: highlight what [tool or product name] does in 15 fast seconds.\n\nAsk first: what's the top feature or use case? What workflow does it simplify?\n\nSequence: open with the problem, show the tool in action, end with the outcome or benefit.\n\nLook: keep it visual and punchy. Use UI mockups, diagrams, or abstract motion to explain the concept. Speed and clarity matter here.\n\nBuild: motion should feel energetic to match the fast pacing. No wasted frames.\n\nCheck: if someone watches once, do they understand what the product does and why they might use it?" },
  { id: "trading-workspace-zoom", category: "product-promo", aspect: "16:9", prompt: "Goal: Create a polished 16:9 product reveal for [trading platform]. Ask me first for its name and preferred accent color. Look: Begin in near-black space with a luminous point; use crisp panels, restrained highlights, and legible market data. Sequence: 1. The point opens into a desktop workspace. 2. Chart, positions, options, and watchlist panels assemble. 3. Move through layered zooms across the interface. 4. Pull back until the desktop becomes a tiny point, then approach a landscape phone showing a chart beside an options list. 5. End on a unified trading view. Motion: Use confident camera scaling and clean panel transitions. Build: Make one self-contained HTML page; derive every animation frame from one elapsed-time value for reliable scrubbing and looping. Avoid: External assets, unreadable data, and abrupt cuts. Check before finishing: Confirm the full journey reads clearly at 1920x1080." },
  { id: "ugc-ad-minimal-sync", category: "product-promo", aspect: "16:9", prompt: "Ask first: the product name and one-line promise, 3-5 key UI moments, one accent color, 10-20 vertical clips you own, and a music track.\n\nLook: one idea per shot, lots of breathing room, single accent color, clean sans serif with tight letter spacing. Masked type reveals and match cuts throughout. Real footage only—no stock placeholders.\n\nSequence: 10 musical bars at 120 BPM (2 seconds each). Hook lands word-by-word on downbeats. A hook word morphs into your product UI. Circle opens from button into darker scene. One movement per bar: clip wall with scan line, key output as large type, 3D carousel of your videos with floor reflections, hero clip in a phone frame, results panel flip, stats on push cuts, three-word ticker, logo moment, fade to black.\n\nBuild: one HTML file, 1920×1080. All motion flows from a single time value so it loops cleanly when scrubbed. Real video as frame sequences swapped per render. Music analysis to lock every cut on a downbeat, every interaction on a beat. Optional Web Audio API for sound effects under the music.\n\nAvoid: dramatic ring effects, explosive bursts, color splits, fast camera movement, lens distortion, bright halos, geometric grid patterns, strobe effects, springy easing curves." },
  { id: "vertical-anime-collab-edit", category: "product-promo", aspect: "9:16", prompt: "Create a 1080x1920 vertical hype edit that pairs [product name] with [anime-style character or mascot] and truly goes hard. Use fast cuts, impact frames, chromatic flashes, screen shake, glowing aura effects and bold kinetic type for the product name, building to a slow-motion hero pose and a clean logo hold. Drive every frame from one time value so it scrubs and loops; any bass hits must be generated in-page with the Web Audio API, all inside one self-contained HTML page." },
  { id: "vertical-capability-promo", category: "product-promo", aspect: "9:16", prompt: "Create a modern social promo for [service name], highlighting [capabilities]. Ask me first for the target audience and the single most important action viewers should take. Design for 1080x1920: lead with a fast visual hook, demonstrate a few concrete capabilities with crisp interface-inspired graphics, and finish with a clear call to action. Keep type large, contrast strong, and transitions punchy without sacrificing legibility. Deliver one self-contained HTML page with no external network assets; derive every frame from a single time value for reliable scrubbing and looping. Optional audio may be synthesized in-page with Web Audio. Avoid vague feature claims and crowded screens." },
  { id: "vertical-update-highlight-reel", category: "product-promo", aspect: "9:16", prompt: "Create a dynamic 25-second, 9:16 motion reel highlighting these recent changes: [release versions or feature list]. Ask me for the product name, the specific improvements, and any interface examples before inventing details. Give each update a distinct visual beat, but maintain one coherent product style and make the motion craft itself feel polished. End with a compact summary of the release. Build a self-contained 1080x1920 HTML page with all animation driven from one time value, so it scrubs and loops cleanly. Use no external media; optional sound may be generated with Web Audio API." },
  { id: "video-transcript-ad", category: "product-promo", aspect: "16:9", prompt: "Create a 15-second product ad for [transcription tool]. Ask me first for the target audience and preferred call to action. Show the simple transformation: a user supplies a video link, speech becomes a readable transcript, and every spoken word can be found. Use 1280x720 framing, expressive kinetic text, and a clear before-and-after sequence that makes the benefit immediately understandable. Build a self-contained HTML page without external network assets; drive the complete animation from one deterministic time value for scrubbing and looping. Optional sound may be generated in-page with Web Audio. Do not imply access to content or features the product does not support." },
  { id: "website-product-motion-ad", category: "product-promo", aspect: "9:16", prompt: "Goal: Create a concise, high-impact vertical motion advertisement for [website or service]. Ask me first for the URL or a one-line description, the intended audience, and the key benefit to communicate.\nLook: Turn the site's strongest visual idea into a polished 9:16 composition with clear hierarchy, refined color, and confident type. Use interface-inspired details only when they help explain the offering.\nSequence: Establish the audience need, reveal the product's main advantage through one focused visual demonstration, then finish with the service name and a brief call to action. Keep each beat immediately understandable.\nMotion: Use purposeful transitions, legible text entrances, and a clear visual focus; adapt timing and visual language to the supplied product details.\nBuild: Deliver a self-contained HTML animation for BurnGuard preview. Make all frames reproducible from one absolute time value for scrubbing and seamless looping. Optional sound may be synthesized in-page with Web Audio API; do not load remote assets.\nAvoid: Invented product claims, generic filler, crowded layouts, and tiny copy.\nCheck before finishing: Confirm the essential message reads at phone size and the complete piece ends on a deliberate, stable frame." },
  { id: "workflow-product-showreel", category: "product-promo", aspect: "16:9", prompt: "Goal: Build a dynamic 15-second product showcase in 16:9 that clearly demonstrates [product name], its core use cases, and how a user moves through it.\nAsk me first: Request a concise product description, its ASCII logo or other supplied mark, and its color palette.\nLook: Make the identity and interface feel cohesive, using animated components instead of a static product dump.\nSequence: Establish the product mark, show a representative task from start to finish, highlight the useful outcomes, and end with a strong branded frame.\nMotion: Use precise timing, crisp transitions, and lively details. Optional audio must be generated in-page with Web Audio API.\nBuild: Implement a self-contained HTML page with every frame driven by one shared time value for scrubbing and seamless looping.\nAvoid: Invented capabilities, external assets, or leaving the workflow unclear.\nCheck before finishing: Ensure the logo treatment respects its supplied ASCII form and every step reads at a glance." },
  { id: "agentic-finance-explainer", category: "explainer", aspect: "16:9", prompt: "Goal: Explain simply how [protocol or service] enables agent-operated investment funds.\nAsk me first: Request a one-line product description, source URL or supplied brand materials, target audience, and any claims that must be preserved.\nLook: Modern, sleek, and punchy. Use brand colors and interface elements only when provided; turn abstract finance concepts into clear visual relationships.\nSequence: 1. Establish the challenge of operating a fund. 2. Introduce autonomous agents as participants. 3. Show a simple step-by-step flow from decision to action. 4. End with the core benefit and product name.\nMotion: Keep diagrams and interface fragments readable, with lively transitions and restrained depth.\nBuild: Make a single self-contained HTML page for the preview, driven frame-by-frame by one time value and able to scrub and loop. Use only in-page graphics; no network assets.\nAvoid: Dense jargon, unverified performance promises, and decorative charts without meaning.\nCheck before finishing: Confirm a newcomer can explain the basic mechanism after watching." },
  { id: "ancient-civilization-history-film", category: "explainer", aspect: "16:9", prompt: "Tell the story of [civilization, e.g. ancient India] as a cinematic 1920x1080 history film: chapters that move from earliest settlements through great eras, ideas, art and architecture, each with an illustrated scene, a date marker and one short caption. Use a palette and ornament style inspired by that culture, with slow camera drifts, parallax layers and graceful transitions between eras. Score it with music and light sound effects synthesized in-page through the Web Audio API, starting on a click, and drive every frame from one time value so it scrubs and loops cleanly. Stay respectful and accurate, avoiding stereotypes." },
  { id: "article-lesson-motion", category: "explainer", aspect: "16:9", prompt: "Goal: Turn [article text or URL] into a clear educational motion piece. Ask me first who the lesson is for and what viewers should remember. Identify the central ideas, arrange them from context to explanation to takeaway, and use simple visual metaphors and readable labels to teach each point. Compose in 1280x720 with a calm, purposeful pace. Build one self-contained HTML page without external network assets; derive every frame from a single deterministic time value for scrubbing and seamless looping. Optional sound may be generated in-page with Web Audio. Preserve the article's meaning and avoid adding unsupported facts." },
  { id: "artificial-intelligence-history", category: "explainer", aspect: "16:9", prompt: "Goal: Make an accessible visual timeline of pivotal moments in artificial intelligence history.\nAsk me first: Ask for the intended audience, time span, and any trusted sources or milestone list to use.\nLook: Combine clear dates, concise labels, and evolving visual metaphors to distinguish historical eras while keeping the design cohesive.\nSequence: Arrange verified breakthroughs, debates, and shifts in chronological order; use a final moment to connect the past to today's landscape.\nMotion: Let each milestone enter as the timeline advances, using measured transitions that support comprehension.\nBuild: Create one self-contained HTML page at 1920x1080, with all motion controlled by a single time value for scrubbing and looping. Optional audio may be generated in-page with Web Audio API.\nAvoid: Treating disputed interpretations as settled facts or implying that one event alone caused a complex change.\nCheck before finishing: Confirm the dates and descriptions are consistent with the provided sources." },
  { id: "brand-story-explainer", category: "explainer", aspect: "16:9", prompt: "Produce an explainer for [brand or business]. Open by establishing what the brand makes or does. Walk through the distinctive elements that set it apart—whether that's materials, process, values, or community. Use motion to highlight these qualities without overstatement: clean reveals, thoughtful pacing, and visual clarity matter more than spectacle. Include real photography or clean illustrations of the product/service. Closing should reinforce the core reason someone would choose this brand. 1280×720, under 90 seconds." },
  { id: "campaign-insights-workflow", category: "explainer", aspect: "16:9", prompt: "Goal: Build a modern, punchy explainer for [product name] that follows a user from campaign creation to useful insights.\nAsk me first: Get the product URL or a one-line description, brand colors, and any preferred campaign example.\nLook: Crisp SaaS interface scenes, clear data visualization, lively transitions, and a confident contemporary finish. Use fictional sample data unless supplied otherwise.\nSequence: 1. Show a user creating an example ad campaign. 2. Connect performance metrics and reveal how attribution clarifies results. 3. Add a voice assistant, show it responding, then handling a follow-up. 4. Bring a human into the review loop. 5. Close with an analytics overview that ties the workflow together.\nMotion: Use focused transitions between interface states; make each step understandable at a glance.\nBuild: One self-contained HTML page at 1920x1080, with all movement derived from one time value for scrubbing and looping. Optional audio only via in-page Web Audio API.\nAvoid: Real customer data, external services, and unsupported product claims.\nCheck before finishing: Verify the sequence clearly communicates how each stage leads to the next." },
  { id: "cocktail-recipe-motion", category: "explainer", aspect: "1:1", prompt: "Create a 30-second motion sequence that visualizes the journey from an empty glass to a finished cocktail. Display each ingredient and its measurement as it enters the glass, building the drink step by step. Use clear labeling and smooth animations to guide the viewer through the recipe.\n\nStyle it like an educational motion graphic: clean layouts, legible type for amounts, and flowing transitions that make the assembly feel natural and satisfying." },
  { id: "cocktail-recipe-pour-explainer", category: "explainer", aspect: "16:9", prompt: "Build a 30-second, 1920x1080 explainer animation that walks through the full recipe for [cocktail or drink name], starting with an empty glass and ending with the finished, garnished drink. Pick whatever mix of HTML, SVG or canvas gives the cleanest result. Show each ingredient as it goes in, with its name and measurement labeled on screen and the liquid level and color visibly changing in the glass. Pace the steps evenly so each pour is readable, and drive every frame from one time value so the piece can be scrubbed and loops back to the empty glass." },
  { id: "five-scene-business-explainer", category: "explainer", aspect: "16:9", prompt: "Build a 30-second, 1920x1080 animated explainer for my business as one HTML page, in five scenes: the customer's pain point, what I offer, how it works in three steps, a single proof point, and my name to close. Use big, bold type, smooth scene transitions and my brand colors throughout. My business: [what you sell, who it is for, your brand colors]. Drive all motion from one time value so the piece scrubs and loops cleanly." },
  { id: "game-release-news-roundup", category: "explainer", aspect: "16:9", prompt: "Produce a 60-second motion graphic summarizing recent game releases [date range]. Present each title from a gamer's perspective, highlighting what makes each game exciting. Show gameplay moments, feature descriptions, and visual hooks that draw player interest.\n\nStructure: Open with a striking title treatment. Present games in quick succession with clear labels and appealing visuals. Close with a call to explore these titles. Motion: Use snappy transitions and pacing that feels energetic without overwhelming." },
  { id: "git-basics-beginner-explainer", category: "explainer", aspect: "16:9", prompt: "Make a 1920x1080 explainer that teaches what Git is to someone with zero computing background, explained simply but with real depth. Open with an everyday analogy such as saving numbered drafts of an essay, then show snapshots, history, branches and merging as friendly animated diagrams before introducing the common commands (init, add, commit, status, log, branch, checkout, merge, push, pull) one per beat, each with a plain-language meaning and a tiny visual of what changes. Write all on-screen captions in [narration language, e.g. Chinese] and pace them so a beginner can read along; if you add sound, generate soft cues in-page with the Web Audio API. Drive every frame from one time value so the whole piece can be scrubbed, all inside one self-contained HTML page." },
  { id: "hand-drawn-physics-whiteboard", category: "explainer", aspect: "16:9", prompt: "Create a short hand-drawn whiteboard animation in 1280x720 that explains [concept, e.g. replica symmetry breaking in the SK spin-glass model]. Draw strokes on progressively as if sketched by a marker, building diagrams and labels step by step. Carry the narration as timed on-screen captions; optional sound only if generated in-page with Web Audio. Drive all drawing from one time value so it scrubs and loops." },
  { id: "handdrawn-finance-explainer", category: "explainer", aspect: "4:3", prompt: "Goal: Create a first-person explainer in which [service name] introduces what it does and how it helps.\nAsk me first: Request the service's core purpose, audience, and the main point viewers should remember.\nLook: Use a warm hand-drawn stop-motion aesthetic with tactile linework and deliberately crafted frame changes.\nSequence: Let the service introduce itself, explain the problem it addresses, show its basic process, and close with the practical benefit.\nMotion: Use small pose shifts, drawn accents, and charming pauses to suggest handmade animation while keeping information clear.\nBuild: Deliver one self-contained HTML page. Drive all frames from one time value for scrubbing and looping. Keep illustrations in-page; optional sound only via Web Audio API.\nAvoid: Unsupported financial promises, dense terminology, and external footage.\nCheck before finishing: Confirm the first-person voice stays consistent and the explanation is easy to follow." },
  { id: "math-concept-animation", category: "explainer", aspect: "16:9", prompt: "Goal: teach [math concept] through animation and clear examples.\n\nAsk first: what's the core idea in one sentence? What's a real-world application or surprising example?\n\nLook: accessible and visual. Use diagrams, number animations, and geometric shapes to show why the concept works. Avoid heavy notation—let motion prove the point.\n\nSequence: open with a puzzle or question. Build intuition through examples. Show the general rule or formula. Close with a \"think about it\" moment.\n\nBuild: each animation should feel necessary—no decoration. Use color and motion to guide the eye through the logic step by step.\n\nVoice: natural, conversational narration shown as on-screen captions; any sound is optional and synthesized in the page with the Web Audio API. Pacing slow enough to follow, fast enough to stay engaged.\n\nCheck: could someone with no background understand this? Is the concept memorable?" },
  { id: "national-political-history", category: "explainer", aspect: "16:9", prompt: "Goal: Create a concise, clear timeline explaining [country]'s political history since independence.\nAsk me first: Confirm the country, independence date, desired period, audience, and trusted source material for milestones.\nLook: Use an editorial timeline, restrained map or document motifs, readable dates, and a visual tone appropriate to a serious history explainer.\nSequence: Organize verified milestones chronologically, showing how each event connects to the next; conclude with a neutral present-day context.\nMotion: Reveal the timeline progressively, using transitions to signal changes in era without dramatizing or distorting facts.\nBuild: Produce a self-contained HTML page at 854x480, animated from one time value for scrubbing and looping. Optional sound only via Web Audio API.\nAvoid: Unsupported claims, partisan framing, and decorative imagery that could misrepresent events.\nCheck before finishing: Verify names, dates, chronology, and neutral wording against the supplied sources." },
  { id: "pixel-art-ai-history-loop", category: "explainer", aspect: "16:9", prompt: "Make a 15-second pixel art animation at 1280x720 that races through the history of language models, from early chatbots and small neural nets to today's large models, then shows the machines starting to improve themselves. Play it as a boomerang that runs forward and back, and let the final third escalate into glorious chaos with screen-filling sprites, palette swaps, glitches and recursive zooms. Draw on a low-resolution canvas scaled up with crisp pixels, keep everything in one self-contained HTML file, and drive every frame from a single time value so it loops seamlessly." },
  { id: "product-feature-explainer", category: "explainer", aspect: "16:9", prompt: "Goal: Explain [product name] and its value in a compelling 30-second piece. Ask me first for [product URL or one-line description], the intended audience, and the main takeaway. Sequence: open with a recognizable user need, show how the product responds, then close on the clearest benefit and a concise end card. Use 1920x1080 framing, dynamic but purposeful transitions, and a polished visual language suited to the product. Build a self-contained HTML page with no external network assets; make every frame a deterministic function of one seekable time value and support a clean loop. Optional sound may be synthesized in-page with Web Audio. Avoid unsupported claims and decorative motion that obscures the explanation." },
  { id: "product-value-explainer", category: "explainer", aspect: "16:9", prompt: "Goal: Build a compelling 30-second, 16:9 explainer for [product]. Ask me first for the product URL or a one-line description, target audience, and the main benefit. Look: Develop a clear color palette, attractive typography, and a focused visual metaphor. Sequence: Open with the audience's problem, show how the product addresses it, highlight its strongest benefit, and close with a concise invitation to learn more. Motion: Keep each beat lively and easy to follow; optional sound must be generated in-page with Web Audio API. Build: Create a self-contained HTML page whose animation is driven by one time value for scrubbing and looping. Avoid: Unsupported claims, crowded copy, and external media. Check before finishing: Keep the story understandable on first viewing and engaging on repeat." },
  { id: "product-value-walkthrough", category: "explainer", aspect: "16:9", prompt: "Goal: Create a concise animation explaining why [product name] deserves a place in its audience's toolkit.\nAsk me first: Ask who it serves, what problem it addresses, and which verified capability makes the difference.\nLook: Make the problem and solution visually distinct, with a clear, confident design.\nSequence: Show the relevant friction, introduce the product's role, then make the resulting improvement easy to understand.\nBuild: Deliver one self-contained HTML page with motion driven by a shared time value for clean scrubbing and looping.\nAvoid: Generic praise or benefits that the supplied facts cannot support." },
  { id: "reading-habit-explainer", category: "explainer", aspect: "16:9", prompt: "Goal: Make a one-minute educational explainer for [reading service]. Ask me first for a product URL or concise description, its audience, and its main reading benefit. Look: Use warm editorial typography, calm colors, and simple book-inspired imagery. Sequence: Introduce a common reading challenge, explain how the service helps, illustrate a typical moment of use, and close with a clear next step. Motion: Keep transitions gentle and narration-friendly; if sound is desired, synthesize it in-page with Web Audio API rather than using voice files. Build: Create a self-contained HTML page with one time value driving all frames for scrubbing and looping. Avoid: Claims not supplied by me and external network assets. Check before finishing: Ensure the main explanation works without audio." },
  { id: "recursion-style-shift-explainer", category: "explainer", aspect: "16:9", prompt: "Make a 1920x1080 explainer about recursion in which each successive explanation (base case, call stack, self-similarity, unwinding) switches to a sharply different visual genre, such as blueprint, retro terminal, paper cutout or nature documentary. Keep it fast, witty and self-referential: frames can nest inside themselves and the explainer can call itself. Drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "token-bucket-explainer", category: "explainer", aspect: "1:1", prompt: "Explain a token bucket rate limiter through a clean square canvas animation at 1080x1080. Show tokens accumulating at a steady refill rate, requests consuming tokens, and excess requests being delayed or rejected when the bucket is empty. Use simple labels, an intuitive visual metaphor, and a brief, accurate explanation of capacity and refill behavior. Implement with canvas only and no libraries. Make every frame a pure function of one time value so the animation can be scrubbed and looped in BurnGuard's self-contained HTML preview." },
  { id: "whiteboard-video-workflow", category: "explainer", aspect: "16:9", prompt: "Goal: Explain a simple process for turning a video idea into a finished motion piece, in a friendly whiteboard-explainer style.\nAsk me first: Ask for the intended audience and the actual steps or tool details to teach; do not invent a workflow.\nLook: Clean drawn lines, clear labels, and a few restrained accent colors.\nSequence: Present one prompt, show how it guides a visual plan, then reveal the resulting short film concept.\nMotion: Draw each diagram and label in as it becomes relevant, keeping the teaching pace easy to follow.\nBuild: Create a self-contained 16:9 HTML page whose animation is controlled by one time value for scrubbing and looping.\nAvoid: Naming specific AI models or relying on external assets." },
  { id: "yellow-line-rule-explainer", category: "explainer", aspect: "16:9", prompt: "Goal: Explain how the [First & 10 Yellow Line] works in a clear 16:9 motion graphic.\nAsk me first: Confirm the sport, the exact rule, and any terminology or visual conventions that must be respected.\nLook: Use a simple field diagram, a contrasting first-down marker, and clean labels.\nSequence: Establish the starting position, show the required distance, animate a play or movement toward the marker, then explain the outcome for success and failure.\nMotion: Move the line and relevant markers in sync with the demonstration.\nBuild: Create a self-contained HTML page controlled by one shared time value for scrubbing and looping.\nAvoid: Ambiguous field markings or unverified rule details." },
  { id: "dynamic-information-display", category: "ui-motion", aspect: "16:9", prompt: "Create a 30-second motion piece that displays [specific information: day, time, schedule, or similar]. The information should be the visual hero, revealed through dynamic typography and motion design. Use a high-energy visual style with confident motion curves and bright accents. Add optional background music or sound design, synthesized in the page with the Web Audio API, that complements the pacing. The piece should feel contemporary and exciting while keeping the information legible throughout. Cycle or end decisively based on whether this loops or plays once. 1920×1080." },
  { id: "five-scroll-story-sections", category: "ui-motion", aspect: "16:9", prompt: "Build a self-contained webpage with five distinctly composed, scroll-driven sections. Choose a fitting subject and narrative context yourself, and make each section explore a different layout or motion idea while preserving a shared visual system. Use scrolling to reveal, transform, or connect content; keep text readable and transitions responsive to scroll position. Target a 1920x972 preview canvas, with all effects rendered locally and no external assets. Ensure the entire experience works as one HTML page." },
  { id: "poster-breakframe-motion", category: "ui-motion", aspect: "16:9", prompt: "Goal: create a cinematic moment where a poster or rectangular element breaks free and transforms.\n\nAsk first: is this a photographic poster, graphic design, or typography? What mood do you want—playful, dramatic, surreal?\n\nSequence: establish the poster in a frame. Show tension or strain at the edges. A break moment—particles, shatter, warp. The escaped element dissolves, morphs, or launches into a new form.\n\nLook: use depth and lighting to make the break feel real. Layering is key—foreground frame, poster, explosion layer, background reveal.\n\nBuild: can be painted on a 3D plane with WebGL distortion, or drawn on canvas with particle effects. Choice depends on your aesthetic.\n\nCheck: does the moment feel surprising and satisfying? Does the new form make visual sense?" },
  { id: "premium-badge-unlock", category: "ui-motion", aspect: "4:3", prompt: "Goal: Animate a badge-unlock screen using the supplied design reference.\nAsk me first: Request the design frame or a clear description, including available artwork, lighting, typography, and layout.\nLook: Preserve the reference faithfully; add only motion. The badge should feel like a crafted solid object, highlighted by a brief burst of gold particles.\nSequence: 1. Establish the interface exactly as designed. 2. Reveal the badge with a premium celebratory accent. 3. Let it tilt toward the pointer with restrained, physically plausible response. 4. Settle into a clean unlocked state.\nMotion: Make the interaction quick and smooth, with controlled easing and no springy bounce.\nBuild: Create a self-contained HTML page at 1408x1080, driven from a single time value for scrubbing and looping. Optional sound may use in-page Web Audio API only.\nAvoid: Redesigning the supplied frame or introducing external assets.\nCheck before finishing: Ensure the original layout stays intact and pointer tilt remains subtle." },
  { id: "talking-head-edit-promo", category: "ui-motion", aspect: "16:9", prompt: "Goal: transform a raw interview into a tight, shareable edit that holds attention.\n\nAsk first: what's the key message or quote you want to highlight? How long is the source clip?\n\nLook: sync subtitles with speech (not full transcription—only key phrases). Add graphics that visualize or reinforce the message. Pacing should accelerate during engaging moments, breathe during reflective ones.\n\nSequence: find the strongest opening statement. Trim dead air and tangents. Pull out three to five quotable moments and emphasize them with motion. Synthesize optional music in the page with the Web Audio API to match the mood and the speaker's tone.\n\nBuild: sound design matters—music under, subtle effects for graphic pops, clean audio ducking.\n\nCheck: does someone new to the content understand the main point in under 60 seconds? Is it something people might share?" },
  { id: "beat-synced-lyric-motion", category: "typography", aspect: "16:9", prompt: "Ask me first for the song's lyrics with rough timestamps, its tempo, and the mood. Build a 1920x1080 kinetic lyric piece where every word lands exactly on the vocal and every accent hits the beat, treating it like the strongest entry in a motion designer's portfolio. Vary the type treatment line by line (scale, masks, splits, rhythm-driven layout) while keeping one coherent look. Drive every frame from a single time value so it can be scrubbed and loops cleanly; if you add sound, generate a beat in-page with the Web Audio API." },
  { id: "kinetic-type-craft-reel", category: "typography", aspect: "1:1", prompt: "Goal: Create an expressive kinetic-typography showreel in a 1:1 square composition.\nAsk me first: Request the exact words, language, tone, and any preferred type styles.\nLook: Make typography the main event, with a carefully composed visual system and strong contrast.\nSequence: Reveal the words in several distinct treatments, building from a simple opening to a confident final statement.\nMotion: Explore shifts in scale, spacing, alignment, masking, and letterform transformation while keeping every word readable.\nBuild: Create one self-contained HTML page for the browser preview. Drive each frame from one time value for clean scrubbing and looping; render type locally.\nAvoid: Model self-references, excessive decoration, and unreadable type effects.\nCheck before finishing: Confirm the supplied wording is exact and the final composition reads at square aspect." },
  { id: "kinetic-typography-architecture", category: "typography", aspect: "1:1", prompt: "Create a 20-second kinetic piece where each line of text becomes a structural element. Build from a spoken passage: the words physically construct the frame as they appear. Early phrases become architectural components—supports, openings, and platforms—that hold later content. Use serif and grotesque typefaces to communicate load and purpose. The final statement rests visibly on what earlier words assembled.\n\nArchitectural mapping: initial words form horizontal spans, middle passages create vertical supports, final lines settle onto a complete platform. Motion should feel like gravity and structural logic, not dance choreography.\n\nRender as 1080×1080 at 60fps, deterministic frame-by-frame seeking. Use SVG or Canvas with embedded fonts. Dark background, warm paper tone, structural gold accent. No distressed styling, protest aesthetics, or decorative excess. The composition must remain readable throughout and should hold still for one moment of earned rest before concluding. Cycle seamlessly at 20 seconds for looping." },
  { id: "kinetic-typography-showreel", category: "typography", aspect: "16:9", prompt: "Design a 15-second kinetic type showreel where text is the primary vehicle for motion and emotion. Let words transform, scale, rotate, and flow across the frame. Pair typography with color shifts and spatial transitions that enhance meaning.\n\nFocus on: Readable, bold typefaces. Motion that feels organic and purposeful—avoid random effects. Pacing that matches the rhythm of the words themselves. Consider pairing with subtle sound design that complements the type motion." },
  { id: "playful-chaos-type-short", category: "typography", aspect: "9:16", prompt: "Create a fast, playful 9:16 motion short with deliberately absurd visual collisions, oversized kinetic words, abrupt scale changes, and surprising graphic interruptions. Give it a distinct point of view about [launch or topic] without impersonating a company, model, or creator. Build escalating visual beats with enough contrast and timing for each joke to register, then finish on a striking final image. Implement it as a single self-contained HTML page at 1080x1920, with all animation derived from one time value for scrubbing and looping. Optional rhythmic cues must be synthesized in-page with Web Audio API. Keep the chaos art-directed: clear focal points, legible type, and no external media." },
  { id: "cozy-seasonal-train-journey", category: "story", aspect: "16:9", prompt: "Create a cozy 16:9 animated vignette viewed from inside a quiet train carriage. Keep a steaming cup of coffee on the table in the foreground while the landscape outside the window gradually passes through spring, summer, autumn, and winter. Use an elegant storybook travel-poster mood, warm interior lighting, layered scenery, and gentle parallax without imitating a specific film or artist. Build a self-contained 1920x1080 HTML page with a single time-driven animation that scrubs smoothly and loops from winter back to spring." },
  { id: "fiery-samurai-kata-canvas", category: "story", aspect: "4:3", prompt: "Build a samurai figure entirely in code (canvas or SVG, no images) who stays on one spot and flows through a kata of striking stances, spins, lunges and sword cuts. Surround the routine with fire: blazing blade trails, embers and heat glow that react to each move. Frame it at 1920x1292, drive the whole sequence from one time value so it can be scrubbed and loops cleanly, and make every pose read as powerful and deliberate." },
  { id: "handmade-surreal-music-film", category: "story", aspect: "16:9", prompt: "Goal: Create a 60-second surreal music-film sequence with a tactile handmade feel and a playful, prop-driven visual world.\nAsk me first: Ask for the theme, any modern cultural references to include, and whether to generate a simple original in-page sound bed.\nLook: Use crafted miniature sets, bold color, collage-like transformations, expressive everyday objects, and rhythmic visual surprises. Make the aesthetic original rather than imitating a named artist, song, or existing video.\nSequence: Shape the piece as a series of escalating visual vignettes: introduce an ordinary object, transform it unexpectedly, build toward a lively ensemble, then land on a memorable final tableau.\nMotion: Let transformations and cuts follow the beat; use playful stop-start gestures and smooth morphs to vary the energy.\nBuild: One self-contained HTML page at 1280x720, animated from a single time value for clean scrubbing and looping. If sound is included, synthesize it in-page with Web Audio API.\nAvoid: Existing characters, recognizable shots, borrowed melodies, external audio, and imitation of a specific creator.\nCheck before finishing: Ensure the piece has a clear progression and its own visual identity." },
  { id: "intricate-bicycle-pelican", category: "story", aspect: "16:9", prompt: "Goal: Create an exceptionally detailed animated scene of a pelican riding a bicycle, framed at 16:9.\nAsk me first: Ask whether the user prefers a particular setting, mood, or illustration style; otherwise invent a charming scene.\nLook: Make the bird, bicycle, and environment precise, expressive, and visually rich. Use any combination of canvas, SVG, CSS, or WebGL that suits the design.\nSequence: Introduce the setting, show the pelican mounting and pedaling, add small environmental details and a playful moment, then finish on a pleasing held pose.\nMotion: Animate wheel rotation, balance, feathers, and surroundings with convincing coordination and subtle secondary movement.\nBuild: Create a single self-contained HTML page for browser preview. Derive the whole animation from one time value so it scrubs and loops smoothly; keep all assets in-page.\nAvoid: Rushing through detail, visual clutter, and remote resources.\nCheck before finishing: Inspect the anatomy and bicycle mechanics, and ensure the loop joins without a jump." },
  { id: "letter-tile-character-short", category: "story", aspect: "9:16", prompt: "Invent a short story that gently promotes [app name] - or simply matches its spirit - built to earn attention on social feeds. Then animate it in 1080x1920 with hand-written WebGL and JavaScript (no external libraries), aiming for animated-feature polish: expressive characters (for example, game tiles or objects from the app's world), warm lighting and clear story beats. Ask me what [app name] does before writing the story. Keep everything generated in code and drive the whole scene from one time value so it scrubs and loops." },
  { id: "life-cycle-loop-reel", category: "story", aspect: "16:9", prompt: "Create a dynamic 20-second, 16:9 motion piece that follows one recognizable person through childhood, adolescence, daily working life, family years, old age, and death, then transforms the final image into the opening childhood pose for a seamless loop. Make the changing years legible through evolving silhouette, setting, and a few evocative objects; keep the same individual visually identifiable. Treat it as a concise showreel of confident animation craft, with expressive transitions and a thoughtful emotional arc. Build a self-contained HTML page for BurnGuard's preview, with every frame driven by one timeline value for precise scrubbing and looping. Optional sound may be synthesized in-page with Web Audio API only." },
  { id: "lighthouse-silent-short", category: "story", aspect: "16:9", prompt: "Goal: Invent a 45-second wordless short about a lighthouse keeper, framed in 1920x816 widescreen.\nLook: Build a cinematic atmosphere through light, weather, and carefully composed silhouettes.\nSequence: Create a visual narrative with a clear emotional change; let sound carry part of the meaning without dialogue or captions explaining it.\nMotion: Use restrained camera movement and deliberate shifts in light. Generate any sound in-page with Web Audio API and synchronize it to the animation.\nBuild: Make one self-contained HTML page controlled by a shared time value so the story can be scrubbed and looped.\nAvoid: Spoken words, external audio, and unexplained decorative action." },
  { id: "mecha-vehicles-combine-transform", category: "story", aspect: "9:16", prompt: "Create a vertical 720x1280 anime-style 3D sequence in which three vehicles - say a jet, a tank and a drill car - race in, transform and lock together into one heroic giant robot, in the spirit of classic mecha shows. Render it with WebGL using toon shading, bold outlines and speed lines, and stage it with dramatic camera cuts: panels sliding, limbs unfolding, parts clamping with sparks and impact flashes, ending on a low-angle hero pose. Build every model from simple primitives in code and drive the whole sequence from one time value so it scrubs and loops cleanly." },
  { id: "mind-blowing-animated-short-film", category: "story", aspect: "16:9", prompt: "Make a 4-minute, 1280x720 animated short meant to leave the viewer stunned: an original story with a clear arc - setup, rising tension, turning point and an emotional payoff - told mostly through images rather than text. Pick one bold visual language and commit to it, with deliberate shot design, lighting changes that carry mood, and transitions that feel motivated. Optionally add a score generated in-page with the Web Audio API that starts on a click. Drive the entire film from one time value so it can be scrubbed, and add a simple timeline with chapter markers." },
  { id: "paper-cut-home-theatre", category: "story", aspect: "9:16", prompt: "Goal: Create a 30-60 second vertical 9:16 short exploring what makes a place feel like home.\nLook: Layered paper cut-outs, theatrical shadows, soft depth, and a gentle, intimate mood.\nSequence: Let a small setting gradually gain signs of comfort and belonging, then resolve in a quiet emotional image.\nMotion: Animate paper layers and light with measured parallax. Optional fitting sound must be generated in-page using Web Audio API.\nBuild: Make a self-contained HTML page with visuals and audio cues driven by one shared time value for reliable scrubbing and looping.\nAvoid: Dialogue, external media, and overly busy movement." },
  { id: "pixel-moon-festival-night", category: "story", aspect: "16:9", prompt: "Goal: Create a warm pixel-art animated scene inspired by [holiday or seasonal celebration]. Ask me first which cultural details or symbols to include; if none are specified, use broadly recognizable, respectful visual cues without relying on unverified specifics.\nLook: Compose a 16:9 evening landscape with a luminous moon, quiet rooftops or hills, and a small number of festive details. Use a limited pixel palette, crisp edges, layered parallax, and a cozy contrast between deep night colors and warm lights.\nSequence: Begin with a still, spacious night view; gradually reveal subtle activity and glowing seasonal accents; finish on a balanced tableau that can return naturally to its opening.\nMotion: Animate clouds, distant lights, or a small focal element with restrained, rhythmic movement. Keep the pixel grid consistent and avoid smooth effects that blur its crafted texture.\nBuild: Make one self-contained HTML page, with all motion controlled by a single absolute time value for accurate seeking and looping. Optional sound may be generated in-page with Web Audio API. Do not use external imagery or network assets.\nAvoid: Overcrowding, stereotyped symbols, inconsistent pixel scale, excessive flashing, and explanatory text that dominates the scene.\nCheck before finishing: Verify the visual details suit the celebration selected, preserve sharp pixels throughout playback, and form a seamless loop." },
  { id: "pixel-wizard-crypto-scene", category: "story", aspect: "16:9", prompt: "Goal: Create an original pixel-art fantasy animation that combines a wizard motif with cryptocurrency-inspired imagery.\nAsk me first: Request the visual reference or describe the desired character, palette, and specific crypto symbols or concepts.\nLook: Use a charming retro game aesthetic, crisp pixel edges, limited colors, and imaginative magical effects. Treat coins, ledgers, or network motifs as fictional visual elements.\nSequence: Introduce the wizard, reveal a crypto-themed magical object, then build to a compact spell effect and a satisfying final pose.\nMotion: Use stepped sprite-like movement, glowing pixels, and readable action timing.\nBuild: Make one self-contained HTML page at 1920x1080, with animation derived from one time value for scrubbing and looping. Optional sound can be synthesized in-page with Web Audio API.\nAvoid: Investment advice, real wallet connections, financial promises, or copying a specific existing character.\nCheck before finishing: Confirm the result reads as playful pixel-art fantasy and not a functional financial interface." },
  { id: "retro-space-cartoon", category: "story", aspect: "16:9", prompt: "Goal: Invent and tell a complete short space-adventure story in a 16:9 animated cartoon.\nAsk me first: Ask for any preferred mood, audience age, or story ingredients; if none are supplied, invent an original premise and characters.\nLook: Evoke the expressive craft and color of classic late-20th-century television cartoons while creating an entirely new world and visual identity.\nSequence: Establish a hero and goal, introduce a surprising obstacle, build to a clear turning point, and finish with a satisfying resolution.\nMotion: Animate characters, spacecraft, and cosmic scenery with layered depth, lively poses, and readable staging.\nBuild: Make one self-contained HTML page using canvas, SVG, or WebGL as useful. Drive the complete animation from one time value for scrubbing and looping; no external assets or network access.\nAvoid: Existing franchise characters, recognizable logos, and copied story beats.\nCheck before finishing: Confirm the story can be followed without narration and every major beat reads visually." },
  { id: "sketchbook-creature-story", category: "story", aspect: "16:9", prompt: "Goal: Create a playful, joyful 16:9 animated short using the supplied hand-drawn images as its visual foundation. Ask me for the images first. Preserve their handmade character while arranging them into a surprising little story; add gentle in-page sound made with the Web Audio API if it helps the action. Build one self-contained HTML page and drive all visuals and sound cues from a shared time value for clean scrubbing and looping. Keep the result original, expressive, and pleasant to watch." },
  { id: "stubborn-bug-animated-short", category: "story", aspect: "16:9", prompt: "Goal: a 90-second animated short at 1920x1080 starring a small software bug who does not want to be fixed.\n\nLook: give the bug a lovable, expressive character design and set it inside a stylized world of code lines, editor windows and test runners, using one consistent palette and drawing style.\n\nSequence:\n1. The bug lives happily in a forgotten corner of the code.\n2. A developer's cursor starts hunting it; the bug hides, disguises itself and dodges breakpoints.\n3. The chase escalates through failing tests and stack traces.\n4. Cornered, the bug reveals why it matters to someone.\n5. A gentle, funny ending that resolves the standoff.\n\nMotion: squash and stretch, clear staging, readable beats with pauses for comedy and emotion.\n\nBuild: one self-contained HTML page drawn with SVG or canvas, all scenes driven from a single time value so the film can be scrubbed; optional sound only if generated with the Web Audio API." },
  { id: "sunlight-photon-journey", category: "story", aspect: "16:9", prompt: "Make a wild 20-second 1920x1080 motion piece; the subject is open, and one strong option is the journey of a single photon from [starting point, e.g. the Sun's core] to [destination, e.g. a human eye]. Push the visuals hard: bouncing through the dense plasma, bursting from the surface, racing across black space, then a sudden arrival in close-up, each stage with its own palette and scale shift. Drive every frame from one time value so the piece scrubs and loops, keep it in a single self-contained HTML page, and only add sound if it is synthesized with the Web Audio API." },
  { id: "sunset-seaplane-dogfight", category: "story", aspect: "16:9", prompt: "Create a 16:9 browser-based 3D-inspired animated scene of a dramatic but graceful seaplane chase over the ocean at sunset. Use original aircraft shapes with cream, green, and red accents, towering violet clouds, and shimmering reflections across the water. Let the camera glide between wide scenic views and closer passes, with readable cinematic composition and a calm, poetic sense of motion. Include the exact phrase \"just breathe\" as a brief on-screen title. Do not recreate a named film, character, or artist's signature style. Build the scene in one self-contained HTML page using local code-drawn or procedural graphics, driven by a single time value for scrubbing and looping." },
  { id: "time-near-black-hole", category: "story", aspect: "16:9", prompt: "Goal: Create a contemplative five-minute, 16:9 narrative about time near a black hole. Ask me first for the desired scientific accuracy, emotional tone, and whether captions are wanted. Look: Build an atmospheric space setting with deep shadows, gravitationally bent light, and a restrained luminous palette. Sequence: Introduce a traveler and a distant observer, show their different experiences of passing time, deepen the separation, then conclude with a quiet emotional resolution. Motion: Use slow orbital movement, subtle lensing, and patient transitions. Build: Make a self-contained HTML page with the entire story driven by one time value for scrubbing and looping; optional sound can be generated in-page with Web Audio API. Avoid: External audio, video exports, and presenting speculation as established fact. Check before finishing: Give each story beat enough space to register." },
  { id: "brand-anniversary-celebration-spot", category: "brand-reveal", aspect: "1:1", prompt: "Create a lively 10-second motion graphics piece at 1080x1080 that celebrates the [number]th anniversary of [brand name]. Let the big anniversary number build itself from shapes tied to what the brand makes, burst into confetti or ribbons, then settle on the brand name with a warm thank-you line. Use the brand colors from [one-line brand description] and keep everything in one self-contained HTML page, with every frame driven by a single time value so the spot loops smoothly." },
  { id: "design-tool-brand-reveal", category: "brand-reveal", aspect: "16:9", prompt: "Goal: Create a distinctive 15-second, 16:9 brand reveal for [design tool]. Ask me first for its name, audience, and signature capability. Look: Turn its core design idea into a visual motif, supported by a deliberate palette and confident type. Sequence: Start with raw shapes or fragments, show them becoming useful design elements, then assemble the identity and finish on the tool name. Motion: Make the transformation feel inventive, smooth, and energetic. Build: Use a self-contained HTML page with all frames driven by a single time value for scrubbing and looping. Avoid: Borrowed logos, unsupported superlatives, and decorative motion without meaning. Check before finishing: Ensure the final identity remains legible and memorable." },
  { id: "early-user-thank-you", category: "brand-reveal", aspect: "16:9", prompt: "Goal: Make a lively 15-second 16:9 thank-you piece celebrating the first 100 users of [product name].\nAsk me first: Request the product identity, any approved logo and colors, and whether the milestone should be written as a number or phrase.\nLook: Warm, celebratory, and polished, with a distinct branded finish.\nSequence: Build anticipation, reveal the 100-user milestone, express genuine appreciation, then close with the product mark.\nMotion: Use lively, considered transitions. Any optional sound must be generated in-page with Web Audio API.\nBuild: Create one self-contained HTML page animated from a shared time value for clean scrubbing and looping.\nAvoid: Unsupported promises, third-party branding, or a generic corporate template." },
  { id: "oscilloscope-studio-identity", category: "brand-reveal", aspect: "16:9", prompt: "Goal: Introduce [studio name] in a 16:9 motion identity inspired by oscilloscope displays. Ask me first for the studio's creative focus, name, and preferred colors. Look: Draw luminous waveforms and fine traces against a dark field, balancing analog character with contemporary typography. Sequence: Let a signal emerge, evolve into patterns that suggest the studio's practice, then settle into its name or mark. Motion: Shape and phase-shift the waveforms with smooth, purposeful rhythm. Build: Create a self-contained HTML page with all frames controlled by one time value for scrubbing and looping; optional tones may be synthesized via Web Audio API. Avoid: External audio or decorative signals unrelated to the identity. Check before finishing: Keep the studio name clear in the final frame." },
  { id: "personal-creator-promo", category: "brand-reveal", aspect: "16:9", prompt: "Goal: Create a personal 15-second promo for [your name] in a 16:9 frame. Ask me first what I make, who it is for, and one quality or idea I want people to remember. Look: Develop a visual signature that feels specific to my work, using considered type, color, and graphic motifs. Sequence: Open with a striking introduction, reveal the work or point of view through a few compact moments, and close on my name with a clear invitation to connect or explore. Motion: Keep the progression bold, coherent, and human. Build: Make a self-contained HTML page with one time value driving every frame for scrubbing and looping. Avoid: Empty boasts, borrowed identities, and external media. Check before finishing: Make the introduction feel authentic and recognizable." },
  { id: "riso-print-studio-intro", category: "brand-reveal", aspect: "16:9", prompt: "Make a 1280x720 intro about [studio name and a line on what you do] in a risograph print style. Limit the palette to two or three spot inks such as fluoro pink, blue and yellow, overprinted with multiply blending, slight misregistration, halftone dots and paper grain, and animate shapes and type as if each ink layer is being pulled through the press. Drive every frame from one time value so it scrubs and loops cleanly in one self-contained HTML page with no external assets." },
  { id: "slow-assembly-logo-reveal", category: "brand-reveal", aspect: "16:9", prompt: "Build a 1920x1080 logo reveal for [brand name] that takes its time: scattered shapes, strokes and particles drift in, slowly find their places, and only in the final beat lock together into the [logo description or uploaded logo]. Let the tension build through restrained easing, light parallax and a gradual sharpening of focus, then give the finished mark a brief hold with a soft glow. Fake the focus pull cheaply, with the opacity and scale of a few pre-blurred layers drawn once, instead of filtering the whole frame every frame, so it stays smooth on modest laptops. Drive every frame from one time value so the piece can be scrubbed and loops cleanly, and keep it to a single self-contained HTML page with no external assets." },
  { id: "studio-case-study-intro-reel", category: "brand-reveal", aspect: "16:9", prompt: "Make a high-energy 15-second, 1920x1080 motion graphics reel that launches [studio name] and shows off the work it does. Ask me first for the case study material (project names, one-line outcomes, key visuals or colors) and pull the strongest highlights from it. Treat it as the studio's intro showreel: rapid but readable beats, bold kinetic type and a confident studio name reveal at the end. Don't invent clients or results that aren't in the material, and drive every frame from one time value so it scrubs and loops cleanly." },
  { id: "art-exploration-3d-game", category: "interactive-3d", aspect: "16:9", prompt: "Goal: create an interactive 3D space inside [painting name] where the user walks around exploring.\n\nAsk first: what objects are the player finding? [Animal name] or other specific subjects—what makes them interesting?\n\nLook: respect the painting's color palette and mood. The 3D geometry can be stylized or abstract, but it should feel grounded in the artwork's world.\n\nBuild: keyboard or pointer controls for movement. Gentle camera, readable spaces. When the user finds a target, reward them with a particle effect, sound, or visual pop.\n\nTechnique: hand-written WebGL in the page for 3D, with no external libraries. Keep performance smooth even on modest devices.\n\nCheck: is exploration rewarding? Do spaces feel intentional? Is the painting's essence preserved?\n\nBuild it in steps: first save a small working version, then extend it in a few small edits." },
  { id: "bass-music-visualizer", category: "interactive-3d", aspect: "1:1", prompt: "Goal: Build a square, music-reactive visual experience for a 140 BPM UK dubstep-inspired track.\nAsk me first: Ask whether to synthesize a simple original in-page bass-and-drum loop or animate to a supplied beat description.\nLook: Use dark, high-contrast abstract forms, sharp rhythmic cuts, and bass-responsive pulses. Aim for an original UK bass music atmosphere rather than copying a named musician or track.\nSequence: Start sparse, introduce the low-end pulse, layer in syncopated visual accents, then build to a final high-energy pattern.\nMotion: Synchronize graphic movement to a steady 140 BPM grid; distinguish deep bass hits from lighter rhythmic details.\nBuild: Create one self-contained HTML page at 1080x1080. Drive every visual frame from one time value for scrubbing and looping. Generate any optional audio in-page with Web Audio API.\nAvoid: External music files, borrowed melodies, or imitation of a specific artist.\nCheck before finishing: Confirm the rhythm remains clear and the visuals stay legible at square aspect ratio.\n\nBuild it in steps: first save a small working version, then extend it in a few small edits." },
  { id: "collision-music-machine", category: "interactive-3d", aspect: "16:9", prompt: "Goal: Build a 45-second kinetic machine that performs an original musical phrase, with every note caused by a visible collision.\nAsk me first: Ask for a preferred mood or instrument character; otherwise choose a cohesive sound palette.\nLook: Show a clear mechanical or geometric system whose moving parts make cause and effect easy to follow.\nSequence: Introduce the machine, start its motion, develop a rhythmic pattern through successive impacts, then resolve with a final accented collision.\nMotion: Make each impact visible and precisely associated with its sound. Give objects believable trajectories and distinct visual responses.\nBuild: Create one self-contained HTML page. Use one shared time value to drive motion and collision events so the piece scrubs and loops deterministically. Generate all sound in-page with Web Audio API; no external audio.\nAvoid: Notes that sound without a visible impact or collisions without an audible result.\nCheck before finishing: Scrub across every event and confirm timing, causality, and the 45-second ending.\n\nBuild it in steps: first save a small working version, then extend it in a few small edits." },
  { id: "data-center-3d-tour", category: "interactive-3d", aspect: "16:9", prompt: "Goal: give an immersive tour of what happens inside a [type] data center.\n\nAsk first: which systems are most interesting to show? Servers, cooling towers, power distribution, fiber routes, or monitoring?\n\nLook: scale and complexity. Use lighting to show activity—glow, flicker, or color shifts. Overlay diagrams and labels to explain infrastructure.\n\nSequence: start at the entrance, move through key zones (server rows, cooling, power, security). Pause at each section with a brief explanation. End with a view of the whole system.\n\nBuild: hand-written WebGL in the page for 3D geometry, with no external libraries. Ground the layout in how real data halls are arranged. Animated elements (fans spinning, lights pulsing) show the space is alive.\n\nInteraction: WASD or mouse to navigate. Click zones for labels or details.\n\nCheck: does scale feel right? Can someone understand the layout? Is it technically interesting without becoming incomprehensible?\n\nBuild it in steps: first save a small working version, then extend it in a few small edits." },
  { id: "interactive-3d-model", category: "interactive-3d", aspect: "16:9", prompt: "Build a self-contained 3D viewer for [object: aircraft, vehicle, machinery, or similar], written in plain WebGL in the page with no external libraries. Model it as a stylized low-poly object assembled in code from a few dozen simple primitives (boxes, cylinders, cones, wedges) so the source stays compact, and give each part a material color. Light it with a key light, a soft fill and simple diffuse plus specular shading so the forms read as dimensional on both light and dark backgrounds. Open on an establishing three-quarter view of the whole object with a slow idle turntable; drag to orbit, use the wheel or a pinch to zoom, ease every camera move with damping, and double-click to return to the opening view. Keep rendering smooth on modest laptops. Build it in steps: first save a minimal working page with one lit, rotating box and the orbit controls, then add the remaining parts in a few small edits. 1920x1080." },
  { id: "moonlit-river-interactive-scene", category: "interactive-3d", aspect: "16:9", prompt: "Goal: Build a memorable 30-second interactive motion scene for the browser preview, expressing a personal, evocative theme rather than relying on supplied references. Ask me first for [mood or interests] if personalization would help; otherwise choose a coherent concept yourself.\nLook: Create a moonlit river setting with layered depth, reflective water, atmospheric architecture, and restrained luminous accents. Treat the scene as an authored visual experience, balancing detail with readable silhouettes and calm negative space.\nSequence: Open with a broad establishing view, guide attention toward one striking riverside focal point, reveal smaller environmental details as the viewpoint moves, then return to a composed wide finale. Let the transitions unfold at a measured pace across the full 30 seconds.\nMotion: Add intuitive pointer or keyboard interaction that gently changes viewpoint or reveals scene details without interrupting playback. Keep movement smooth and purposeful.\nBuild: Implement as one self-contained HTML page using CSS, JavaScript, and canvas, SVG, or WebGL as useful. The animation must derive from a single absolute time value for reliable scrubbing and looping. Optional sound may be generated in-page with Web Audio API; use no external assets or network access.\nAvoid: Generic visual-effects overload, abrupt camera changes, unreadable contrast, and controls that obscure the scene.\nCheck before finishing: Test the entire timeline and each interaction, including returning to the opening state; ensure the scene remains legible and polished at the requested 16:9 aspect ratio.\n\nBuild it in steps: first save a small working version, then extend it in a few small edits." },
  { id: "music-sync-3d-ball-bounce", category: "interactive-3d", aspect: "16:9", prompt: "Create a 3D physics scene where a ball falls and bounces through a dynamic environment. Sync every bounce and object interaction to music beats. As the ball collides with elements, light them up in rhythm with the soundtrack—creating a satisfying audio-visual connection.\n\nBuild: Render with WebGL or canvas code written in the page, with no external libraries. Compose an original instrumental loop with the Web Audio API and design objects that respond visually to it. Add subtle humor through unexpected bounces or playful object behavior. Motion: Gravity-driven physics feel authentic, but fine-tune the bounce height and timing to lock perfectly with the audio.\n\nBuild it in steps: first save a small working version, then extend it in a few small edits." },
  { id: "pixel-duel-card-battler", category: "interactive-3d", aspect: "16:9", prompt: "Build a playable one-on-one collectible card battler in a crisp pixel art style at 1280x720: two heroes with health, a mana curve that grows each turn, a hand of minion and spell cards, a board to play minions onto, and attacks resolved by dragging. Give the opponent a simple but sensible AI, and add juicy feedback - card hover lifts, attack lunges, damage numbers, screen shake on big hits. Draw every sprite and card frame in code with nearest-neighbor scaling, keep the rules small but complete enough for a satisfying match, and finish with win and lose screens plus a restart button. Don't stop to ask questions; make sensible design calls and deliver the best version you can.\n\nBuild it in steps: first save a small working version, then extend it in a few small edits." },
  { id: "ambient-backlight-media-glow", category: "interface-style", aspect: null, prompt: "Add an ambient backlight glow to [which media, e.g. the product screenshot]: behind the element, render a copy of it that is blurred around 40px, slightly scaled up and boosted in saturation, so the image seems to spill its own colors onto the page.\nUse an inline SVG filter (blur plus saturate, composited under the original) or a blurred duplicate layer, and keep the original crisp on top with rounded corners.\nOn hover, let the glow brighten and spread a little over about 300ms; on touch, keep it at the resting level.\nWith prefers-reduced-motion, keep the glow static with no hover change, and make sure nearby text never sits on the brightest part of the halo.\nUse plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "animated-connector-light-beam", category: "interface-style", aspect: null, prompt: "Add animated connector beams to [which section, e.g. the integrations section]. Arrange several small icon tiles around a central hub and connect each one to the hub with a faint curved SVG path computed from the centers of the two elements. Along every path, run a short bright gradient segment that travels from tile to hub over about two seconds, with staggered start times so the pulses feel alive. Recalculate the curves whenever the container or any tile changes size or position. Treat the beams as decoration and describe the connections in text nearby. With prefers-reduced-motion, show the paths with a static soft glow instead of moving pulses. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "animated-dither-pattern-background", category: "interface-style", aspect: null, prompt: "Add an animated dither pattern to [where to apply it, e.g. the hero background]: a two-color field (page background plus one accent) where a smooth underlying shape such as rolling waves, a glowing sphere or soft noise is rendered through a dither so it reads as crisp retro pixels.\nWrite it as a WebGL fragment shader with uniforms for the base shape, dither type (ordered Bayer matrix or random), pixel size in screen pixels, and scale and rotation of the shape; the pixel grid stays locked to the screen while the shape moves slowly underneath.\nLet the pointer gently pull the shape on hover.\nWith prefers-reduced-motion, render a single still frame; keep the dither low-contrast behind any text.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "animated-grid-swap-layout", category: "interface-style", aspect: null, prompt: "Apply an animated grid swap to [which grid, e.g. the product showcase grid]. Lay the items out in a CSS grid with one large featured cell and several small ones; when a small item is clicked, measure every item, exchange the clicked item's grid area with the featured item's, then animate each item from its old box to its new one using transforms and a FLIP approach over about 600ms. Make each item a button with a clear focus style so the swap also works from the keyboard, and keep the grid's overall size fixed during the move. With prefers-reduced-motion, swap the positions instantly. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "animated-ring-progress-gauge", category: "interface-style", aspect: null, prompt: "Add an animated ring gauge to [which stat, e.g. the uptime figure]. Draw a circular SVG track with a thicker colored arc on top whose length comes from a value clamped between a minimum and maximum, guarding against equal bounds, and print the percentage in the middle. When the gauge scrolls into view, sweep the arc from zero to its value over about one second with an ease-out curve while the number counts up in step. Expose the value with a meter or progressbar role and a text label, and only show real figures, never a fake timer. With prefers-reduced-motion, render the final arc and number immediately. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "async-crossfade-page-transition", category: "interface-style", aspect: null, prompt: "Add smooth page transitions to [which links, e.g. the main navigation]: intercept internal link clicks, update the URL with the History API, and swap the main content without a full reload.\nKeep the old view on screen while the new one is prepared, then crossfade them over about 0.5s with a slight upward drift on the incoming view; block extra clicks until the swap settles and handle the back and forward buttons the same way.\nAfter each change, move focus to the new page heading and update the document title so keyboard and screen reader users know where they are.\nUnder prefers-reduced-motion swap instantly, and let external links, new-tab clicks and modified clicks behave normally.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "audio-reactive-orb-visualizer", category: "interface-style", aspect: null, prompt: "Add an audio-reactive glowing orb to [where to apply it, e.g. the hero section], drawn on a WebGL or 2D canvas as a softly lit sphere whose surface bulges into spikes.\nLet the visitor pick a local audio file or press play on a bundled synthesized tone; feed it through the Web Audio API analyser and map low frequencies to overall pulse size and highs to spike sharpness, smoothed so the orb breathes rather than jitters.\nAround it, place two or three small draggable info panels that drift and settle with gentle momentum.\nShow honest states (no audio, loading, playing, paused) with labeled play and pause buttons, never autoplay sound, and under prefers-reduced-motion keep the orb still with a subtle brightness change only.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "aurora-glow-background", category: "interface-style", aspect: null, prompt: "Add an aurora glow background to [where to apply it, e.g. the hero section]: two or three large, heavily blurred bands of teal and violet (or accent colors from the page palette) layered over a dark base.\nAnimate the bands so they drift and stretch very slowly, about a twelve-second cycle with ease-in-out, overlapping where they meet to create soft new hues.\nThe aurora is pure decoration: keep it on its own layer behind the content, never tie meaning to it, and make sure headline and body text keep strong contrast at every moment of the cycle.\nUnder prefers-reduced-motion, freeze the bands in a pleasing still arrangement; the content must read exactly the same with or without the motion.\nUse plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "aurora-launch-hero-section", category: "interface-style", aspect: null, prompt: "Add a product launch hero to [where to apply it, e.g. the top of the landing page], stacked vertically as a small eyebrow label, a very large headline, a one-line supporting sentence and a primary call-to-action button.\nBehind the content, layer two or three blurred, semi-transparent color bands taken from the page palette that slowly drift and shift hue over 15-25 seconds, like an aurora; keep the aurora purely decorative (aria-hidden) and below the text in stacking order.\nGive the button a gentle brightness lift on hover and a clear focus ring, and keep enough contrast between the headline and the glow at every moment.\nWith prefers-reduced-motion, freeze the aurora into a static gradient.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "auto-rolling-word-ticker", category: "interface-style", aspect: null, prompt: "Add an auto rolling word to [which headline, e.g. the hero title], rotating through [list of words].\nEvery 2.5 seconds, the current word slides up and fades out while the next one rolls in from below over about 300 ms, inside a clipped slot whose width eases to fit each word.\nPause the rotation on hover, focus, when the element is off screen or the tab is hidden, and provide a small pause/play toggle so viewers can stop it; handle a one-item list without errors.\nKeep the headline meaningful as static text for screen readers rather than announcing every change, and with prefers-reduced-motion show the first word without rotating.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "bayer-dither-ripple-background", category: "interface-style", aspect: null, prompt: "Add a dither ripple background to [where to apply it, e.g. the landing page backdrop]: a quiet two-tone field rendered through an ordered 4x4 or 8x8 Bayer matrix, so slow noise underneath shows up as crisp pixel patterns.\nOn each click or tap, convert the pointer position to canvas pixels (flipping y), store it with a timestamp in a ring buffer of about ten slots, and have the shader send an expanding ring from each point that brightens the dither and fades over roughly two seconds.\nKeep the pattern low contrast and let clicks still reach buttons and links above the canvas.\nWith prefers-reduced-motion, keep the dither still and skip the ripples.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "bento-feature-grid-section", category: "interface-style", aspect: null, prompt: "Add a bento-style feature grid to [where to apply it, e.g. the features section]: four to six cards of mixed sizes on a CSS grid, some spanning two columns or rows, each with a title, a short line and a link.\nGive each card its own small animated backdrop drawn in the page (a slow gradient shift, a looping list, a tiny chart or a mini calendar) in the existing palette.\nOn hover or keyboard focus the card lifts slightly and its call-to-action slides up into view; on touch and small screens the call-to-action is always visible, so nothing depends on hover.\nCollapse to a single column on narrow screens, and under prefers-reduced-motion stop the backdrops and keep the cards static.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "blend-mode-color-shift-section", category: "interface-style", aspect: null, prompt: "Apply a blend mode color shift to [which sections, e.g. the feature sections]: each section owns a background color, and a few large colored shape layers set to mix-blend-mode (multiply or difference) slide across as that section scrolls into view.\nDrive the slide from scroll position over roughly the first 400px of each section, moving the layers along a different axis per section so transitions feel varied, and let the blended overlap produce the in-between colors.\nKeep text on a layer above the blend so it always renders in its own color with readable contrast, and test the darkest blend result against body text.\nWith prefers-reduced-motion, switch the section colors with a short fade and no sliding layers.\nBuild it with plain HTML, CSS and vanilla JavaScript using requestAnimationFrame or IntersectionObserver, with no external libraries, CDNs, fonts or network assets." },
  { id: "blinds-mask-image-transition", category: "interface-style", aspect: null, prompt: "Add a blinds-style mask transition between the full-screen images in [which section, e.g. the image chapters]. Build an SVG mask with a viewBox 100 units wide and a height matched to the viewport ratio, filled with horizontal strips; as the user scrolls, open each strip by moving its top and bottom edges apart by different amounts, slightly staggered, so the next image appears through widening slats. Offer a grid variant where square tiles grow from their centers in a diagonal sequence. Scrub everything with scroll and rebuild the mask on resize. With prefers-reduced-motion, use a simple crossfade, and keep any overlaid titles on a readable backing. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "blur-edge-logo-marquee", category: "interface-style", aspect: null, prompt: "Add a blur-edge logo marquee to [where to apply it, e.g. below the hero]. Slide a row of logos or images sideways at a slow constant speed of roughly 30 seconds per full cycle, with a generous gap between items, and wrap it seamlessly. Draw the moving band on a canvas sized to the band and sharp at the device pixel ratio, painting the logos each frame, and give the canvas role=\"img\" with an aria-label that lists them, so no readable text or logo ever sits half-clipped at an edge. Fade both edges with a soft gradient and a slight blur so items melt away gradually instead of being cut off. Slow the strip down on hover. Under prefers-reduced-motion, stop the movement and show the logos as a static, wrapped row of plain images. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "blur-focus-scroll-text", category: "interface-style", aspect: null, prompt: "Apply a blur focus reveal to [which text, e.g. each section heading].\nUse an inline SVG blur filter on the HTML text, starting with a strong blur and low opacity, and when the heading's top passes about the bottom fifth of the viewport, animate the blur down to zero and opacity up to full over about 1.2 seconds; optionally add a slight displacement wobble that settles as it clears.\nAdd a small replay control for the demo, and remove the filter entirely once the text is sharp so it stays crisp and cheap.\nWith prefers-reduced-motion, or if filters are unsupported, show the text sharp from the start; content must never be stuck blurred.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "caret-typewriter-text", category: "interface-style", aspect: null, prompt: "Add a caret typewriter effect to [which text, e.g. the hero subheading].\nReveal the sentence one character at a time about every 65 ms, followed by a thin blinking caret in the text color, and keep the line's final width reserved from the start so surrounding layout does not shift; optionally type a second line after a short pause and let the caret keep blinking at the end.\nThe full sentence must exist from the start for screen readers, with the typed copy hidden from them.\nIf the element is hidden, scrolled away mid-typing or motion is turned off, complete the sentence at once; with prefers-reduced-motion show the full text and a steady caret.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "cascading-cube-flip-text", category: "interface-style", aspect: null, prompt: "Add a cascading letter flip to [which text, e.g. the navigation links or a button label].\nSplit the text by user-perceived characters (use Intl.Segmenter when available) and give each one a front and a top face on a tiny 3D box; on hover or keyboard focus, each box rotates 90 degrees upward in sequence with about a 25 ms stagger over roughly 400 ms, revealing the top face in an accent color from the page palette, and flips back on leave.\nOn touch, a tap plays the flip once.\nMark all faces as decorative and keep the original text once for screen readers, and with prefers-reduced-motion change only the color without rotating.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "cascading-notification-list", category: "interface-style", aspect: null, prompt: "Add a cascading notification list to [where to apply it, e.g. beside the hero headline]. Show a short column of rounded cards, each with an icon, a title and a time, and reveal them one at a time every second or so: each new card appears at the top with a quick spring-like scale and fade of about 400ms while the cards below slide down smoothly. Keep each card's identity stable so existing ones move instead of re-rendering, cap the visible column with a soft fade at the bottom, and stop adding once the sample list is shown. Keep all items present in the markup in a sensible reading order. With prefers-reduced-motion, show the full list at once. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "chromatic-lens-bulge-image", category: "interface-style", aspect: null, prompt: "Add a chromatic lens effect to [which image, e.g. the hero photo]. Draw the image into a canvas with a small WebGL fragment shader that bulges the picture gently outward like thick glass and splits the red, green and blue channels into thin spectral fringes that grow toward the edges while the middle stays crisp.\nOn pointer move, ease the lens center toward the cursor over roughly 300ms; on touch, follow the finger and drift back to the center when it lifts.\nRespect prefers-reduced-motion by showing a fixed, mild distortion with no pointer tracking, keep the original image with its alt text as the fallback when WebGL is unavailable, and never place body text under the fringes.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "circuit-light-path-diagram", category: "interface-style", aspect: null, prompt: "Add an animated circuit diagram to [where to apply it, e.g. the technology section]: an inline SVG with a central chip block labeled in gradient text and six to eight angular traces leading into it from all sides.\nFirst draw the traces in with a stroke-dashoffset animation, then send small glowing dots in different palette colors along each trace using offset-path, each on its own loop length so the flow feels busy but not synchronized.\nLet the chip label gradient shimmer slowly, and brighten the traces slightly when the pointer hovers the diagram.\nMark the SVG decorative or give it a short accessible label, and under prefers-reduced-motion show the finished traces with static dots.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "circular-image-stack-intro", category: "interface-style", aspect: null, prompt: "Add a circular image stack intro to [where to apply it, e.g. the landing hero]: start with the images piled in the center, then fan them out one by one into an evenly spaced circle, each card turned to face outward.\nStagger the entrance over about 1.5 seconds with a soft overshoot, then let the whole circle drift around slowly while individual cards occasionally flip on their vertical axis.\nOn hover, pause the drift and lift the nearest card; on touch, a tap brings a card to the front.\nRespect prefers-reduced-motion by placing the cards directly in their final circle with no spin, provide a visible pause button for the ongoing motion, and keep the hero text readable on top.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "circular-reveal-theme-toggle", category: "interface-style", aspect: null, prompt: "Add a light/dark theme toggle to [where it goes, e.g. the top navigation bar] that reveals the new theme as an expanding circle. When clicked, switch the theme on the root element right away, then grow a clip-path circle from the toggle's center until it covers the whole viewport over about 500ms; use the View Transitions API when the browser has it and simply apply the theme instantly when it does not. Ignore extra clicks while a transition is running, swap a sun and moon icon inside the button, and remember the choice in localStorage. Give the button an accessible name and aria-pressed state. With prefers-reduced-motion, skip the circle and change the theme immediately. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "click-origin-stagger-exit", category: "interface-style", aspect: null, prompt: "Apply a click-origin stagger to [which group, e.g. the row of option cards]. On load, bring the items in from left to right with a short fade and rise, about 100ms apart.\nWhen the user clicks or taps one item, make all items exit with a fade and scale-down whose start times spread outward from the clicked item by distance, so the whole wave finishes within about one second, then show a small control to bring them back with the same entry sequence.\nKeep DOM order unchanged, make each item a real button reachable by keyboard, and move focus to the restore control once the exit ends.\nUnder prefers-reduced-motion, swap the wave for an instant hide and show.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "click-ripple-press-button", category: "interface-style", aspect: null, prompt: "Apply a click ripple to [which buttons, e.g. the primary call-to-action buttons]. On each press, spawn a translucent circle at the pointer position that scales from zero to past the button's edges while fading out over about 600ms, clipped by the button's rounded corners; when the button is activated with Enter or Space, start the ripple from its center instead. Let rapid presses stack several ripples and remove every ripple element once its animation ends. Tint the ripple from the button's text color so it works on any palette. With prefers-reduced-motion, show no ripple and rely on the normal pressed and focus styles. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "clip-path-product-preview", category: "interface-style", aspect: null, prompt: "Add an animated product preview to [which grid, e.g. the product grid]. When a product is clicked, reveal a large preview panel with a clip-path inset wipe (about 0.7s, ease-in-out), fade the other products back, and once the wipe finishes, start a small gallery that cycles that product's images with quick clip-path transitions every couple of seconds. Switching products stops the previous gallery before starting the new one, and closing reverses the wipe. Use real buttons, move focus into the preview and back on close, and support Escape. With prefers-reduced-motion, swap instantly and do not auto-cycle. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "clip-reveal-playful-menu", category: "interface-style", aspect: null, prompt: "Add a playful clip reveal menu to [which navigation, e.g. the site header]. When the menu button is pressed, expand a clip-path circle or rounded shape from the button until it covers the panel over about 600 ms with a springy ease, then stagger the links in. Closing should play the same path backward but faster, and if the user closes it mid-animation, reverse from the current point instead of jumping. Use aria-expanded on the button, move focus into the menu on open, close on Escape and return focus to the button. Under prefers-reduced-motion, show and hide the panel with a quick fade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "cmyk-halftone-print-effect", category: "interface-style", aspect: null, prompt: "Apply a CMYK halftone print effect to [which image, e.g. the feature illustrations]: split the image into cyan, magenta, yellow and black channels and draw each as its own grid of dots at a classic screen angle, so overlaps build the colors like a printed magazine.\nUse a WebGL fragment shader with uniforms for each ink color, dot size, dot shape, a flood amount that grows every dot of a channel evenly, a gain that scales existing dots, and a little grid noise for a hand-printed feel.\nOn hover, ease the dot size down over about 300ms so the photo sharpens toward the original.\nThe effect is static apart from hover; with prefers-reduced-motion, skip the hover easing, keep alt text on the image, and fall back to the plain picture without WebGL.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "color-adaptive-carousel-backdrop", category: "interface-style", aspect: null, prompt: "Add a color-adaptive carousel to [where to apply it, e.g. the gallery section]: image cards arranged on a gently curved 3D track that loops forever, with the card nearest the center sitting forward and the rest angled away.\nDrag, wheel or swipe moves the track with momentum and friction measured per frame; when the centered card changes, sample its dominant colors from a small canvas and ease the full-section background gradient toward them over about 600ms.\nProvide previous and next buttons and arrow-key support so the carousel works without dragging.\nWith prefers-reduced-motion, drop the momentum and tilt, move one card per step, and change the background color instantly; keep captions on a solid enough surface to stay readable on any gradient.\nBuild it with plain HTML, CSS 3D transforms, canvas and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "color-invert-cursor-circle", category: "interface-style", aspect: null, prompt: "Add a color invert cursor to [which area, e.g. the black and white hero]. Show a 60px white circle with mix-blend-mode set to difference so text and shapes under it flip to their inverse colors. Ease the circle toward the pointer by a fixed share of the remaining distance each frame for a soft lag, grow it over links, and hide it when the pointer leaves the area. Use a single requestAnimationFrame loop and cancel it and its listeners when the area is removed. Keep the native cursor available, skip the effect on touch, and with prefers-reduced-motion keep the circle but move it directly with no lag. Text must stay readable both with and without the circle. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "comic-burst-pop-text", category: "interface-style", aspect: null, prompt: "Apply comic burst lettering to [which word or short heading]. Render it in heavy uppercase with a thick dark outline, a bold offset drop shadow, and a halftone dot pattern made with a repeating radial gradient inside the letters, using bright colors from the page palette. When it first appears, pop it in by scaling from small to slightly oversized and settling at full size with a small tilt, in about 0.5 seconds. On hover, give it a quick wobble; on touch, a tap replays the pop. Use a real heading element when it is a title, and fall back to a heavy system font stack. Under prefers-reduced-motion, show it at rest without the pop or wobble, and keep the letters legible over the dots. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "concentric-pulse-ripple-backdrop", category: "interface-style", aspect: null, prompt: "Add a concentric pulse ripple behind [which element, e.g. the main call-to-action or app icon]. Center six to eight thin circles on the element, each about 70px wider than the last, with borders and faint fills taken from the accent color and fading out toward the outer rings.\nAnimate the rings with a gentle scale and opacity pulse of around 3 seconds, offset each ring's delay so the wave appears to travel outward, and keep the motion purely decorative since it does not react to input.\nKeep the rings behind the element with pointer-events: none, and verify the label on top stays readable in both light and dark themes.\nUnder prefers-reduced-motion, show the rings as still outlines.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "confetti-burst-celebration", category: "interface-style", aspect: null, prompt: "Add a confetti celebration that fires when [the success moment, e.g. the sign-up button is clicked]. Draw it on a full-viewport canvas that ignores pointer events: launch around 150 small rectangles and circles in the page's accent colors from the trigger point, give them random angles and speeds, then let gravity, drag and a gentle spin carry them down until they fade out after about 3 seconds. Stop the animation loop and clear the canvas once every piece is gone, and let a new trigger start a fresh burst. The confirmation text must still appear on its own, since the confetti is only decoration. With prefers-reduced-motion, skip the particles entirely. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "connected-checkbox-selection-highlight", category: "interface-style", aspect: null, prompt: "Apply a merged selection highlight to [which checkbox list, e.g. the notification settings list].\nEach row is a real checkbox with its label; when adjacent rows are checked, draw their background as one continuous rounded block, rounding only the outer corners of the run.\nWhen a row is toggled, animate the block over about 0.25s so it stretches to swallow the new row or splits into two pieces, and fade in the checkmark with a quick stroke draw.\nKeep native keyboard toggling with Space, a visible focus ring, and a checked state that does not rely on color alone; skip the animation on first render and under prefers-reduced-motion.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "connected-grid-scroll-reveal", category: "interface-style", aspect: null, prompt: "Apply a connected scroll reveal to [which grid, e.g. the portfolio image grid], where cells sit edge to edge with no gaps.\nAs each row scrolls into view, grow every cell's frame from zero along the side that faces its previous neighbor, so the images seem to unfold out of one another, while the image inside starts zoomed in (about 5x) and settles to its natural scale.\nDrive progress from the cell's position in the viewport with requestAnimationFrame or an IntersectionObserver, keeping it smooth in both scroll directions.\nUnder prefers-reduced-motion show the grid fully formed, and keep each image's alt text and any captions readable at all times.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "counter-loader-intro-reveal", category: "interface-style", aspect: null, prompt: "Add a counter loader intro to [where to apply it, e.g. the page opening]: show a large number ticking from 0 to 100 in stepped jumps over about 1.5 seconds beside a thin line that fills in sync.\nWhen it reaches 100, slide the loader away and fly a small cluster of images from the center into their places in the real layout while the headline rises in.\nTreat it as a decorative opening only, not as real loading progress, and let a click or key press skip straight to the finished page.\nRespect prefers-reduced-motion by skipping the counter and showing the final layout immediately, keep it from blocking content for more than two seconds, and make sure the page is usable if the script never runs.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "counting-number-ticker", category: "interface-style", aspect: null, prompt: "Add a counting number ticker to [which stats, e.g. the key metrics row]. When the row scrolls into view, count each figure up from zero to its final value over about 1.5 seconds with an ease-out curve, formatted with the page's locale separators and tabular digits so the width does not jitter. Next to each figure, grow a small mini bar chart to its set heights in step, labelled as illustrative rather than live data. Keep the final number in the markup from the start so screen readers and copies always get the real value, and run each count only once. With prefers-reduced-motion, show final values and bars immediately. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "covering-panel-unreveal-transition", category: "interface-style", aspect: null, prompt: "Add a covering panel transition for opening content previews from [which list or cards to apply it to]. When an item is chosen, a solid panel in an accent color from the page palette sweeps across, the preview image slides in from one side while its frame slides in from the other, and the title and text are uncovered with clip-path wipes, all within about 1 second using small offsets. Closing runs the sequence backwards, and repeated clicks should finish or cancel the current run instead of stacking animations. Move focus to the preview heading on open, return it to the item that opened it on close, and support Escape. With prefers-reduced-motion, replace the sweeps with a short opacity fade so content appears right away. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "crackling-electric-border", category: "interface-style", aspect: null, prompt: "Add a crackling electric border to [which element, e.g. the hero card or a power-up badge]. Draw the outline as an inline SVG path with small irregular kinks along every side, stroked in a bright accent color with a soft blurred glow copy underneath.\nUse a stepped animation that swaps between two or three slightly different jagged paths and nudges opacity and scale by tiny amounts, keeping the changes modest and well under three flashes per second.\nKeep the electric outline outside the content area with pointer-events: none so text and controls stay calm and usable.\nUnder prefers-reduced-motion, show one still jagged outline with a steady glow.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "crayon-stop-motion-cursor", category: "interface-style", aspect: null, prompt: "Add a playful crayon cursor to [where to apply it, e.g. the hero section]. On a full-size canvas behind the content, draw a rough, grainy crayon stroke that follows a smoothed copy of the pointer, getting thicker the faster the pointer moves, and slowly fade old strokes away. Redraw at a deliberately low rate of about 10 to 12 frames per second with slight random jitter in line edges so it feels like hand-made stop-motion, and show a small scribbly circle as the cursor itself. Pause drawing when the tab is hidden or the section leaves view. With prefers-reduced-motion or on touch-only devices, keep the normal cursor and show a single static doodle instead, and never cover text with strokes. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "crumpled-paper-texture-background", category: "interface-style", aspect: null, prompt: "Apply a crumpled paper texture to [where to apply it, e.g. the page background or a note card]. Generate it once on a canvas with a fixed seed: an off-white base tinted from the palette, fine fiber strands, a couple of soft fold lines, scattered crumple creases lit from one consistent angle, and a few faint water marks.\nThe texture is static, so draw it once, store it as an image, and redraw only when the element is resized.\nKeep the creases low contrast so body text stays fully legible, and keep the plain background color underneath as the fallback while the texture is drawing.\nBecause nothing animates, it needs no prefers-reduced-motion change.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "cursor-image-trail-effect", category: "interface-style", aspect: null, prompt: "Add a cursor image trail to [where to apply it, e.g. the hero section]: as the pointer travels, drop a small image at its position every time it has moved a set distance, cycling through a pool of the page's images.\nEach image pops in at full size, then shrinks and fades out over about 0.6 seconds, so a short ribbon of pictures follows the pointer and the newest always sits on top.\nOn touch devices, run the same trail along the finger while it drags, and stop spawning when the pointer leaves the area.\nRespect prefers-reduced-motion by showing a single static image near the pointer or none at all, keep headlines above the trail layer readable, and cap the number of live images so it stays smooth.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "cursor-lift-displacement-letters", category: "interface-style", aspect: null, prompt: "Add a cursor lift effect to [which heading, e.g. the hero title]. Draw the headline in a WebGL canvas as a fine mesh with a soft shadow layer beneath it, and in the vertex shader push the parts of the letters within a set radius of the pointer toward the viewer, fading the shadow by the same amount so the text seems to rise off the page. Ease the bump toward the pointer so it trails slightly, and let it settle flat within about half a second after the pointer leaves; on touch, follow the finger while dragging. Keep a real HTML heading with the same words in the page for screen readers and as the fallback when WebGL is unavailable. Under prefers-reduced-motion, show the flat headline without displacement. Build it with plain HTML, CSS and vanilla JavaScript, writing the WebGL code in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "curved-drag-product-grid", category: "interface-style", aspect: null, prompt: "Add a curved 3D product grid to [where to apply it, e.g. the shop section], drawn on a WebGL canvas where product images sit on tiles bent along the inside of a gentle cylinder.\nLet the visitor drag to pan with rubber-band resistance past the edges; a short press without movement counts as a click and smoothly zooms the camera onto that product, and releasing outside snaps back toward the center.\nAdd a soft vignette and slight tile lift on hover, and keep frame cost low by reusing one geometry and texture atlas.\nProvide arrow-key navigation, Escape to zoom out, and a plain HTML product list fallback, and under prefers-reduced-motion use instant camera moves.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "curved-path-scroll-follower", category: "interface-style", aspect: null, prompt: "Add a scroll-linked object that travels along a curved path through [which markers, e.g. the five milestone dots in the timeline section]. Measure the centers of the markers, build a smooth curve through them (a Catmull-Rom style spline is fine), and move a small badge or icon along it so its position follows scroll progress with slight easing that catches up within a fraction of a second. Optionally draw the path faintly as a dashed SVG line and rotate the badge to face its direction of travel. Rebuild the curve after resize, resetting any transform before measuring so positions do not drift. Respect prefers-reduced-motion by placing the badge statically at the nearest marker without gliding, and make sure the markers and their labels stay readable on their own. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "curved-svg-overlay-menu", category: "interface-style", aspect: null, prompt: "Add a curved overlay menu to [which navigation]. On open, an inline SVG shape with a bulging curved edge sweeps up from the bottom until it covers the screen in about 700 ms, then the menu appears and the overlay peels away out the top, uncovering a menu that sits on a slowly drifting, endlessly looping background pattern. Closing plays a matching sweep in the other direction. Use aria-expanded on the toggle, trap focus while open, close on Escape and restore focus. Under prefers-reduced-motion, fade the menu in and keep the background pattern still. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "curved-swipe-page-transition", category: "interface-style", aspect: null, prompt: "Add a curved swipe transition to [where to apply it, e.g. opening the menu or moving between sections]: a full-screen SVG panel in an accent color rises from the bottom with its top edge bulging into a curve, then settles into a flat edge that covers the view.\nAnimate it in two steps of about 400ms each, morphing the path from flat to curved to flat; running it again plays the same motion in reverse to uncover the page.\nTrigger it from a real button so it works with keyboard and screen readers, and move focus into the newly shown content when it finishes.\nWith prefers-reduced-motion, replace the swipe with a short fade; never hide content behind the panel longer than the transition.\nUse plain HTML, CSS, inline SVG and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "curved-thumbnail-flow-strip", category: "interface-style", aspect: null, prompt: "Add a thumbnail flow to [where to apply it, e.g. the gallery intro]: images start as a neat stack in the center, then on a button press or when scrolled into view they travel along curved paths and settle into an evenly spaced horizontal strip.\nGive each thumbnail its own arc with a slight rotation that straightens on arrival, staggered by about 60ms, over roughly 1.2s with a soft ease; a second press gathers them back into the stack.\nOn resize, remeasure the target slots and keep the current progress so the layout never breaks mid-flight.\nUse a real button with a clear label, keep the images reachable as a normal list, and under prefers-reduced-motion jump straight to the final strip.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "cylinder-roll-headline-text", category: "interface-style", aspect: null, prompt: "Add a cylinder roll to [which headline, e.g. the hero statement], cycling through [3-4 short phrases].\nPlace the phrases on top of each other and split each into letters whose rotation origin sits behind the text by about one eighth of its width, so letters swing around an imagined drum.\nEach letter rotates from -90 to 90 degrees on the X axis with a small stagger, and each phrase starts about 0.45 s after the previous one, giving a continuous rolling loop; re-measure width on resize.\nExpose only one readable version of the headline to screen readers and hide the rolling copies; pause the loop when off screen.\nWith prefers-reduced-motion, show the first phrase still.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "datamosh-glitch-transition", category: "interface-style", aspect: null, prompt: "Add a datamosh glitch transition to [where to apply it, e.g. the image slideshow in the hero]: when the slide changes, the outgoing picture's pixels should be dragged along blocky motion vectors and smear into the incoming one, like a video file with dropped keyframes.\nImplement it in a WebGL fragment shader written in the page: sample the previous frame, offset 16px blocks by a noise-driven vector field, blend toward the next image over about 800ms, then snap clean.\nTrigger it from the slide controls or a click, and let a hover over the image add a faint, brief block shimmer.\nWith prefers-reduced-motion, replace the effect with a plain short crossfade; keep any captions in normal HTML above the canvas so they stay readable.\nUse plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets; generate placeholder images in canvas if none exist." },
  { id: "depth-flyin-highlight-text", category: "interface-style", aspect: null, prompt: "Add a depth fly-in highlight to [which phrases, e.g. key phrases inside the body copy].\nWhen a marked phrase scrolls into view from either direction, its letters start far toward the viewer with a tilt and low opacity, then settle into place with a short stagger over about 700 ms while a highlight color from the page palette sweeps behind the phrase.\nWhen the phrase leaves the viewport, reset its letters to their resting state so a later entry can play again, and never leave letters mid-flight.\nKeep the phrase as real text for screen readers, hiding only the split letters, and with prefers-reduced-motion show the highlight color without any letter motion.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "depth-stack-scroll-cards", category: "interface-style", aspect: null, prompt: "Apply a depth-stacked card effect to [which images, e.g. the project thumbnails in the hero]. Stack the cards along the z axis inside a perspective container, each starting further back with a slight tilt and reduced opacity, with start and end depths computed from the viewport width and the card's index. As the user scrolls, move every card forward so it grows, straightens and fades in, then passes the viewer and fades out, like flying through a pile of photos. If a new scroll begins mid-transition, cancel the old animation and continue from the current state instead of jumping. Respect prefers-reduced-motion by showing the cards as a simple vertical list without depth movement, and keep any title text above the stack readable. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "diagonal-glare-hover-card", category: "interface-style", aspect: null, prompt: "Apply a diagonal glare to [which cards, e.g. the pricing cards]. Add a pseudo-element over each card holding a linear gradient angled at about -45 degrees, transparent at both ends with a soft white band in the middle, sized to twice the card and parked off one corner; on hover or focus-within, slide its background-position across so the band passes over the card in about 650ms. Expose the angle, band width, duration and color as CSS custom properties, and make the glare layer ignore pointer events so buttons inside stay clickable. Keep text contrast intact while the band passes. With prefers-reduced-motion, skip the sweep. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "diagonal-stripe-pattern-background", category: "interface-style", aspect: null, prompt: "Add a diagonal stripe pattern to [where to apply it, e.g. a placeholder panel or the section behind a card]. Use an inline SVG pattern of thin 45-degree lines in a muted tone from the palette, with spacing set as a plain number of pixels around 8 to 12, filling the area through a full-size rect.\nOptionally fade it toward the edges with a mask, and on hover of the parent shift the stripes slowly sideways by one period over about a second for a subtle hint of life.\nMark the pattern aria-hidden with pointer-events: none and keep the line opacity low enough that text placed over it stays easy to read.\nUnder prefers-reduced-motion, keep the stripes still on hover.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "dot-pattern-backdrop-card", category: "interface-style", aspect: null, prompt: "Add a dot pattern backdrop to [which cards, e.g. the feature cards]. Tile a tiny inline SVG or a radial-gradient dot every 24-30px across each card's background in a faint tone of the text color, then lay a diagonal gradient from the card's solid background color to transparent over it so the dots fade out behind the heading and copy. Optionally fade the pattern in a little more on hover over about 300ms. Keep text contrast meeting WCAG AA everywhere the pattern shows, and make sure the card reads fine if the pattern fails to render. Any hover change should be skipped under prefers-reduced-motion. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "dotted-world-map-markers", category: "interface-style", aspect: null, prompt: "Add a dotted world map to [which section, e.g. the global offices section]. Render the continents as a grid of small round dots in a muted tone, offsetting every other row by half a step for a honeycomb rhythm; approximate the land shapes with a simple mask written in the page. Place a few accent-colored markers on chosen cities, each with a small label and a soft ring that pulses outward every two seconds. Pair the map with a visible text list of the same locations so the information does not depend on the picture. With prefers-reduced-motion, keep the markers still. Build it with plain HTML, CSS and vanilla JavaScript using SVG or canvas, with no external libraries, CDNs, fonts or network assets." },
  { id: "double-image-clip-hover", category: "interface-style", aspect: null, prompt: "Apply a double image clip hover to [which images, e.g. the project cards].\nStack two copies of the same image in each card: the lower one gets a filter such as grayscale, blur or a color tint, and the upper one is hidden by a clip-path (an inset, circle or slanted polygon).\nOn hover or keyboard focus, animate the clip-path open over about 0.5s while easing the lower copy's filter, and on leave reverse it, interrupting any running animation so rapid in-and-out never glitches.\nOn touch, run the reveal once on tap before following the link.\nKeep one meaningful alt text with the other copy marked decorative, and under prefers-reduced-motion switch states instantly.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "drifting-aurora-headline-text", category: "interface-style", aspect: null, prompt: "Apply an aurora text effect to [which word or heading]. Fill the letters with several large, blurred color blobs from the page palette that drift and blend slowly behind the glyphs, clipped to the text shape, completing one loop in about 10 seconds and repeating the first color at the end so the cycle is seamless. It can be used on a single highlighted word inside a longer heading. Give the text a solid fallback color for browsers without background clipping, and avoid reading the same words twice: either put the effect on the real text, or give screen readers one copy and hide the decorative one. With prefers-reduced-motion, freeze the colors in a pleasant position, and check contrast against the lightest blob. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "drifting-mesh-gradient-background", category: "interface-style", aspect: null, prompt: "Add a drifting mesh gradient behind [where to apply it, e.g. the hero section]. Pick four or five colors from the page palette and render them on a canvas as large soft blobs whose edges melt into each other, with a gentle swirl in the coordinates and a very light film grain on top so the blend never bands.\nMove each blob along its own slow looping path of 15 to 25 seconds so the composition keeps changing without ever feeling busy.\nKeep the effect behind the content, check that headings and buttons keep enough contrast against every color in the mix, and stop drawing while the section is out of view.\nUnder prefers-reduced-motion, show one still frame of the gradient.\nBuild it with plain HTML, CSS and vanilla JavaScript, using canvas 2D or WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "drifting-smoke-ring-glow", category: "interface-style", aspect: null, prompt: "Add a drifting smoke ring around [which element, e.g. the product logo or a central headline]. Draw it on a canvas with a fragment shader: a ring of set radius and thickness whose edges are torn by several layers of noise so it looks like wisps of colored smoke, with a faint fill toward the inside and a glow from the accent color.\nLet the wisps swirl slowly around the ring on a continuous loop, with two noise layers moving at different speeds for depth.\nKeep the ring behind the element, leave the center calm so the content inside stays readable, and stop rendering when off screen.\nUnder prefers-reduced-motion, show one still frame of the ring.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "dual-direction-name-marquee", category: "interface-style", aspect: null, prompt: "Add a two-way name marquee to [where to apply it, e.g. the clients section]: show two rows of names or logos of varying widths that glide sideways in opposite directions, the upper row a little faster than the lower.\nWrap each row seamlessly, use roughly 25 and 35 seconds per cycle, and fade both edges softly into the background.\nDraw the moving band on a canvas sized to the band and sharp at the device pixel ratio, painting the names or logos each frame, and give the canvas role=\"img\" with an aria-label that lists them, so no readable text or logo ever sits half-clipped at an edge.\nPause the rows on hover, and include a visible pause button that keeps the marquee stopped until the user resumes it.\nRespect prefers-reduced-motion by showing the names as a still, wrapped list of plain text, readable at rest.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "dual-wave-scroll-text", category: "interface-style", aspect: null, prompt: "Add a dual wave text list to [where to apply it, e.g. the projects index]. Lay out two columns of short titles; as the page scrolls, shift each row sideways by a sine of its row phase plus the overall scroll progress, with the left and right columns moving in opposite directions, so the lists ripple like two mirrored waves. The row closest to the vertical center is highlighted and swaps a thumbnail in the middle with a quick crossfade, using images already in the project or CSS gradient tiles. Hovering a title also highlights it and shows its thumbnail; on touch, a tap does the same. Keep each title a normal link in reading order. Under prefers-reduced-motion, keep the rows straight and change the thumbnail without fades. Build it with plain HTML, CSS and vanilla JavaScript using requestAnimationFrame, with no external libraries, CDNs, fonts or network assets." },
  { id: "dust-petal-dissolve-text", category: "interface-style", aspect: null, prompt: "Add a dust and petal dissolve to [which text, e.g. a large title in a feature section], triggered by a button.\nDraw the title to a canvas, then over about six seconds erode it with a moving noise-shaped edge that sweeps across the letters, releasing fine glowing dust and a few rotating petal shapes from the edge that drift upward and sideways before fading; colors come from the page palette.\nDisable the button while the dissolve runs and re-enable it shortly after the title fades back in, and cap the particle count so it stays smooth on laptops.\nKeep the real title as HTML text for screen readers, and with prefers-reduced-motion replace the dissolve with a simple fade out and in.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "echo-stack-scroll-text", category: "interface-style", aspect: null, prompt: "Add an echo stack to [which heading, e.g. a full-width section title].\nBehind the real heading, create several decorative copies, each showing a thinner horizontal band of the same word, and stack them below the original so the word seems to repeat downward like an echo.\nAs the heading scrolls through the viewport, spread the copies apart vertically in growing steps and fade the lower ones, then collapse them back as it leaves; compute spacing from the measured text height so it stays tidy at any size.\nKeep the copies hidden from assistive tech and use colors from the page palette with the original copy at full contrast.\nWith prefers-reduced-motion, show only the original heading with two faint static echoes.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "elastic-bounce-footer-edge", category: "interface-style", aspect: null, prompt: "Add an elastic bounce footer to [which footer]. Give the footer a curved SVG top edge; when the footer enters the viewport, read how fast the visitor was scrolling and bend the edge by an amount based on that speed, clamped to a sensible maximum, then let it spring back with a decaying wobble over about two seconds. Slow arrivals give a gentle ripple and fast ones a bigger bounce. Keep the footer links and text fixed and readable; only the decorative edge moves. Under prefers-reduced-motion, keep the edge flat or softly curved without motion. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "elastic-lagging-column-grid", category: "interface-style", aspect: null, prompt: "Apply an elastic lag grid to [which grid, e.g. the image gallery]. Group the items into columns and let each column follow the scroll position with its own small delay, the center columns lagging most, by easing each column's offset toward the target every frame. When scrolling stops, the columns settle back into alignment within about half a second, giving a soft, stretchy feel. Build the columns so that the DOM order still matches a sensible reading order. Under prefers-reduced-motion, keep the grid aligned and static. Build it with plain HTML, CSS and vanilla JavaScript using requestAnimationFrame, with no external libraries, CDNs, fonts or network assets." },
  { id: "emissive-dissolve-particle-transition", category: "interface-style", aspect: null, prompt: "Add an emissive dissolve to [which element, e.g. the hero image when switching slides]: the element disappears along a noise-shaped edge that glows hot in an accent color, while small sparks peel off the edge and drift upward before fading.\nDraw the element into WebGL, threshold a noise texture against a progress value animated over about 1.2 seconds, color a thin band at the threshold with an emissive glow, and spawn sparks from that band; reverse the progress to make it reappear.\nReuse the particle buffers instead of reallocating them each frame, and recycle sparks that travel too far.\nWith prefers-reduced-motion, use a plain opacity fade; keep the real content in the DOM so it stays accessible during and after the effect.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "endless-loop-card-carousel", category: "interface-style", aspect: null, prompt: "Add an endless card carousel to [where to apply it, e.g. the featured work section] whose cards wrap around seamlessly so the row never runs out. Let people move it by dragging, by wheel or trackpad scrolling, and with clearly labelled previous and next buttons, and make every input settle on the nearest card with a short eased snap of about 400ms. Keep one running offset for all three inputs so the buttons, drag and scroll always agree, and scale the centered card slightly larger than its neighbors. Support touch dragging and arrow keys when the carousel has focus. With prefers-reduced-motion, jump between cards without the glide, and keep every card's text readable and reachable in plain order. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "endless-stacked-panels", category: "interface-style", aspect: null, prompt: "Apply an endless stacking-panel scroll to [which full-screen sections, e.g. the four story panels]. Each panel fills the viewport and stays pinned while the next one slides up and covers it, and a copy of the first panel sits at the end so that, when the user reaches it, the scroll position is silently reset to the top and the sequence continues without a visible jump; scrolling above the start wraps to the end the same way. Recalculate the loop length on resize, and keep wheel, keyboard and touch scrolling native with no hijacked speed. Give the panels contrasting backgrounds from the page's palette so each cover is easy to read. Respect prefers-reduced-motion by turning off the wrap and pin so the panels read as a normal finite list, mark the duplicate panel aria-hidden, and keep content after the panels reachable. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "falling-image-cursor-trail", category: "interface-style", aspect: null, prompt: "Add a falling image trail to [which section, e.g. the portfolio intro]. Each time the pointer travels about 100 pixels, place the next image from a small pool of page images (or generated colored shapes) at the pointer, let it pop in, then drop and rotate slightly as it fades out over about a second. Reuse the same pool of elements in rotation, cancelling any running animation on an element before moving it, and stop the distance check when the pointer leaves the section. Keep images decorative with empty alt text and behind the section's text. With prefers-reduced-motion or on touch, show a static collage of the images instead. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "falling-light-rays-background", category: "interface-style", aspect: null, prompt: "Add falling light rays behind [where to apply it, e.g. the hero section]. Place a decorative layer of 8 to 14 tall, blurred, semi-transparent beams that fan out from just above the top edge, each with its own width, tilt and delay, tinted from the page's accent color.\nAnimate each beam with a slow 6 to 10 second loop that gently fades its opacity and sways its angle by a few degrees, using only transform and opacity so scrolling stays smooth.\nKeep the beams behind the content on their own layer with pointer-events: none, and make sure headline contrast stays readable at the brightest moment.\nUnder prefers-reduced-motion, show the beams as a still glow with no swaying.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "feature-mosaic-stats-tiles", category: "interface-style", aspect: null, prompt: "Add a compact feature mosaic to [where to apply it, e.g. the overview section]: a two-column layout where the left tile spans two rows and holds a big headline number, and the right column holds a solid color tile and a small bar chart tile.\nCount the big number up from zero when the mosaic enters view, grow the bars to their values with a short stagger, and keep a small symbol slowly rotating in the color tile.\nUse the page palette, keep tile heights stable so long labels wrap instead of overflowing, and stack the tiles in one column on narrow screens.\nKeep the final numbers in the markup for screen readers, and under prefers-reduced-motion show final values with no counting or rotation.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "film-grain-noise-overlay", category: "interface-style", aspect: null, prompt: "Add a film grain overlay to [where to apply it, e.g. the whole page or the hero gradient]. Generate the grain with an inline SVG filter using fractal turbulence, turn it greyscale, raise its contrast so the specks are crisp, and lay it over the surface at 5 to 12 percent opacity with a blend mode that suits light or dark themes; optionally fade it out toward the edges with a radial mask.\nKeep the grain static by default, and give each instance its own filter id so several can live on one page.\nMark the overlay aria-hidden with pointer-events: none so it never blocks clicks, and check that small text keeps its contrast with the grain applied.\nThe grain does not move, so it is already safe for prefers-reduced-motion.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "flash-filter-slide-reveal", category: "interface-style", aspect: null, prompt: "Add a flash filter slide reveal to [which slideshow or hero carousel]: when moving to the next slide, slide the outer frame fully off one side while the image inside moves the opposite way, so a clean edge sweeps across and uncovers the next picture.\nDuring the sweep, push the outgoing image's brightness up sharply for a split second and settle the incoming one back to normal, giving a camera-flash punch; keep the whole change to about one second.\nDrive it from next and previous buttons, arrow keys and horizontal swipes, and ignore new input until the current transition ends.\nRespect prefers-reduced-motion by using a plain crossfade with no flash, avoid rapid repeated flashes, keep slide titles readable, and announce the current slide number to screen readers.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "flashlight-grid-reveal-section", category: "interface-style", aspect: null, prompt: "Add a flashlight reveal to [which section, e.g. the dark hero section]. Cover the background with a fine grid pattern that is masked out except within a soft circle around the pointer, and add a blurred glow of the accent color at the same spot, so moving the pointer feels like sweeping a torch across a hidden surface. Ease the light toward the pointer over roughly 100ms and fade it out when the pointer leaves. Keep all headings and text on a separate layer above the mask so nothing needs to be lit to be read. On touch, show a fixed soft light in the center. With prefers-reduced-motion, show the grid faintly everywhere without the moving light. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "flickering-square-grid-background", category: "interface-style", aspect: null, prompt: "Add a flickering square grid behind [where to apply it, e.g. the call-to-action section]: a canvas filled with small squares separated by thin gaps, each holding its own low opacity in one accent color.\nEvery frame, give each square a small chance (scaled by elapsed time) to jump to a new opacity, so the field shimmers softly like a dormant display; cap the flicker rate so no area flashes more than a few times per second.\nSize the canvas to its container at the device pixel ratio (capped at 2), and only run the animation loop while the section is visible.\nWith prefers-reduced-motion, draw one still frame; keep peak opacity low behind text so content stays easy to read.\nBuild it with plain HTML, CSS, canvas and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "flip-resize-grid-layout", category: "interface-style", aspect: null, prompt: "Add a grid whose density can be switched with a small set of size buttons (for example small, medium, large) to [which grid, e.g. the project gallery].\nWhen a size is chosen, record each tile's current position and size, apply the new column layout, then animate every tile from its old box to its new one with transforms over about 0.6s with an ease-out curve, so tiles glide and rescale instead of jumping.\nMark the active size button with aria-pressed, and ignore new clicks until the running transition finishes or cancel it cleanly so tiles never end up mid-way.\nUnder prefers-reduced-motion, switch the layout instantly with no movement; the grid must stay fully usable and readable either way.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "floating-depth-particles-background", category: "interface-style", aspect: null, prompt: "Add floating depth particles behind [where to apply it, e.g. the hero section]: a few hundred soft circles placed in a virtual 3D volume and drawn on a 2D canvas with perspective projection, so near ones are larger and brighter and far ones small and faint.\nRotate the whole volume slowly around the vertical axis while each particle bobs upward with a buoyant drift and wraps back to the bottom; let the pointer tilt the volume a few degrees.\nCap the pixel ratio at 2 and cut the particle count to about a fifth on narrow screens.\nWith prefers-reduced-motion, draw a single still frame and actually stop the animation loop instead of redrawing the same image; keep text above the canvas at full contrast.\nBuild it with plain HTML, CSS, canvas and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "fluid-xray-reveal-layer", category: "interface-style", aspect: null, prompt: "Add a fluid x-ray reveal to [where to apply it, e.g. the hero image]: stack two visuals, a normal top image and an alternate x-ray or wireframe version beneath, and let the pointer paint a soft, liquid mask that shows the lower layer.\nKeep the mask in a ping-pong pair of WebGL render targets: each frame, spread the trail slightly to neighbors so edges ripple like ink, and let it heal back to the top image over one to two seconds.\nOn touch, follow the finger the same way; when the pointer leaves, the reveal fades out naturally.\nWith prefers-reduced-motion, show a static circular reveal under the pointer with no spreading, and keep any headline outside the masked area at full contrast.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "fluted-glass-image-overlay", category: "interface-style", aspect: null, prompt: "Apply a fluted glass overlay to [which image, e.g. the hero photo]: render the image through a WebGL fragment shader that slices it into repeating strips, each one refracting its slice like a prism or lens so the picture looks seen through ribbed glass.\nExpose uniforms for strip shape (straight lines, wave or zigzag), strip size and angle, refraction strength, stretch and a light blur, plus margins that limit the glass to part of the frame.\nOn hover, ease the refraction strength down over about 400ms so the image briefly comes into focus.\nWith prefers-reduced-motion, keep the glass static with no hover easing; keep the original image's alt text, and show the plain image if WebGL is unavailable.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "fragmented-reveal-tooltip", category: "interface-style", aspect: null, prompt: "Apply a fragmented reveal to the tooltips on [which elements, e.g. the highlighted terms in the article]. When a term is hovered or focused, place the tooltip next to it, flipping to the other side if it would overflow the viewport, and cover it with a grid of small tiles that fade and scale in with staggered delays in random order over about 400ms until the panel is solid, then fade the text in; reverse the stagger when it closes. Connect each trigger to its tooltip with aria-describedby, open it on keyboard focus too, and close it on Escape or blur. With prefers-reduced-motion, show the tooltip with a short fade. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "frosted-glass-blob-card", category: "interface-style", aspect: null, prompt: "Add a frosted glass card over moving color to [where it goes, e.g. the hero section]. Behind the card, place three large blurred circles in the page's accent colors that drift slowly along different paths on 15-25 second loops; make the card itself semi-transparent white or dark with backdrop-filter blur around 16px, a thin light border and a soft shadow. Use a solid fallback background where backdrop-filter is unsupported, and make sure the card text keeps WCAG AA contrast whatever color sits behind it. With prefers-reduced-motion, keep the blobs still. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "frosted-glass-outline-card", category: "interface-style", aspect: null, prompt: "Apply a frosted glass outline to [which cards, e.g. the feature cards over the hero]. Give each card a translucent fill, a backdrop-filter blur of about 12 to 20px, and a 1px rim made from a gradient border that is brighter on the top-left edge like light catching glass, over a backdrop of slowly drifting color blobs.\nOn hover or focus, lift the card a few pixels and brighten the rim over about 200ms.\nTest every caption and small label on the busiest part of the backdrop and raise the fill opacity until they read clearly; fall back to a solid tinted fill where backdrop-filter is unsupported.\nUnder prefers-reduced-motion, keep the blobs still and skip the lift.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "full-screen-snap-scenes", category: "interface-style", aspect: null, prompt: "Turn [which sections, e.g. the three story scenes] into full-height snapping scenes. Make each scene fill the viewport and use CSS scroll-snap (mandatory, aligned to start) on the scrolling container so every scroll gesture settles on one scene, and add a small dot navigation on the side that highlights the current scene and jumps to it when clicked. Keep all text in normal HTML order from the start, so nothing depends on JavaScript to appear. Make sure scenes taller than the screen on small devices can still be read, relaxing snapping to proximity there. With prefers-reduced-motion, use instant jumps for the dot navigation instead of smooth scrolling. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "fullscreen-clip-morph-gallery", category: "interface-style", aspect: null, prompt: "Add a fullscreen-to-row clip morph to [where to apply it, e.g. the hero gallery].\nStart with one image filling the viewport under a large title; on a button press, animate the image's clip-path from the full rectangle into a tall rounded window while neighboring slides fly in from depth to form a row, and squash the title letters away vertically.\nRun it over about 1.2s with a strong ease-in-out, and provide a close control that plays the morph in reverse back to fullscreen.\nUse labeled buttons, keep the title in the DOM for screen readers, move focus sensibly between states, and under prefers-reduced-motion switch between the two layouts with a short fade.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "fullscreen-scroll-slideshow", category: "interface-style", aspect: null, prompt: "Add a fullscreen scroll slideshow to [where to apply it, e.g. the featured projects page]. Show one large image slide at a time; a wheel step, swipe or arrow key moves to the next or previous slide with a vertical clip reveal and a slight image scale over about one second, ignoring extra input until the transition ends. Each slide has a title and a button that opens a content view with details, which closes automatically if the user navigates away. Add a numbered indicator that updates immediately and works as direct navigation. Under prefers-reduced-motion, switch slides with a crossfade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "gem-smoke-glow-emblem", category: "interface-style", aspect: null, prompt: "Add a gem smoke glow to [which emblem, e.g. the logo in the hero]: a WebGL shader that fills a shape, by default a diamond outline, with slowly curling colored smoke inside and lets a softer haze leak outside its edge.\nUse separate uniforms for inner glow and outer glow, each with its own distortion amount, and a palette taken from the page accents; if an image of the logo is provided, trace its alpha outline into a mask once, ahead of the first frame.\nOn hover, let the smoke speed up and brighten slightly for about a second.\nWith prefers-reduced-motion, render a still frame; give the emblem an accessible label and show a plain version of the shape if WebGL fails.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "giant-type-zoom-transition", category: "interface-style", aspect: null, prompt: "Add a giant-type zoom transition between [which two views, e.g. the overview and a detail panel].\nBehind the content, set a few rows of very large, low-contrast words in the page palette; when the user opens the next view, the whole block of words rotates about 90 degrees and scales up past the viewport while the rows slide sideways in alternating directions, wiping away the old content and revealing the new one.\nRun the forward transition in roughly 1.2 seconds with a strong ease-in-out, and play a matching reverse when the user goes back; a second click during a transition should jump to the latest target instead of queuing.\nWith prefers-reduced-motion, swap views with a short crossfade, and keep focus moved to the new view's heading so keyboard users stay oriented.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "glare-sweep-shimmer-text", category: "interface-style", aspect: null, prompt: "Add a shimmer sweep to [which text, e.g. the announcement badge]. Keep the text in its normal readable color, and layer a narrow, bright, semi-transparent highlight that is clipped to the letter shapes and glides from left to right about every 3 seconds, with a short pause between passes. On hover, run the highlight once more right away; on touch devices simply keep the loop. If the shimmering element is meant to be clicked, make it a real link or button with a focus style rather than a decorative box. Under prefers-reduced-motion, stop the sweep and leave the plain text, and make sure the base color alone meets contrast. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "glowing-orb-cursor-trail", category: "interface-style", aspect: null, prompt: "Add a glowing orb trail to [where to apply it, e.g. the hero section]. Five soft, blurred dots in shades of the page accent color follow the pointer, each one lagging a little more than the last and getting smaller and fainter, so they read as a comet-like afterimage. Move them with transforms inside one requestAnimationFrame loop, using a different easing factor per dot, and let the trail collapse onto the pointer when it stops. Ignore the effect on touch devices and pause it when the tab is hidden. With prefers-reduced-motion, hide the trail completely, and keep the dots behind content so they never block clicks or text. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "glowing-pricing-plan-card", category: "interface-style", aspect: null, prompt: "Add a glowing pricing card to [where to apply it, e.g. the pricing section] with a monthly / yearly toggle above the price.\nWhen a billing option is chosen, update the toggle's pressed state and the price together, rolling the old digits out and the new ones in over about 0.3s, and let a soft radial glow in the accent color gather behind the selected plan while the border brightens.\nOn hover the card tilts slightly toward the pointer and the glow follows it; on touch, keep it flat.\nUse real buttons with aria-pressed, announce the new price via a polite live region, keep text contrast high over the glow, and under prefers-reduced-motion change values instantly with a static glow.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "glowing-voronoi-cells-background", category: "interface-style", aspect: null, prompt: "Add glowing Voronoi cells to [where to apply it, e.g. the hero or a science-themed section]. In a fragment shader, divide the canvas into irregular cells, draw thin gaps between them in a dark tone, shade each cell with a soft radial glow toward its center, and pick each cell's color from a few stepped palette shades.\nMove the cell centers slowly along small looping paths so the borders breathe and reshape, and let the cell under the pointer brighten slightly on hover.\nKeep it behind content, keep glow levels modest under text, and stop rendering when off screen.\nUnder prefers-reduced-motion, render a single still frame.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "glyph-scramble-resolve-text", category: "interface-style", aspect: null, prompt: "Add a glyph scramble resolve to [which text, e.g. a section label or button caption].\nWhen triggered by click or when the text first scrolls into view, replace each character with rapidly changing random symbols, then lock the real characters in from left to right over roughly 800 ms; spaces stay spaces and the width should not jump, so use a monospace or tabular style for the effect.\nA new trigger cancels the running one and starts again cleanly, and hiding the tab or stopping motion ends the effect showing the final word.\nKeep the real text in an accessible label so screen readers never hear the random symbols, and with prefers-reduced-motion show the final text with no scramble.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "gooey-cell-cursor-trail", category: "interface-style", aspect: null, prompt: "Add a gooey cursor trail to [which section, e.g. the hero background]. Divide the section into an invisible grid of cells; when the pointer enters a cell, switch on a soft circle there and switch it off again after about 600ms. Apply an SVG blur and contrast filter to the cell layer so neighbouring circles merge into a liquid blob that follows the pointer, and use a blend mode so the blob tints the background rather than hiding it. Rebuild the grid only when the size actually changes. Keep text above the effect and readable, ignore touch, and with prefers-reduced-motion show a still blob shape instead. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "gooey-metaball-blobs-background", category: "interface-style", aspect: null, prompt: "Add gooey metaball blobs to [where to apply it, e.g. the hero background]. Draw six to ten round blobs of different sizes on a canvas with a fragment shader that sums their fields, so neighbors stretch and merge into one smooth shape when they approach and snap apart as they separate; color them from the page palette with a soft inner glow.\nLet the blobs drift on slow orbits of 10 to 20 seconds, and gently attract the nearest one toward the pointer on hover or touch.\nKeep the blobs behind the content with pointer-events: none on the layer, and keep text on a calm area or a contrasting panel.\nUnder prefers-reduced-motion, freeze the blobs in a pleasing arrangement.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "gooey-morph-word-text", category: "interface-style", aspect: null, prompt: "Add gooey morphing words to [where to apply it, e.g. the tagline], cycling through [list of 3-6 words].\nStack two copies of the word and, over about one second, blur and fade the outgoing word while the incoming one sharpens in, passing both through an inline SVG threshold filter so their shapes appear to melt and fuse; hold each word for about two seconds before the next morph.\nGive the filter a unique id per instance, pause the cycle while the element is off screen or the tab is hidden, and add a small pause control next to it.\nShow the first word as plain static text before the script runs, expose a polite live region only when the user starts the cycle, and with prefers-reduced-motion show one word without cycling.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "grainy-gradient-backdrop", category: "interface-style", aspect: null, prompt: "Add a grainy gradient backdrop to [where to apply it, e.g. the hero section]: soft color fields from the page palette that blend into each other, finished with a fine, even film grain.\nRender it in a WebGL fragment shader with uniforms for edge softness, how much the color bands warp, grain amount, and a base shape (waves, dots, corners or blobs); keep the grain at a fixed screen scale so it never smears when the shapes move.\nAnimate the color fields slowly on a cycle of about 20 seconds, and nudge them toward the pointer on hover.\nWith prefers-reduced-motion, render one still frame; keep contrast between text and the lightest part of the gradient.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "gravity-bounce-image-trail", category: "interface-style", aspect: null, prompt: "Add a gravity bounce trail to [where to apply it, e.g. the hero section]: each time the pointer has traveled a set distance, spawn a small image at its position that falls under gravity, tumbles slightly, and bounces off the bottom edge of the section two or three times before fading out.\nGive each image a little sideways drift and spin taken from the pointer's direction, use a simple velocity and damping loop on requestAnimationFrame, and skip spawning near the very bottom so pictures always have room to fall.\nOn touch, spawn along the drag path; cap live images at around 20 and remove them once they settle.\nRespect prefers-reduced-motion by turning the trail off, keep text above the falling layer readable, and make sure nothing blocks clicks on the content underneath.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "grid-flow-intro-loader", category: "interface-style", aspect: null, prompt: "Add an intro loader to [where to apply it, e.g. the gallery page] that shows a large percentage counter while the page's images load, then flows the thumbnails into a grid.\nBase the counter on how many images have actually finished loading (or errored), not on a timer, and wait for the last one before leaving.\nThen fade the counter out and send the thumbnails from a tight cluster in the center along short curved paths into their grid slots with a staggered ease-out over about 1s; clicking a thumbnail can open it larger.\nExpose loading progress to assistive tech with a progressbar role, and under prefers-reduced-motion skip the flow and show the grid as soon as images are ready.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "grid-to-slideshow-switch", category: "interface-style", aspect: null, prompt: "Add a view switch to [which gallery, e.g. the image gallery] that toggles between a multi-column grid and a single large slideshow.\nWhen switching to the slideshow, send alternate columns sweeping up and down off screen while the selected image expands smoothly from its grid cell into the large slide; switching back reverses it so columns return and the image shrinks into place.\nUpdate the toggle label and pressed state immediately, and ignore further toggles until the transition finishes.\nIn slideshow mode support previous and next buttons plus arrow keys, keep focus on a sensible control after each switch, and under prefers-reduced-motion swap views with a quick fade.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "grid-to-slideshow-transition", category: "interface-style", aspect: null, prompt: "Add a grid-to-slideshow morph to [which gallery]: show the images first as an irregular, staggered grid, and when one is clicked, fly every image smoothly from its grid spot into a horizontal slideshow with the chosen image centered and large.\nMeasure positions before and after the layout change and animate the difference over about 0.8 seconds, staggering outward from the clicked image so the motion ripples.\nInside the slideshow, arrow buttons, arrow keys and swipes move between images, and a close button or Escape reverses the morph back into the grid.\nRespect prefers-reduced-motion by switching layouts with a short crossfade instead, keep focus on the active image after each switch, and ignore new clicks until the current morph finishes.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "grid-zoom-detail-view", category: "interface-style", aspect: null, prompt: "Add a zoom-to-detail interaction to [which grid, e.g. the article image grid].\nWhen a thumbnail is clicked, compute the transform from its cell to a large frame on the right half of the screen and animate it there over about 0.8s, while the other thumbnails fade back and a text panel with title and description slides in on the left.\nA close button, Escape, or a click on the backdrop reverses the zoom so the image lands exactly back in its cell.\nMake each thumbnail a button, move focus into the panel when it opens and back to the thumbnail when it closes, and under prefers-reduced-motion open and close with a simple fade.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "hand-drawn-marker-highlight", category: "interface-style", aspect: null, prompt: "Add a hand-drawn marker highlight to [which words, e.g. two key phrases in the intro paragraph], using an underline style for one and a filled highlight style for the other.\nDraw each mark as an inline SVG path with slightly irregular, doubled strokes so it looks made by hand, colored from the page palette with transparency behind the text, and animate the stroke drawing from left to right over about 800 ms when the phrase first scrolls into view.\nMeasure the phrase box, including multi-line wraps, and redraw the marks without animation whenever the text reflows on resize.\nWith prefers-reduced-motion, show the finished marks immediately; the marks are decorative, so wrap the words in a semantic emphasis element too.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "heartbeat-glow-pulse-border", category: "interface-style", aspect: null, prompt: "Add a heartbeat glow border to [which element, e.g. the main call-to-action panel]. Render a rounded frame on a canvas behind the element using a fragment shader: a thin border line, several soft colored spots sliding around it, and a wispy smoky glow spilling just outside the edge, all tinted from the palette.\nPulse the brightness and spread on a double-beat rhythm about once every 1.5 seconds, while the spots keep circling slowly.\nKeep the glow outside the content box and the panel surface opaque so text stays legible, and give the canvas pointer-events: none.\nUnder prefers-reduced-motion, show a steady glow with no pulsing; fall back to a CSS box-shadow if WebGL is unavailable.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "horizontal-parallax-gallery-strip", category: "interface-style", aspect: null, prompt: "Add a horizontal parallax gallery to [where to apply it, e.g. the work showcase section]: a row of tall image frames that moves sideways as the visitor scrolls vertically, drags, or swipes.\nSmooth the motion with linear interpolation so the strip glides to its target, and inside each frame shift the oversized image opposite to the travel direction based on how far the frame sits from the viewport center, giving depth.\nOptionally upgrade the frames to a WebGL canvas with a slight bend or wave at speed, keeping the DOM version as the fallback.\nSupport arrow keys and a visible scrollbar alternative, keep alt text on every image, and under prefers-reduced-motion use plain horizontal scrolling with no parallax.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "horizontal-scroll-letter-cascade", category: "interface-style", aspect: null, prompt: "Add a horizontal letter cascade to [where to apply it, e.g. a pinned statement section]. Pin the section and move one long sentence from right to left as the user scrolls through a tall runway. Start each letter scattered, shifted up or down and rotated, and as that letter travels from the right edge to about a third of the way across the screen, bring it back upright and aligned, so the sentence assembles as it passes. Base each letter's progress on its horizontal position within the moving line, not on vertical page scroll alone. Recompute on resize. Give the container an aria-label with the full sentence and hide the letter spans from assistive technology. Under prefers-reduced-motion, show the sentence aligned without pinning. Build it with plain HTML, CSS and vanilla JavaScript using requestAnimationFrame, with no external libraries, CDNs, fonts or network assets." },
  { id: "hover-highlight-grid-background", category: "interface-style", aspect: null, prompt: "Add a hover highlight grid behind [where to apply it, e.g. the hero section]: a field of square cells with hairline borders, slightly skewed and masked so it fades out toward the edges.\nWhen the pointer moves over a cell, fill it with a soft accent tint that fades in within about 100ms and lingers for half a second after the pointer leaves, so moving across the grid leaves a short glowing trail.\nThis is a decorative reaction only: it stores no selection, so keep it out of the tab order and away from screen readers, and let clicks pass through to real content above.\nOn touch, a tap lights a single cell briefly. With prefers-reduced-motion, switch cells on and off without fading or trails.\nUse plain HTML, CSS, inline SVG and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "hover-zoom-caption-card", category: "interface-style", aspect: null, prompt: "Apply a zoom photo caption card style to [which images, e.g. the gallery grid]. Each card clips its photo inside rounded corners; when activated, the image scales to about 1.08 over 400 ms and a caption panel with a soft dark gradient slides up from the bottom edge. Trigger the same state from hover, keyboard focus and a tap that toggles it with aria-pressed, so touch and keyboard users see exactly what mouse users see. Keep caption text high contrast against the gradient. Under prefers-reduced-motion, skip the zoom and simply fade the caption in. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "hypnotic-spiral-lines-background", category: "interface-style", aspect: null, prompt: "Add a hypnotic spiral to [where to apply it, e.g. the hero background or a loading screen]. Use a fragment shader on a canvas to draw a spiral of strokes from the center outward, with controllable density, stroke width that tapers toward the ends, and a little angular noise so the lines feel hand drawn; use two colors from the palette.\nRotate the spiral slowly and add a gentle time-based wobble, keeping the speed calm, around one turn every 20 to 30 seconds.\nKeep the spiral low contrast behind content, avoid high-contrast flashing stripes, and pause when the section is off screen.\nUnder prefers-reduced-motion, show a still spiral with no rotation.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "image-grid-hover-reveal", category: "interface-style", aspect: null, prompt: "Apply a hover reveal to the items in [which grid, e.g. the portfolio grid]. On hover or keyboard focus, scale the item's image down to about 90% and shift it to grayscale or a duotone tint, while a thin outlined box draws in around it and a large index number and title slide up letter by letter with a short stagger, over roughly 500ms in total; on leave, cancel any running enter motion and play the reverse. Keep the title and link available as real text at all times, so the reveal only changes emphasis. On touch screens, show the revealed state by default. With prefers-reduced-motion, switch states with a simple fade. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "image-thread-unravel-effect", category: "interface-style", aspect: null, prompt: "Add a horizontally drifting strip of images to [where to apply it, e.g. the gallery section], rendered on a WebGL canvas where each image is sliced into many thin vertical ribbons.\nAs a ribbon nears the left or right edge of the viewport, let it tear away from its neighbors and scatter with a small random offset per ribbon plus a gentle time-based wobble, then reassemble as it moves back toward the center.\nScroll or drag can nudge the drift speed; the motion should feel woven and calm, not chaotic.\nUnder prefers-reduced-motion show the images as a normal static row, and keep real img elements with alt text available so the content survives without WebGL.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "image-tile-menu-transition", category: "interface-style", aspect: null, prompt: "Add an image tile menu transition to [which menu, e.g. the projects list]. When a menu item is hovered or focused, show a small grid of tiles cut from that item's image beside it, popping in with a short stagger after a brief delay, and clear them cleanly when the pointer moves away. When the item is clicked, slide and scale the tiles together until they form the full image as the detail view opens, over about 800 ms, and reverse that on close. Cancel pending timers when the user moves quickly between items. Make every item a real link or button and keep the detail text readable on its own. Under prefers-reduced-motion, swap views with a crossfade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "inertia-draggable-stickers", category: "interface-style", aspect: null, prompt: "Add draggable stickers to [which section, e.g. the about section]. Scatter a few decorative badges and shapes that people can grab with mouse or touch: one slides only sideways inside the section, one spins when dragged around its center, and one moves freely. On release, carry the last drag velocity forward and let it decay with friction over about a second, bouncing softly off the section edges. Use pointer events with pointer capture and transforms only. Keep the stickers purely decorative so no content depends on moving them, and add a small reset button that returns them to their places. With prefers-reduced-motion, keep dragging but stop at release with no momentum. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "inertial-smooth-page-scroll", category: "interface-style", aspect: null, prompt: "Add inertial smooth scrolling to [which page or section, e.g. the whole landing page]. Keep native scrolling as the source of truth, but render the content inside a fixed wrapper whose translateY eases toward the real scroll position each frame (a lerp factor around 0.1), so movement glides and settles softly. Add decorative shapes with data-speed values that move faster or slower than the content, and let one shape hold in place for a few hundred pixels when it reaches the center. Make in-page links and a jump-to button land on the correct spot, keep the document height in sync on resize, and leave keyboard scrolling and find-in-page working. With prefers-reduced-motion, disable the easing and the speed differences. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "infinite-drag-parallax-grid", category: "interface-style", aspect: null, prompt: "Add an endlessly tiling image grid to [where to apply it, e.g. a full-screen gallery section] that the visitor can pan in any direction by dragging or with the wheel, with inertia that slows smoothly after release.\nWhen a tile leaves one edge, shift it by one full tile block so it reappears on the opposite side, making the wall feel infinite; give each column a slightly different speed and let the pointer add a subtle parallax shift.\nWhen tiles enter view, fade and lift their captions in with a short stagger.\nProvide arrow-key panning and a plain scrollable list fallback, and under prefers-reduced-motion drop inertia and parallax.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "infinite-pan-image-canvas", category: "interface-style", aspect: null, prompt: "Add an infinite pan image canvas to [which gallery section]: lay the images out on a loose tiled grid that repeats seamlessly in every direction, so the user can drag around forever without reaching an edge.\nDrag with mouse or touch to pan, release with smooth inertia that glides to a stop over about a second, and let the scroll wheel or trackpad pan as well.\nOnly render tiles near the viewport and reuse them as they leave, and give hovered images a slight scale-up with their caption.\nRespect prefers-reduced-motion by removing the inertia glide, add arrow-key panning and a plain list fallback of the images for keyboard and screen reader users, and keep any overlay text readable.\nBuild it with plain HTML, CSS and vanilla JavaScript, using canvas or WebGL written in the page if needed, with no external libraries, CDNs, fonts or network assets." },
  { id: "infinite-parallax-flip-gallery", category: "interface-style", aspect: null, prompt: "Add an infinite parallax gallery to [where to apply it, e.g. the portfolio page]. Repeat a set of images in a grid that wraps around seamlessly as the visitor scrolls, with each image shifting slightly inside its frame for a parallax feel and fading up as it enters. Clicking an image grows it from its grid position into a fullscreen view with a caption over about 700 ms, and closing shrinks it back to the same spot; if the user closes during the opening, reverse from where it is. Make each image a labeled button, trap focus in the open view and close on Escape. Under prefers-reduced-motion, drop the parallax and open views with a fade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "inline-image-layout-switch", category: "interface-style", aspect: null, prompt: "Add an inline image layout switch to [which headline or text block]: set large editorial text with small rounded images tucked between the words, and when the user clicks a toggle, move those images out of the sentence into a tidy column or grid.\nAs the images travel to their new spots over about 0.8 seconds, scatter the surrounding words out of view in different directions, then bring them back when switching back.\nMeasure each image before and after so the move is continuous, and block extra clicks until the switch completes.\nRespect prefers-reduced-motion by crossfading between the two layouts, keep the full sentence available to screen readers in both states, and keep the toggle reachable by keyboard.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "inline-word-flip-swap", category: "interface-style", aspect: null, prompt: "Apply an inline word flip to [which sentence, e.g. the hero tagline], swapping one word among [3 options].\nKeep the rest of the sentence still; on each click of a small button beside it, update the chosen word right away, then let the old word slide up and fade out while the new one slides in from below over about 350 ms inside a clipped slot that smoothly resizes to the new word's width.\nRepeated fast clicks always land on the latest word rather than queuing animations.\nWith prefers-reduced-motion, change the word instantly, and announce the new sentence politely to screen readers.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "instanced-cube-dither-field", category: "interface-style", aspect: null, prompt: "Add a dithered cube field to [where, e.g. the hero background]. In a WebGL canvas, draw a large grid of small cubes as one instanced mesh, giving each instance its normalized row, column and a threshold from a 4x4 ordered dithering matrix. Pass a single progress value and a grayscale source (a gradient or shape drawn on an offscreen canvas) as uniforms, and in the shader raise or color each cube when the source brightness passes its threshold, so a dithered image builds up as progress moves with scroll or a slow loop. Cap the grid size and pixel ratio on small screens, and fall back to a static image without WebGL. With prefers-reduced-motion, show the finished pattern still, and keep foreground text on a solid backing. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "kinetic-image-ring-band", category: "interface-style", aspect: null, prompt: "Add a kinetic image ring to [where to apply it, e.g. the hero section]: stitch the page's images side by side into one long strip and wrap it around a tilted 3D cylinder that turns slowly, so the pictures curve away at the edges.\nKeep a calm, constant rotation of about one full turn every 30 seconds, ease it faster while the user scrolls or drags, and let it settle back to the base speed within a second.\nOn hover, slightly brighten the ring; on touch, a horizontal swipe nudges the rotation with gentle inertia.\nRespect prefers-reduced-motion by showing the ring still at a pleasing angle, keep any headline above it fully readable, and make sure the images are also available as a plain list for screen readers.\nBuild it with plain HTML, CSS and vanilla JavaScript using WebGL or CSS 3D transforms written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "label-slide-hover-button", category: "interface-style", aspect: null, prompt: "Apply a sliding label hover effect to [which button, e.g. the main call-to-action]. At rest show a pill button with a small accent dot beside the label; on hover or keyboard focus, grow the dot until it fills the button, slide the original label off to the right while fading it, and slide in a copy of the label with an arrow from the left, all over about 300ms with an ease-out curve. Mark the decorative copy aria-hidden so the button keeps one accessible name, and keep the button width fixed so nothing around it shifts. On touch devices, show the filled state while pressed. With prefers-reduced-motion, switch to the filled state with a simple color change. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "layered-clip-image-wipe", category: "interface-style", aspect: null, prompt: "Add a layered image wipe transition to [which views or sections]: stack three or four full-screen image layers and sweep them across the screen one after another, each revealed by an expanding clip-path edge.\nKeep it brisk, around 0.9 seconds overall, with each layer starting slightly after the previous one; swap the page content while the last layer covers it, then peel that layer away to reveal the new view.\nTrigger it from links or buttons, ignore extra clicks until it finishes, and vary the wipe direction to match forward or back navigation.\nRespect prefers-reduced-motion by replacing the wipe with a simple fade, move focus to the new heading afterward, and keep the content readable and navigable without the effect.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "layered-depth-tilt-card", category: "interface-style", aspect: null, prompt: "Add a layered depth tilt to [which card, e.g. the product card in the hero]. Put the card in a CSS perspective container and rotate it up to about 12 degrees toward the pointer, while the title, image and badge inside sit on separate layers pushed forward with translateZ so they shift at different depths. Smooth the rotation with a short easing of about 150ms, and when the pointer leaves, glide the card back to flat over roughly half a second. On touch, tilt gently while a finger drags and settle on release. With prefers-reduced-motion, keep the card flat with only a light shadow lift on hover, and make sure all text stays readable at every angle. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "layered-depth-tilt-illustration", category: "interface-style", aspect: null, prompt: "Add a layered depth tilt effect to [which illustration or image]. Split it into three to five stacked layers (background, middle shapes, foreground), and provide a toggle button that switches between a flat view and a depth view. In depth view, push the layers apart along the Z axis with 3D transforms over about 400 ms, and tilt the whole stack a few degrees toward the pointer; in flat view, pointer movement does nothing. Expose the toggle state with aria-pressed and make it keyboard operable, and on touch let a tap on the toggle do the same job. Under prefers-reduced-motion, separate the layers without tilting or animating. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "layered-depth-zoom-scroll", category: "interface-style", aspect: null, prompt: "Add a layered depth zoom scroll to [where to apply it, e.g. the hero section]. Pin the section while the visitor scrolls through it, and arrange several images at different depths using CSS perspective; as progress grows, move the camera forward so near images scale up and slide past the edges while far ones sharpen from a light blur into focus, ending on a headline. Store progress in a CSS custom property and derive all transforms from it so the effect reverses when scrolling up. Keep the headline and any links readable in the final state on their own. Under prefers-reduced-motion, show the final composition without the zoom. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "layered-parallax-scene", category: "interface-style", aspect: null, prompt: "Add a layered parallax scene to [where to apply it, e.g. the hero section]. Build three or more layers, such as distant hills and near hills drawn as SVG shapes in the page's palette plus the headline, inside a sticky stage that stays in view while its taller track scrolls. Compute one progress value from the current scroll position and derive each layer's offset from it, with far layers moving least and the headline moving most, instead of accumulating changes from past events. Do not intercept wheel or touch input. Respect prefers-reduced-motion by fixing progress at zero so the scene stays still while content keeps scrolling normally, and keep the headline high-contrast against every layer. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "layered-parallax-waves-backdrop", category: "interface-style", aspect: null, prompt: "Add layered parallax waves to [where to apply it, e.g. the footer or hero section]: four smooth wave lines or filled bands stacked from back to front, each a slightly different shade of the page palette.\nGive every layer its own offset, slope and period so they drift sideways at different speeds, back layers slowest, building a calm sense of depth on a loop of about 10 to 20 seconds; on scroll, shift the layers vertically at different rates.\nThe waves carry no information, so keep the headline as a separate element above them with solid contrast.\nWith prefers-reduced-motion, freeze the waves in place, and stop animating while the section is off screen.\nUse plain HTML, CSS, inline SVG or canvas and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "letter-shuffle-menu-labels", category: "interface-style", aspect: null, prompt: "Add a letter shuffle effect to [which menu, e.g. the fullscreen navigation]. When the menu opens, each item label cycles through a few random uppercase letters per character slot before landing on the real letter, with slots settling left to right over about 600 ms and each item starting slightly after the previous one. Replay a shorter shuffle on hover or keyboard focus of an item. Keep the real label in the accessible name (for example with aria-label on the link and the animated letters aria-hidden) so screen readers never hear the noise. Under prefers-reduced-motion, show the final labels with a simple fade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "light-beam-tunnel-card", category: "interface-style", aspect: null, prompt: "Wrap [which card, e.g. the signup card] in a light beam tunnel. Around the card, build four CSS planes for the top, bottom, left and right walls, tilted with perspective so they recede to a vanishing point behind it, each drawn with a faint grid and two or three short glowing beams in accent colors.\nSend the beams along the walls toward the viewer on loops of 3 to 6 seconds with staggered delays, giving a sense of speed while the card stays perfectly still.\nKeep the card on its own layer with a solid surface so its content stays readable, and give the wrapper enough padding to fit narrow screens.\nUnder prefers-reduced-motion, hide the moving beams and keep the still tunnel grid.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "light-sweep-shimmer-button", category: "interface-style", aspect: null, prompt: "Apply a light sweep to [which button, e.g. the pricing call-to-action]. Overlay an aria-hidden pseudo-element holding a narrow, slanted white gradient band at low opacity, clipped to the button, and move it from beyond the left edge to beyond the right edge over about 800ms, repeating every 5 seconds. Also run one sweep on hover or focus so the button feels responsive. The sweep is purely decorative, so do not use it to signal loading or success, and keep the label crisp and fully readable as it passes. With prefers-reduced-motion, remove the sweep and keep a subtle static sheen. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "line-grid-pattern-card", category: "interface-style", aspect: null, prompt: "Apply a line grid pattern surface to [which cards, e.g. the feature cards]. Draw a thin repeating grid of hairlines with an inline SVG or CSS gradients, then lay a dark gradient over it that is nearly solid at one corner and lets the lines show through toward the other, so the texture feels like it fades into depth. Wrap each card in a one-pixel outer frame in a slightly lighter tone of the page palette, and let the pattern scale with the card so it never looks cropped at wide sizes. The effect is static, so no motion fallback is needed, but keep body text on a calm area of the gradient with strong contrast. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "line-mask-rise-replay", category: "interface-style", aspect: null, prompt: "Apply a line mask rise to [which text, e.g. the page intro heading and lead paragraph].\nSplit the text into its rendered lines, wrap each line in an overflow-hidden mask, and on load slide every line up from fully below its mask while fading in, with about 100 ms between lines and roughly 700 ms per line.\nInclude a small replay button that restarts the sequence at one fifth speed so the motion can be studied, and rebuild the lines on resize so the newest split is the one being animated.\nKeep the original text accessible as plain text, and with prefers-reduced-motion show all lines at once and hide the replay button.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "liquid-chrome-flow-background", category: "interface-style", aspect: null, prompt: "Add a liquid chrome background to [where to apply it, e.g. the hero section or a logo badge]. Use a full-size canvas with a WebGL fragment shader that draws tight, glossy bands of silver highlight and shadow, bends them with smooth noise so they flow like molten metal, and adds a faint red and blue channel offset at the band edges for an iridescent sheen.\nLet the surface drift slowly on a continuous loop, and on hover speed it up slightly and ease back over about a second.\nPlace text above the surface on a solid or darkened panel so it stays legible, and pause rendering when the section is off screen.\nUnder prefers-reduced-motion, render a single still frame; if WebGL fails, fall back to a CSS gradient in grey and white tones.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "list-enter-exit-reorder-animation", category: "interface-style", aspect: null, prompt: "Apply enter, exit and reorder motion to [which list, e.g. the task list]. Before every change, measure each item; after adding, shuffling or removing items in the DOM, animate the remaining ones from their old positions to the new ones with transforms over about 400ms. New items scale and fade in from 0.8, and removed items stay in place while they scale and fade out, then are taken out of the DOM once their own exit finishes, even if another change starts meanwhile. Keep focus on a sensible item after a removal and announce additions and removals in an aria-live region. With prefers-reduced-motion, apply the changes instantly. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "list-to-grid-view-morph", category: "interface-style", aspect: null, prompt: "Add a scroll stretch effect and an animated list-to-grid toggle to [which collection, e.g. the article list]. As each item leaves the top of the viewport, scale its image to roughly 2.4 times its height and 1.2 times its width inside a clipped frame while fading it out, tied directly to scroll. Add a clearly labeled toggle button that switches between the list and a compact grid; on switch, record each image's old box, apply the new layout, and animate every image from its old box to its new one over about 0.6 seconds, cancelling any running switch if clicked again. Respect prefers-reduced-motion by skipping the stretch and changing views instantly, expose the toggle state with aria-pressed, and keep titles readable in both views. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "magnetic-pull-hover-button", category: "interface-style", aspect: null, prompt: "Add a magnetic pull to [which buttons, e.g. the hero call-to-action buttons]. When the pointer comes within about 80px of a button, translate the button toward it by up to roughly a third of the distance, capped at 12-16px, and move the label slightly further for a layered feel; ease the motion with a short transition or a lerp in requestAnimationFrame. When the pointer leaves, spring the button back to its resting spot over about 400ms. Only enable this for fine pointers that can hover, and keep the click target and focus outline in place. With prefers-reduced-motion, leave the buttons still. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "magnifier-zoom-lens", category: "interface-style", aspect: null, prompt: "Add a magnifier lens to [which image, e.g. the main product photo]. While the pointer is over the image, show a round lens about 160px wide that displays the same picture zoomed to around 2.5 times, centered on the spot under the pointer, with a thin ring and soft shadow. Fade the lens in over 150ms and out when the pointer leaves; on touch, show it under a pressing finger and hide it on release. Mark the zoomed copy as hidden from assistive technology so the image is only described once, and let Escape dismiss the lens. With prefers-reduced-motion, show and hide it without fades. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "magnifying-icon-dock-bar", category: "interface-style", aspect: null, prompt: "Add a magnifying icon dock to [where to apply it, e.g. the bottom of the page]. Line up the icons in a frosted rounded bar; as the pointer moves along it, scale each icon based on its distance from the pointer, up to about 1.6 times for the nearest, with neighbors growing less, easing smoothly with a spring-like follow. When the pointer leaves, ease everything back. Each icon is a real link or button with an accessible name and a tooltip label, and keyboard focus enlarges only the focused icon. On touch, skip magnification and keep the icons tappable. Under prefers-reduced-motion, use a simple highlight instead of scaling. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "make-way-expanding-grid", category: "interface-style", aspect: null, prompt: "Add a make-way expanding grid to [which grid of cards or images]: when a tile is hovered or clicked, scale it up smoothly while every other tile slides away from it, pushed farther the closer it sits, so the grid parts like a crowd making room.\nAnimate over about 0.6 seconds with a soft ease, cancel and redirect cleanly if the user moves to another tile mid-animation, and return everything to rest when the pointer leaves.\nOn touch, a tap expands a tile and a second tap or tap elsewhere collapses it; keyboard focus does the same as hover.\nRespect prefers-reduced-motion by highlighting the chosen tile with an outline instead of moving the others, keep labels readable at every size, and keep tiles clickable throughout.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "masked-line-scroll-reveal", category: "interface-style", aspect: null, prompt: "Add a masked line scroll reveal to [which paragraphs, e.g. the about section copy].\nSplit each paragraph into its currently rendered lines, wrap every line in an overflow-hidden mask, and start each line pushed down below its mask.\nTie the reveal to scroll so lines slide up one after another as the paragraph moves from mid-screen toward the top, and reverse when scrolling back; each paragraph gets its own range.\nWhen the viewport is resized, rebuild the lines from the original text and reconnect the scroll progress so nothing is left stuck half-hidden, and keep the original paragraph text available to screen readers.\nWith prefers-reduced-motion, show all lines immediately.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "menu-row-to-grid-thumbnails", category: "interface-style", aspect: null, prompt: "Add a menu to grid thumbnail transition to [which list, e.g. the collections menu]. Each menu row shows a title with a few small thumbnails; when a row is opened, measure where every thumbnail sits now and where it belongs in a larger preview grid, then animate each one from the old position to the new one over about 800 ms with a slight stagger while the other rows fade away. Going back reverses the motion, returning thumbnails to their row and bringing titles back in a cascade from the chosen row. Use real buttons for rows, move focus to the preview heading on open and back to the row on close. Under prefers-reduced-motion, switch views with a crossfade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "meteor-shower-streaks-background", category: "interface-style", aspect: null, prompt: "Add a meteor shower to [where to apply it, e.g. a dark hero or a feature card]. Create 15 to 30 small bright dots, each trailing a thin fading gradient tail, and send them diagonally across the area from random starting points measured against the container itself, not the window.\nGive every meteor its own duration between 2 and 8 seconds and a random delay so they arrive in an irregular rhythm, then recompute starting points when the container is resized.\nClip the meteors to the container, keep them behind the content with pointer-events: none, and keep them away from small text.\nUnder prefers-reduced-motion, hide the moving meteors and leave a few faint still streaks.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "minimap-hover-preview-list", category: "interface-style", aspect: null, prompt: "Add a hover preview with a minimap to [which items, e.g. the project thumbnails list].\nWhen the pointer is over a thumbnail, open a large preview panel showing a zoomed region of that image, plus a small minimap outline of the full image with a dot or rectangle marking the cursor's spot.\nMap the cursor's position within the thumbnail to both the preview's pan and the minimap marker, smoothing it with requestAnimationFrame, and fade the panel in and out over about 0.2s.\nOn touch or keyboard focus, show the preview centered without tracking, and under prefers-reduced-motion skip the fades; the thumbnails and their links must keep working when the preview is not shown.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "mirrored-floor-reflection", category: "interface-style", aspect: null, prompt: "Add a mirrored reflection beneath [which content, e.g. the horizontal gallery or the hero cards]. Render a decorative copy of the content flipped vertically below it, faded with a gradient mask from about 30 percent opacity to transparent and lightly blurred, so it reads like a glossy floor. Each animation frame, translate the reflection by the negative of the current scroll offset so it moves in step with the real content, and apply the same rotation, depth and filter animations to each item and its mirrored twin. Mark the reflection aria-hidden and non-interactive so focus and clicks only reach the real items. Respect prefers-reduced-motion by keeping the reflection static or hiding it, and make sure the text above stays crisp. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "morphing-progress-state-button", category: "interface-style", aspect: null, prompt: "Apply a three-state morph to [which button, e.g. the form's submit button]. On click, disable the button, shrink its label away and show a small spinning ring with a short 'Sending' message; when the real task resolves, swap the ring for a checkmark that draws itself with an SVG stroke over about 300ms and a 'Done' message, then return to the idle label after 2 seconds; on failure, show an error state instead. Drive the states from the actual result, never from a fixed timer, and announce each change through an aria-live region. Keep the button width stable between states. With prefers-reduced-motion, change the states with simple crossfades and a static icon. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "multi-row-logo-marquee", category: "interface-style", aspect: null, prompt: "Add a multi-row logo marquee to [which section, e.g. the trusted-by section]. Lay out several horizontal lanes, each carrying a few logo chips that glide continuously from one side to the other with their own speed and starting offset, so the lanes feel staggered rather than in sync. Build the lane count from the data so missing lanes leave no gap, and soften both edges with a fade. Draw the moving band on a canvas sized to the band and sharp at the device pixel ratio, painting the logo chips each frame, and give the canvas role=\"img\" with an aria-label that lists them, so no readable text or logo ever sits half-clipped at an edge. Pause the motion on hover and add a visible pause button. With prefers-reduced-motion, show the logos as a still wrapped grid of plain images. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "neon-gradient-glow-card", category: "interface-style", aspect: null, prompt: "Apply a neon gradient glow to [which card, e.g. the highlighted plan card]. Give the card a rounded rim filled with a two-color neon gradient taken from the page palette, and behind it a blurred copy of the same gradient that spills outward as a soft halo. Slowly rotate the gradient angle over about eight seconds so the colors drift around the rim, and brighten the halo a little on hover or focus. Size the rim and halo from the card's live box with a ResizeObserver so they stay aligned when fonts load or the layout changes. With prefers-reduced-motion, keep the gradient still, and keep the card's inner surface solid so its text stays crisp and readable. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "neural-glow-web-background", category: "interface-style", aspect: null, prompt: "Add a neural glow web behind [where to apply it, e.g. the hero or an AI feature section]. On a canvas, write a fragment shader that layers warped noise into a mesh of thin, branching luminous strands over a dark base, with brighter sparks where strands cross; use one accent color for the sparks and a muted mid tone for the strands.\nLet the web flow and pulse on a slow continuous loop, and brighten it slightly around the pointer on hover or touch.\nKeep the layer decorative and behind the content, dim it under text blocks so copy stays readable, and pause rendering when off screen.\nUnder prefers-reduced-motion, render one still frame.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "opposing-column-scroll-grid", category: "interface-style", aspect: null, prompt: "Add an opposing column scroll effect to [which gallery, e.g. the work grid]. Lay out three image columns and, while the section scrolls, translate the middle column upward and the outer columns downward, scaled to the scroll progress so the motion reverses smoothly. Clicking an image enlarges it to about 70% of the viewport height in a detail view with its title, and closing returns it to its spot. Keep the DOM order matching the visual reading order, and make each image a button with a label. Under prefers-reduced-motion, keep the columns static and open details without movement. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "opposing-wrapper-scene-slider", category: "interface-style", aspect: null, prompt: "Add a full-screen scene slider to [where to apply it, e.g. the landing page sections] with four or five stacked scenes. Each scene has an outer wrapper and an inner wrapper that slide in opposite directions during a change, so the content feels peeled into place, and the heading letters appear in a shuffled order over roughly 0.8 seconds. Move forward or back with one wheel tick, a vertical swipe, or the arrow and Page keys, wrapping from the last scene to the first, and ignore new input until the current transition finishes. Add visible previous and next buttons plus a small scene counter so keyboard and screen reader users can navigate, and offer a way to read every scene as normal scrolling content. Under prefers-reduced-motion, switch scenes with a short crossfade and show headings whole. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "orbiting-circle-badge-text", category: "interface-style", aspect: null, prompt: "Add orbiting circle text to [where to apply it, e.g. beside the hero call-to-action], using [the phrase, e.g. a short repeating slogan].\nSplit the phrase into letters and place each one around a circle so the spacing is even and the letters face outward, sizing the ring in em units and giving the container an explicit square size so it takes up proper layout space.\nRotate the whole ring continuously, one full turn about every 12 seconds, slowing down on hover and reversing direction on click or tap; an icon or logo can sit still in the center.\nHide the individual letters from assistive tech and keep the phrase once as readable text, and with prefers-reduced-motion keep the ring still.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "orbiting-dot-matrix-background", category: "interface-style", aspect: null, prompt: "Add an orbiting dot matrix behind [where to apply it, e.g. the hero section]: a grid of round dots where every dot circles around the center of its own cell on a small, slightly different path and speed.\nRender it in a WebGL fragment shader with uniforms for cell size, dot radius, per-dot size variation, orbit spread (zero means dots sit still but keep their look) and a palette of two or more page colors with extra blended steps between them.\nLet the pointer widen the orbits a little nearby.\nWith prefers-reduced-motion, render the dots at rest with no orbit, and pause rendering when off screen; keep the dots faint behind text so headings stay readable.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "orbiting-icon-rings-visual", category: "interface-style", aspect: null, prompt: "Add an orbiting icon rings visual to [where to apply it, e.g. the integrations section]. Place a central logo or badge with two or three thin, faint circular paths around it, and spread small icons evenly along each ring. Rotate each ring at its own pace (for example 20, 30 and 40 seconds per turn), with the middle ring turning the opposite way, while counter-rotating the icons so they stay upright. The motion is purely decorative, so give the icons accessible names or list the same items as text nearby, and pause the rings on hover. Under prefers-reduced-motion, show the rings and icons at rest. Build it with plain HTML, CSS and vanilla JavaScript using CSS transforms or inline SVG, with no external libraries, CDNs, fonts or network assets." },
  { id: "orbiting-light-border-button", category: "interface-style", aspect: null, prompt: "Add a traveling border light to [which button, e.g. the primary hero button]. Behind the button's inner surface, place a rotating conic-gradient layer that is mostly transparent with one bright arc in the accent color, and inset the solid surface by about 1.5px so only a thin rim of that layer shows; rotate it with a linear 3-second loop so a spark circles the edge. On hover, speed the loop up slightly, and nudge the button down 1px while pressed. Keep the label rendered once, readable, and above every decorative layer. With prefers-reduced-motion, stop the rotation and show an evenly lit static border. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "organic-wave-curtain-reveal", category: "interface-style", aspect: null, prompt: "Add an organic wave curtain to [where to apply it, e.g. the full-screen menu]: two stacked SVG layers in related accent colors whose edges are built from about twenty control points, so they sweep across the screen as soft, uneven waves.\nWhen toggled, animate each column of points toward its target with a small random delay, rebuilding the cubic path string every frame; the back layer leads and the front layer follows about 100ms later, taking around 1 second overall.\nIgnore new toggles until the current motion finishes so commands never pile up, and drive it from a real button with aria-expanded and focus moved into the opened content.\nWith prefers-reduced-motion, show and hide the overlay with a short fade.\nUse plain HTML, CSS, inline SVG and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "origami-arrow-3d-object", category: "interface-style", aspect: null, prompt: "Add a spinning origami object to [where to apply it, e.g. beside the hero headline]: build a faceted shape such as four folded arrows meeting at a center, with flat paper-like faces in the page's palette and crisp light and shadow on each fold.\nTilt each arrow on its own axes in a slow five-second loop while the whole group turns once every ten seconds, so the object constantly refolds its silhouette.\nOn hover, let it lean toward the pointer slightly; on touch, a drag spins it and it eases back into its loop.\nRespect prefers-reduced-motion by showing it still at a flattering angle, keep it decorative so it never covers text or controls, and hide it from screen readers.\nBuild it with plain HTML, CSS and vanilla JavaScript using WebGL, canvas or CSS 3D transforms written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "outline-spotlight-fill-text", category: "interface-style", aspect: null, prompt: "Apply an outline spotlight fill to [which text, e.g. the hero title].\nShow the text as a thin outline with transparent fill, and layer a solid-colored copy on top that is masked to a soft-edged circle about 160 px wide; mark the copy as decorative so the words are read once.\nThe circle follows the pointer smoothly with a short lag of about 100 ms, shrinks away when the pointer leaves, and on touch it appears where the finger rests.\nWith prefers-reduced-motion, fill the whole title solidly with no tracking, and make sure the outline alone still meets readable contrast.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "parallax-fullscreen-slideshow", category: "interface-style", aspect: null, prompt: "Add a parallax fullscreen slideshow to [where to apply it, e.g. the landing hero]: each slide fills the viewport, and on change the whole slide travels across the screen while its image moves only about a third as far in the opposite direction, creating a deep, layered glide.\nUse a smooth ease of roughly one second, show the next slide's title rising in just after the image settles, and loop from the last slide back to the first.\nControl it with arrow buttons, arrow keys and swipe, and only accept a new move once the current one is finished.\nRespect prefers-reduced-motion by switching slides with a quick fade and no parallax, keep text over images readable with a soft gradient shade, and expose the slide count to screen readers.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "parallel-wave-lines-pattern", category: "interface-style", aspect: null, prompt: "Add parallel wave lines to [where to apply it, e.g. the section behind a quote]. Fill the area with evenly spaced horizontal lines drawn as SVG paths or on a canvas, each following the same wave whose shape can sit anywhere between zigzag, smooth sine and slightly irregular, with adjustable amplitude, frequency, spacing and stroke width in a muted palette tone.\nKeep the pattern still by default, and optionally shift the phase slowly on scroll so the waves seem to roll as the section passes.\nKeep line contrast low under text, mark the layer aria-hidden, and give it pointer-events: none.\nUnder prefers-reduced-motion, drop the scroll-linked phase shift.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "particle-emitter-svg-cursor", category: "interface-style", aspect: null, prompt: "Add a particle emitter cursor to [where to apply it, e.g. the hero section]. Draw a small SVG dot that eases after the pointer, and as it moves, emit a few tiny circles in accent colors that drift outward in the direction of travel, shrink and fade over about 800ms. Spawn more particles the faster the pointer moves and cap the total so it stays light. Run everything in one requestAnimationFrame loop that you keep a handle to, stop it when the pointer leaves or the tab is hidden, and remove listeners if the section is torn down. Keep the native cursor available, skip the effect on touch, and with prefers-reduced-motion show only the small dot with no particles. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "particle-fountain-press-effect", category: "interface-style", aspect: null, prompt: "Add a particle fountain to [which elements, e.g. the playful buttons and links in the footer]. While the pointer is held down on one of them, emit small colored circles or simple emoji-like shapes from the cursor every few frames, each shooting upward with a random sideways drift, then falling under gravity and fading out within about a second; cap the count at roughly 45 live particles. Put the particles in one fixed overlay layer that ignores pointer events, stop emitting the moment the pointer is released or leaves, and remove the layer content when no particles remain. Clicks must still work normally. With prefers-reduced-motion, emit nothing. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "perspective-glitch-hover", category: "interface-style", aspect: null, prompt: "Add a perspective glitch hover to [which cards or images, e.g. the team portraits]. Stack several copies of the image inside a container with perspective: the base image plus layers pixelated at different strengths (draw each to a small canvas and scale up without smoothing). On hover or focus, tilt the stack a few degrees in 3D, turn on the extra layers with small offsets, and make the top layer flicker with a stepped animation about every 0.5s; on touch, play it briefly on tap. With prefers-reduced-motion, disable both the tilt and the flicker and show a simple outline instead, and never flash more than three times per second. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "perspective-grid-flyby", category: "interface-style", aspect: null, prompt: "Add a perspective grid scroll to [which section, e.g. the gallery between hero and footer]. Lay out the images in a grid inside a container with about 1000px perspective, tilted on the x axis so it recedes like a floor. As the section scrolls through, move each tile along its own horizontal and depth range, picked randomly within a set span per tile, so the grid seems to scatter and regroup as it sweeps past, with distant tiles slightly dimmer. Offer a second layout variant where the grid turns on the y axis instead. Respect prefers-reduced-motion by showing a flat, untilted grid, and keep captions outside the transformed layer so they stay sharp. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "phrase-cycle-scramble-text", category: "interface-style", aspect: null, prompt: "Add a phrase cycle scramble to [which text, e.g. a statement block below the hero], rotating through [3-4 phrases].\nOn each click, move to the next phrase immediately, then animate the visible text through random characters that resolve into the new phrase over about 1.5 seconds, revealing from left to right; a new click overrides the running animation and targets the latest phrase.\nOne phrase can get a distinct accent style, such as a border or color from the page palette, applied as it settles.\nKeep the current phrase in an accessible label so screen readers hear it once and never the shuffled characters, and with prefers-reduced-motion swap phrases instantly.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "pinned-horizontal-scroll-gallery", category: "interface-style", aspect: null, prompt: "Add a pinned horizontal gallery to [where to apply it, e.g. the portfolio section]. Pin the section and translate a long row of image cards sideways as the visitor scrolls down, with the travel distance measured as the row's full width minus the viewport width and remeasured on resize, so the last card lands exactly at the right edge before the pin releases. Show a small progress bar or counter in sync. Keep the cards in normal DOM order and focusable so keyboard users can tab through them, scrolling each into view. Under prefers-reduced-motion or on narrow touch screens, use a plain swipeable row with scroll snapping instead. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "pinned-list-progress-indicator", category: "interface-style", aspect: null, prompt: "Add a pinned list with a vertical progress line to [which section, e.g. the four-step how-it-works block]. Pin the section while the user scrolls through it and split that distance into equal steps: at each step the current list item turns the accent color, the previous one fades back to muted text, and a matching image beside the list slides in to replace the last one. A thin vertical line next to the list starts a quarter filled and grows to full height with the same progress, holding briefly at the end before the section releases. Derive every layer from one shared progress value so nothing drifts when scrolling quickly or backwards. Respect prefers-reduced-motion by unpinning and showing every item with its image in a plain stacked layout, and keep the highlight decorative rather than acting as a selection. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "pixel-grid-distortion-hover", category: "interface-style", aspect: null, prompt: "Add a pixel grid distortion to [which image, e.g. the hero image]: divide the image into a coarse grid of cells and, as the pointer moves across it, push the nearby cells' sampling offsets in the direction of motion so the picture smears into chunky pixels.\nScale the push by pointer speed, then let every cell relax back to its true position over about a second so the image heals behind the cursor.\nCompute pointer positions relative to the image's own box so it works anywhere on the page, and on touch apply the same effect along the drag.\nRespect prefers-reduced-motion by showing the clean image with no distortion, keep any caption over it readable, and fall back to a plain image if WebGL is unavailable.\nBuild it with plain HTML, CSS and vanilla JavaScript using WebGL or canvas written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "pixel-grid-page-transition", category: "interface-style", aspect: null, prompt: "Add a pixel grid page transition between [which views or sections]: cover the viewport with a grid of square tiles in the page's accent color that switch on one by one in a diagonal or random wave until the screen is filled.\nWhile fully covered, swap the content, then switch the tiles off in a new wave to reveal the next view; aim for about 0.5 seconds each way.\nTrigger it from navigation links or buttons, block repeated clicks until the reveal finishes, and make sure the new content is in place even if a transition is interrupted.\nRespect prefers-reduced-motion by using a quick fade instead of the tile wave, move focus to the new view's heading after the swap, and keep the content fully usable if the script fails.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "pixel-tile-image-reveal", category: "interface-style", aspect: null, prompt: "Apply a pixel tile reveal to [which image, e.g. the hero photo]. Split the image area into a grid of square tiles drawn from a single image, for example with a canvas or background-position, and make the tiles pop in one by one in a random order over about a second, starting in grayscale. Once the image has actually finished loading and every tile is placed, fade the whole picture into full color. Start the reveal when the image scrolls into view, and keep one meaningful alt text for the picture rather than one per tile. With prefers-reduced-motion, show the finished color image at once. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "pixelated-image-reveal", category: "interface-style", aspect: null, prompt: "Add a pixelated reveal to [which images, e.g. the case study thumbnails]. Draw each image into a canvas at a very low resolution with image smoothing turned off, then step through progressively finer pixel sizes until it matches the original, holding the first coarse step for about 300ms and then advancing every 80ms or so. Start the sequence once when the image first enters the viewport and do not replay it. Begin only after the image has actually loaded, and if loading fails, show a neutral placeholder rather than a frozen pixel grid. Respect prefers-reduced-motion by showing the finished image immediately, and keep the real image's alt text available to assistive technology. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "playful-scroll-hide-header", category: "interface-style", aspect: null, prompt: "Apply a playful hide-and-reveal motion to [which fixed element, e.g. the top navigation bar].\nWhen the visitor scrolls down past a small threshold, tuck the bar away with character: its letters or links drop out one by one with a slight stagger, or the bar squashes and slips upward; when they scroll up, it springs back in.\nOffer two or three variants in code and pick one, cancelling any running animation before starting the next so quick direction changes stay clean and the bar always ends in its original markup.\nKeep the bar visible while it holds keyboard focus or is near the top of the page, and under prefers-reduced-motion simply slide it out and in without the playful stagger.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "pointer-contrast-grid-hover", category: "interface-style", aspect: null, prompt: "Add a pointer-driven grid effect to [which grid, e.g. the hero image grid].\nOn load, play a short intro where the images scale up from small and fade in with a stagger; afterward, track the pointer's horizontal distance from the center and use it to raise image contrast and brightness near the edges, tilt the images slightly toward the pointer, and shrink them a touch.\nUse a squared easing on the distance so the change feels gentle near the center, and smooth updates with requestAnimationFrame.\nOn touch devices skip the tracking and leave the images neutral, keep any captions readable, and under prefers-reduced-motion show the finished grid without the intro or pointer reactions.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "pointer-drift-particle-field", category: "interface-style", aspect: null, prompt: "Add a floating particle field behind [where to apply it, e.g. the hero section]. On a canvas sized to the container and device pixel ratio, draw a fixed number of small dots, 50 to 150 depending on area, with varied size and opacity, colored from the page palette; create them once and reuse the same array on resize.\nLet each dot drift slowly with a slight random wander, and when the pointer is inside the area, shift the dots by an amount scaled to their size so near ones move more and the field feels deep; ease back to rest when the pointer leaves or a touch ends.\nKeep the canvas behind content with pointer-events: none and pause the loop when off screen.\nUnder prefers-reduced-motion, draw the dots once and skip all motion.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "pointer-lit-dot-field", category: "interface-style", aspect: null, prompt: "Add a pointer-lit dot field behind [where to apply it, e.g. the features section]: a regular grid of small dots in a faint tone, plus a second, brighter copy of the grid masked by a radial gradient centered on the pointer so dots near it glow and grow slightly.\nUpdate the mask center through CSS custom properties from pointermove, easing it toward the pointer in about 150ms; add a few thin dashed rings that turn slowly around the center for depth.\nOn touch devices, park the light at the center of the section.\nWith prefers-reduced-motion, stop both the following light and the rotating rings together and keep a fixed glow; the dots are decorative and never carry content.\nUse plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "pointer-spotlight-card-border", category: "interface-style", aspect: null, prompt: "Add a pointer spotlight to [which cards, e.g. the pricing cards]. As the pointer moves over a card, place a soft radial glow at the pointer position inside the card and a brighter, tighter version of the same glow on its border, so the edge nearest the pointer lights up. Update the position from local pointer coordinates through CSS custom properties, fade the glow in over about 200ms on enter and out on leave, and also fade it when the window loses focus. On touch devices show a gentle static glow on the tapped card instead. With prefers-reduced-motion, keep a fixed subtle border highlight, and make sure card content stays readable with the glow off. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "pool-caustics-water-background", category: "interface-style", aspect: null, prompt: "Add pool caustics to [where to apply it, e.g. the hero section or an image]. In a fragment shader, draw bright, wobbly web-like light patterns over a cool base color, add a second fainter caustic layer moving at a different speed, and gently distort the underlying image or color with small noise waves as if seen through water.\nKeep the caustics shimmering on a slow continuous loop, and on pointer move add a small local ripple that fades within a second.\nKeep text on a calm area or on a panel above the effect, and pause rendering when off screen.\nUnder prefers-reduced-motion, show a single still frame of the pattern.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "press-burst-letter-headline", category: "interface-style", aspect: null, prompt: "Add a press-to-burst effect to [which headline, e.g. the hero title], splitting it into individual letter spans while keeping the original text available to screen readers.\nWhile the pointer is held down over the headline, letters within a small radius of the press point fly outward with a slight spin and scale change, turning into small geometric chips tinted from the page palette; letters farther away only nudge a little.\nOn release, every letter eases back to its home position over about 600 ms with a gentle overshoot, and touch presses behave exactly like mouse presses.\nWith prefers-reduced-motion, skip the scatter and only brighten the letters near the press point, and keep the headline fully readable whenever nobody is pressing.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "progressive-edge-blur-scroll", category: "interface-style", aspect: null, prompt: "Apply a progressive edge blur to [which scrollable area, e.g. the testimonial list]. Stack six to eight thin layers over the bottom (and optionally top) 30 to 40 percent of the scroll container, each with a stronger backdrop-filter blur and a linear-gradient mask covering a slightly different band, so content melts into a smooth graduated blur instead of a hard fade.\nHide the bottom blur when the user reaches the end of the list and the top blur at the very start, easing the change over about 200ms.\nGive the layers pointer-events: none, add enough bottom padding that the last item can scroll fully clear of the blur, and fall back to a plain gradient fade where backdrop-filter is unsupported.\nThe blur itself is static, so prefers-reduced-motion users only lose the short fade.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "pulse-ring-attention-button", category: "interface-style", aspect: null, prompt: "Apply a pulsing ring to [which button, e.g. the main sign-up button]. Place an aria-hidden ring behind the button in its own background color, and loop a keyframe animation every 1.5 seconds that scales the ring from 1 to about 1.5 while fading it from 60% opacity to transparent, so the button seems to breathe. Read the color from a CSS custom property so it follows the page palette, and pause the pulse on hover and focus so the button settles when the user is about to act. Keep the label and button size unchanged. With prefers-reduced-motion, drop the loop and show a static soft outline instead. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "radial-fan-action-menu", category: "interface-style", aspect: null, prompt: "Add a radial fan menu to [which button, e.g. the floating action button in the corner]. Pressing the round trigger rotates its plus icon into a cross and fans three to five circular action buttons out along a quarter arc about 120 px away, each one popping in with a small overshoot and a 40 ms stagger. Closing pulls them back in reverse, slightly faster. Use aria-expanded on the trigger, close on Escape or an outside click, and make hidden items truly unreachable with inert or hidden rather than just invisible; open items need visible labels or tooltips. Under prefers-reduced-motion, show and hide the items instantly. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "radial-spotlight-glow-background", category: "interface-style", aspect: null, prompt: "Add a radial spotlight glow to [where to apply it, e.g. the dark hero section]. Paint a deep navy or near-black base and lay a single radial-gradient of the page's accent color at about 30 to 40 percent alpha on top, centered on the main content or anchored a little below the top edge, with a fixed radius around 500 to 600px so the light stays a focused pool on wide screens.\nKeep it static by default; optionally let the center follow the pointer with a slow 400ms ease on desktop only.\nCheck that text inside the brightest part of the glow still meets contrast, and keep the background purely decorative.\nUnder prefers-reduced-motion, drop any pointer following and keep the still glow.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "radiant-god-rays-background", category: "interface-style", aspect: null, prompt: "Add radiant god rays behind [where to apply it, e.g. the hero headline]: a WebGL fragment shader that fans beams of light out from a glowing point near the top of the section, blending warm or accent colors from the page palette into the background.\nProvide uniforms for ray count, how broken or spotty the rays are, ray intensity, the size and brightness of the central glow, and a bloom-style additive blend; let the rays slowly turn and breathe on a cycle of about 15 seconds.\nOn hover, shift the light source a little toward the pointer.\nWith prefers-reduced-motion, render one still frame; keep the brightest area away from body text, or add a subtle scrim, so copy stays readable.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "rainbow-glow-gradient-button", category: "interface-style", aspect: null, prompt: "Add a rainbow glow style to [which button, e.g. the hero call-to-action]. Give the button a dark solid fill, a 2px border painted with a wide red-orange-yellow-green-blue-violet linear gradient, and a blurred copy of that gradient just below it as a glow; animate the gradient's background-position so the colors drift along the border on a loop of about 2 seconds. Brighten the glow slightly on hover and focus-visible, and show a clear focus ring that stays visible against the colors. Keep the label in high-contrast white. With prefers-reduced-motion, freeze the gradient in place. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "random-letter-scramble-text", category: "interface-style", aspect: null, prompt: "Add a scramble reveal to [which text, e.g. the navigation labels]. On page load and again on hover or focus, replace each character with random uppercase letters or symbols for a few frames, then lock the real characters in from left to right over about 0.6 seconds, giving each character a fixed-width span so the width does not jump. On touch, a tap replays it. Handle text whose length changes, and never leave a scrambled state if the pointer leaves early: always end on the original text. Keep the real text available to screen readers with an aria-label and hide the animated characters. Under prefers-reduced-motion, show the text without scrambling. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "reading-progress-bar", category: "interface-style", aspect: null, prompt: "Add a reading progress indicator to [which scroll area, e.g. the whole page or the article body]. Pin a thin bar in the accent color to the top edge, below any fixed header, and scale it horizontally from 0 to 100 percent, with an optional small percentage label in a corner. Compute progress on every scroll as the current offset divided by the maximum scrollable distance of the chosen area, and recompute on resize and whenever the content height changes. Animate the bar with a transform rather than width so it stays smooth. Respect prefers-reduced-motion by updating without easing, expose it with a progressbar role and aria-valuenow, and make sure it never covers navigation or text. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "refractive-glass-cube-scene", category: "interface-style", aspect: null, prompt: "Add an interactive glass scene to [where to apply it, e.g. the hero background]. Render a few softly drifting cubes with a refractive, lightly tinted glass look in a WebGL canvas, and project wavy caustic light patterns onto the floor beneath them with a shader. Moving the pointer, or dragging on touch, sends a ripple through the caustics and nudges nearby cubes, easing back over about two seconds. Offer an optional sound toggle, off by default, that adds a quiet tone whose volume follows the ripple strength, and fully silence and stop the audio when it is switched off. Under prefers-reduced-motion, render a single still frame; pause the loop when the canvas is off screen, and keep overlaid text readable with a contrast scrim. Build it with plain HTML, CSS and vanilla JavaScript, writing the WebGL and Web Audio code in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "repeated-layer-image-hover", category: "interface-style", aspect: null, prompt: "Add an echo layer image hover to [which images or cards]: inside each image frame, stack four or five copies of the same picture, each inset a little more than the last, so on hover they zoom in one after another to form a tunnel of nested frames.\nStagger the copies by about 60 milliseconds over a 0.7-second ease, and when the pointer leaves, play the same motion in reverse from wherever it currently is.\nTrigger the same effect on keyboard focus, and on touch run it once per tap without trapping the link.\nRespect prefers-reduced-motion by showing a single subtle zoom on the base image instead, hide the decorative copies from screen readers, and keep captions readable over the frame.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "repeating-frame-trail-transition", category: "interface-style", aspect: null, prompt: "Add a repeating frame trail transition to [which images, e.g. the gallery thumbnails opening to a full view]. When an image moves from its thumbnail to its expanded position, interpolate the center and size between the start and end boxes and place a series of copies at the in-between steps, offset along a gentle sine curve with a little random wobble, then reveal them one after another over about 0.8s and remove them in the same order so the image appears to leave an echoing trail. Run it in reverse when closing. Use transforms only and keep the copies aria-hidden. With prefers-reduced-motion, swap directly or crossfade. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "rgb-split-square-lens", category: "interface-style", aspect: null, prompt: "Add a cursor-following square lens to [which image, e.g. the hero photo]. Inside a rounded square that trails the pointer with a short easing, show a second version of the image that is gently bulged and has its red, green and blue channels offset by a few pixels, while the area outside stays the normal picture. Draw it in a WebGL or 2D canvas written in the page, correct the lens shape for the image's aspect ratio, and add a subtle animated ripple inside the square. Grow the lens in when the pointer enters and shrink it out when it leaves; on touch, show it where the finger rests. With prefers-reduced-motion, show the plain image with no lens, and keep any caption outside the effect. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "ripple-cube-grid-background", category: "interface-style", aspect: null, prompt: "Add a ripple cube grid behind [where to apply it, e.g. the hero section]: a dense floor of small square blocks seen from a slight tilt, shaded in two or three tones from the page palette.\nAs the pointer moves, store its recent positions with timestamps; each block rises based on its distance to those points and their age, so circular wavefronts spread outward and decay over about 1.5 seconds, with a capped maximum height.\nOn touch, taps send a single ripple; when idle, the floor rests flat.\nWith prefers-reduced-motion, keep the grid still and skip the ripples, and dim the grid where text sits so headings stay readable.\nUse plain HTML, CSS and vanilla JavaScript with canvas or WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "rotating-badge-editorial-cover", category: "interface-style", aspect: null, prompt: "Add an editorial cover treatment to [where to apply it, e.g. the hero section]. Set a short headline in oversized, tightly tracked type with strong contrast against a flat background taken from the page palette, and place a circular badge of text on a path beside it that slowly rotates, about one turn every 12 seconds. Include a round arrow button next to the badge; pressing it reveals a short intro line in a polite live region, and its accessible name must describe exactly that result. On hover the arrow nudges a few pixels and the badge spins a little faster; on touch the pressed state is enough. Respect prefers-reduced-motion by stopping the rotation and keeping the badge still, and make sure the headline wraps cleanly on narrow screens. Build it with plain HTML, CSS and vanilla JavaScript using inline SVG for the badge, with no external libraries, CDNs, fonts or network assets." },
  { id: "rotating-cylinder-scroll-text", category: "interface-style", aspect: null, prompt: "Add a rotating cylinder of text to [where to apply it, e.g. a pinned section]. Place several short lines around a half or full ring using CSS 3D transforms, with the radius tied to the shorter side of the viewport, and pin the section while the user scrolls through a tall runway so scroll progress turns the ring around its horizontal axis, roughly one and a half turns across the runway. Fade lines as they rotate toward the back so the front line stays clear. Recompute the radius on resize and skip updates while the section is off screen. Keep the same lines as a plain list in reading order for assistive technology. Under prefers-reduced-motion, show the lines as a static stacked list without pinning. Build it with plain HTML, CSS and vanilla JavaScript using requestAnimationFrame, with no external libraries, CDNs, fonts or network assets." },
  { id: "rotating-dot-globe", category: "interface-style", aspect: null, prompt: "Add a rotating dot globe to [which section, e.g. the hero's right column]. Draw a sphere made of evenly spaced glowing dots in WebGL or canvas written in the page, with a soft atmospheric rim and a few brighter marker dots, and turn it slowly on its vertical axis. Let people drag horizontally to spin it faster, easing back to the idle speed with a spring-like feel after release, and pause rotation when it is off screen. Add small rotate-left and rotate-right buttons as a non-drag alternative, and treat the globe as decoration with any real location info given in text. With prefers-reduced-motion, show a still globe. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "rotating-wireframe-globe", category: "interface-style", aspect: null, prompt: "Add a rotating wireframe globe to [where to apply it, e.g. the global reach section]. Draw a sphere outline with fixed latitude lines and a set of meridians that sweep around the vertical axis, so the ellipses widen and narrow as they turn, using thin strokes in the page's accent color with lines on the far side dimmed. One full turn should take around 20 seconds, and hovering can speed it up slightly. Treat the globe as decoration: it is not a map, so give it aria-hidden and keep any real locations in text. Under prefers-reduced-motion, show the globe still. Build it with plain HTML, CSS and vanilla JavaScript using inline SVG or canvas, with no external libraries, CDNs, fonts or network assets." },
  { id: "rounded-expanding-cover-menu", category: "interface-style", aspect: null, prompt: "Add a rounded expanding menu to [which navigation]. The closed menu is a small pill button; on press, it grows into a large rounded panel covering the page over about 700 ms while the page content behind it shrinks slightly and darkens, then the links rise in one after another. Closing reverses the sequence. Ignore extra clicks while a transition is running so states never tangle. Mark the button with aria-expanded, trap focus inside the open panel, close on Escape and return focus to the button. Under prefers-reduced-motion, open and close with a plain fade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "row-hover-floating-image-preview", category: "interface-style", aspect: null, prompt: "Add a floating image preview to [which list, e.g. the project index rows]. When the pointer enters a row, show that row's image (or a generated poster shape in the page palette) right at the pointer and let it follow with a soft eased lag of about 0.4 seconds, scaling and fading in over 250ms. On the first entry, start the image at the current pointer position so it never flies in from the previous row, and when leaving the list fade it out, then remove the movement listener. Show the same preview beside a row when it receives keyboard focus, and skip the effect on touch. With prefers-reduced-motion, show the preview in a fixed spot without following. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-3d-ring-carousel", category: "interface-style", aspect: null, prompt: "Add a 3D ring carousel that rotates with scroll to [which gallery, e.g. the featured work section]. Place the image cards around a vertical axis by dividing 360 degrees by the card count and giving each card a rotateY plus a translateZ equal to a configurable radius, inside a container with CSS perspective. While the section is pinned, map scroll progress to the ring's rotation so about one full turn happens across the pinned distance, dimming cards that face away for depth. Hovering a front card can lift it slightly, and touch scrolling drives the ring the same way. Respect prefers-reduced-motion by laying the cards out as a flat grid without rotation, and keep each card's caption and link reachable by keyboard. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-assembled-layout-formation", category: "interface-style", aspect: null, prompt: "Add a scroll-assembled layout to [where to apply it, e.g. the gallery intro]. Pin the section while the visitor scrolls, starting with the images pushed well below the viewport at varied distances, and bring each one up into its final grid cell as progress grows so the layout snaps together piece by piece, with the heading rising and fading in alongside. Release the pin once everything is in place. Make sure the final layout and heading are fully visible if the script does not run. Under prefers-reduced-motion, show the assembled layout from the start. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-bento-expand-gallery", category: "interface-style", aspect: null, prompt: "Add a scroll-scrubbed bento gallery to [which section, e.g. the gallery section]. Start with a compact bento grid of images with one large central tile, and define a second, expanded layout where the central image grows to fill the viewport and the others spread outward. Measure both layouts, then pin the section and map scroll progress to each tile's position and size between the two (a FLIP-style interpolation with transforms), so the user scrubs the transition back and forth. On resize, clear inline styles, re-measure and rebuild. With prefers-reduced-motion, keep the compact grid static and fully visible. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-blur-letter-reveal", category: "interface-style", aspect: null, prompt: "Add a blurry scroll reveal to [which paragraph or heading]. Split the text into letters and start each one blurred, slightly dim and transparent; as the block moves through the viewport, map scroll progress to the letters in order so they sharpen and brighten one after another, finishing when the block reaches the middle of the screen. Scrolling back up reverses the progress. When the window is resized, remove the old listeners and rebuild the split and the progress mapping. Keep the full sentence available to assistive technology through an aria-label, with the letter spans hidden from it. Under prefers-reduced-motion, show the text sharp from the start. Build it with plain HTML, CSS and vanilla JavaScript using requestAnimationFrame for scroll updates, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-crossfade-photo-stack", category: "interface-style", aspect: null, prompt: "Add a scroll crossfade photo stack to [where to apply it, e.g. the story section]. Pin three or more photos on top of each other in a sticky frame while a tall scroll track passes by, and compute a single progress value from 0 to 1 for that track. Give each photo a center point along the progress and set its opacity from the distance between progress and that center, so scrolling backward or jumping gives the same frame. Pair each photo with a short caption that fades in sync. Under prefers-reduced-motion, show the photos as a simple vertical list. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-curved-path-motion", category: "interface-style", aspect: null, prompt: "Add scroll curved path motion to [where to apply it, e.g. the steps section]. Draw a smooth SVG curve that winds from one section to the next, computed from the positions of anchor points in the layout, and move a small marker or icon along it as the visitor scrolls, with the stroke drawing in behind it. Recalculate the curve on resize while keeping the current progress, so it stays aligned on any screen size. The path is decorative, so mark it aria-hidden and keep every step's content in normal reading order. Under prefers-reduced-motion, show the full path drawn with the marker at the end. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-direction-hiding-header", category: "interface-style", aspect: null, prompt: "Apply a scroll-aware hiding header to [which header]. Keep the header fixed at the top, and when the visitor scrolls down past the first screen, slide it up out of view over about 250 ms; as soon as they scroll up, slide it back in. Ignore tiny scroll jitters with a small threshold, always show it near the top of the page, and never hide it while something inside it has keyboard focus. Add a soft shadow once the page has scrolled. Under prefers-reduced-motion, keep the header simply visible without sliding. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-drawn-map-route", category: "interface-style", aspect: null, prompt: "Add a scroll-drawn map route to [where to apply it, e.g. the journey section]. Use an inline SVG illustrated map with a route path; as the visitor scrolls, draw the path progressively with a stroke-dash reveal, move a small marker along its tip, and pan and zoom the map gently so the marker stays near the center. Pop in labelled stop markers as the route reaches them, with matching text cards beside the map. Keep the stops listed in the text so the story works without the map, and offer a button to expand the map full width that closes on Escape. Under prefers-reduced-motion, show the whole route drawn and the map static. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-driven-css-carousel", category: "interface-style", aspect: null, prompt: "Add a scroll-driven carousel to [where to apply it, e.g. the featured stories row]. Use a horizontal scroller with scroll snapping, and give each slide a view timeline so it grows to full size and opacity as it reaches the center and shrinks and dims toward the edges, while its description and a numbered indicator update in sync. Add previous and next buttons and numbered links that scroll to each slide. Where scroll-driven animations are unsupported, fall back to a plain snapping carousel that still shows every image and description. Under prefers-reduced-motion, keep all slides at full size. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-rotating-cube-gallery", category: "interface-style", aspect: null, prompt: "Add a scroll rotating cube gallery to [where to apply it, e.g. the showcase section]. Build a cube from six faces with CSS 3D transforms, sized from its container width so the front and back faces sit half a width away, and place one image and short caption on each face. Pin the section and map scroll progress across its height to the cube's rotation, turning 90 degrees per step with a slight smoothing lag so it feels weighty. Provide the same images and captions as an ordinary list for screen readers and for viewports too narrow for the cube. Under prefers-reduced-motion, show that list instead of the rotating cube. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-stretch-image-preview", category: "interface-style", aspect: null, prompt: "Add a scroll stretch image preview to [which list of stories or projects]: as each tall preview image enters the viewport, scale its inner picture vertically from the top edge while its title drifts upward, giving a stretching, elastic feel tied to scroll position.\nWhen a preview is clicked, expand that image to fill the screen over about 0.9 seconds, then slide in the detailed content below it, with a back button that reverses the transition.\nKeep the motion smooth by driving it from scroll progress rather than timers.\nRespect prefers-reduced-motion by keeping images at their normal size and opening content with a fade, move focus to the opened content's heading, and keep titles readable throughout.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-velocity-direction-marquee", category: "interface-style", aspect: null, prompt: "Add a scroll direction marquee to [where to apply it, e.g. between two sections]. Repeat a short phrase in large type across an endless horizontal ribbon at a calm base speed, wrapping seamlessly. When the user scrolls or swipes, jump to about six times the speed in the scroll direction, then ease back to normal speed over roughly a second while keeping the new direction; a fresh input replaces any easing already in progress. Draw the moving band on a canvas sized to the band and sharp at the device pixel ratio, painting the phrase each frame, and give the canvas role=\"img\" with an aria-label that lists them, so no readable text or logo ever sits half-clipped at an edge. Re-measure on resize so the loop stays seamless. Pause the loop on hover and while it is off screen. Under prefers-reduced-motion, show the phrase once as static text. Build it with plain HTML, CSS and vanilla JavaScript using requestAnimationFrame, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-velocity-image-skew", category: "interface-style", aspect: null, prompt: "Add a velocity skew to [which images, e.g. the gallery images]. Each frame, read the scroll velocity, scale it down and clamp the result to about plus or minus 20 degrees, and accept a new value only when it is stronger than the current skew; then ease the skew back to zero over about 0.8s. Apply it as skewY on all images at once with a single style write per frame. Keep text unskewed so it stays readable. With prefers-reduced-motion, leave the images straight. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-velocity-rgb-distortion", category: "interface-style", aspect: null, prompt: "Add a scroll-speed distortion to [which images, e.g. the project thumbnails]. Render the images in WebGL, sharing one renderer and one canvas behind the page where possible, and compute a single clamped scroll velocity value that eases back to zero over about 0.8s after scrolling stops. Feed that value to a fragment shader that bends the image vertically and offsets the red and blue channels in opposite directions, so fast scrolling makes the pictures stretch and fringe while slow scrolling leaves them clean. Handle resize, release GPU resources when images leave the page, and fall back to plain images without WebGL. With prefers-reduced-motion, keep the velocity at zero so images stay clean. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-wipe-image-reveal", category: "interface-style", aspect: null, prompt: "Add a scroll-driven before-and-after wipe to [which pair of images, e.g. the product comparison section]. Stack two images of identical size and pin the section while the user scrolls through a distance about equal to its width; during that stretch the top image's frame slides in from the right while the picture inside it slides the opposite way, so the second image appears to be uncovered by a moving edge rather than pushed across. Draw a thin vertical divider in the page's accent color along that edge and map progress directly to scroll position so scrolling back reverses it smoothly, with touch following native scrolling and no extra gestures. Respect prefers-reduced-motion by skipping the pin and showing both images side by side with captions, and give both images meaningful alt text. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-word-highlight-reveal", category: "interface-style", aspect: null, prompt: "Add a word-by-word reveal to [which statement, e.g. the mission paragraph]. Place the paragraph in a sticky block inside a track about twice the viewport height, split it into words, and show each word as a faint ghost with a solid copy on top whose opacity rises as scroll progress passes that word's slice of the track. Compute everything from the current progress so scrolling back dims the words again. Expose the original sentence once to screen readers and hide the split copies, and make sure long paragraphs fit the sticky block on small screens. With prefers-reduced-motion, show the full sentence at full opacity. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "scroll-zoom-frame-reveal", category: "interface-style", aspect: null, prompt: "Add a scroll zoom frame reveal to [which image, e.g. the feature photo]. Start the photo as a small rounded frame, roughly 40% of the viewport wide, centered in a sticky stage, with a title laid over it. As the visitor scrolls through a tall section, grow the frame to the full viewport and flatten its corners, and fade the title out before the halfway point so text never balloons with the image. Drive every change from one scroll progress value so the effect reverses cleanly. Under prefers-reduced-motion, show the image full width with the title above it. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "shader-wipe-page-transition", category: "interface-style", aspect: null, prompt: "Add a liquid wipe transition between pages or views for [which links, e.g. the main navigation].\nOn an internal link click, raise a full-screen canvas overlay whose edge is a soft animated wave in the page's accent color, sweep it upward over about 0.7s until it covers the screen, swap the content underneath, then continue the sweep off the top to reveal the new view.\nWhile covering, the overlay accepts pointer events so stray clicks are ignored; afterward it is hidden and passes input through again.\nMove focus to the new heading after the swap, and under prefers-reduced-motion replace the wave with a quick plain fade; if WebGL is unavailable, draw the wave with a CSS clip-path instead.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "shape-aware-ascii-art", category: "interface-style", aspect: null, prompt: "Add a shape-aware ASCII render to [where to apply it, e.g. the hero visual]. Draw a simple solid, such as a torus or an extruded version of the page's logo shape, in an offscreen WebGL or canvas pass, then divide the frame into character cells and, for each cell, choose the printable glyph whose own shape best matches the light and edges inside that cell rather than only its brightness, so outlines read cleanly. Show the result as a monospace grid in a color from the page palette, rotate the shape slowly, and let the user drag with mouse or finger to spin it, with inertia that fades within a second. Under prefers-reduced-motion, show one still frame and keep dragging optional. Give the canvas a short text alternative. Build it with plain HTML, CSS and vanilla JavaScript, writing any shader code in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "shape-morph-image-reveal", category: "interface-style", aspect: null, prompt: "Apply a scroll-driven shape morph to [which images, e.g. the three chapter covers]. Animate each image's clip-path between polygons with the same number of points, for example from a narrow diamond to a full rectangle, scrubbed by scroll so the frame opens as it nears the center, while the image inside scales down slightly for depth. Split the nearby heading into letters that fade and rise in a quick stagger once the image is mostly open. On pointer hover add a gentle 3D tilt of a few degrees that eases back on leave, and skip the tilt on touch. Respect prefers-reduced-motion by showing the full rectangle and whole text at once, and keep the original heading text available to screen readers rather than only the split letters. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "shifting-glyph-matrix", category: "interface-style", aspect: null, prompt: "Add a shifting glyph matrix behind [which section, e.g. the developer features section]. Fill a canvas with an even grid of small monospace-style symbols such as dots, plus signs and slashes in a low-contrast tone, and every 90ms or so swap a handful of random cells to new symbols with a quick fade, letting a few briefly flash in the accent color. Use the system monospace font, treat each symbol as a whole character rather than splitting strings by index, and adapt colors to light and dark themes. Hide the canvas from assistive technology and pause it off screen. With prefers-reduced-motion, show a still matrix. Keep content above it with a calm backing so text stays readable. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "shimmer-skeleton-content-swap", category: "interface-style", aspect: null, prompt: "Add shimmering skeleton placeholders to [which area, e.g. the article card list] that swap into the real content when it arrives. Stack the placeholder and the finished card in the same grid cell with a shared minimum height, so the swap never changes the layout. Sweep a soft diagonal highlight across the gray blocks about every 1.5 seconds, and when the content is ready cross-fade only the opacity over roughly 300ms. Mark the region busy while loading and announce once when it is ready. With prefers-reduced-motion, keep the placeholders still and swap instantly. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "sliced-reunite-scroll-text", category: "interface-style", aspect: null, prompt: "Apply a sliced reunite effect to [which text, e.g. a large section title].\nRender several decorative copies of the word, each clipped to one vertical slice of equal width, and start them shifted up and down by different amounts so the word looks cut and scattered.\nAs the title scrolls from the bottom of the viewport to the middle, ease every slice back to zero offset so the word becomes whole exactly at center, and reverse on scroll up; recalculate slice widths when the text or viewport size changes.\nHide the slices from assistive tech and keep one real copy of the text for screen readers.\nWith prefers-reduced-motion, show the assembled word with no offsets.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "sliding-pill-tab-indicator", category: "interface-style", aspect: null, prompt: "Apply a sliding pill tab style to [which tab set, e.g. the pricing period switch]. Place the tabs in a rounded track and draw one highlight pill behind the active tab; on selection, move and resize the pill to the new tab over about 300 ms with a soft ease while the panel content crossfades. Measure the tab sizes so it also works for labels of different lengths and after resizing. Use proper tablist, tab and tabpanel roles with aria-selected and arrow-key navigation. Under prefers-reduced-motion, jump the pill and content without animating. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "smooth-follower-cursor-dot", category: "interface-style", aspect: null, prompt: "Add a smooth follower cursor to [where to apply it, e.g. the whole page]. Show a soft circle in an accent color from the page palette that glides after the pointer, centered on it, with an eased lag of about 0.6 seconds so it catches up gracefully rather than snapping. Keep a single animation loop that always chases the latest pointer position, grow the circle slightly over links and buttons, and shrink it on press. Keep the native cursor visible underneath so precision is never lost, and hide the follower on touch devices and when the pointer leaves the window. With prefers-reduced-motion, remove the follower entirely. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "spherical-icon-cloud", category: "interface-style", aspect: null, prompt: "Add a spherical icon cloud to [which section, e.g. the tools we use section]. Spread 20 to 30 small icons drawn as inline SVG or simple monograms evenly over an invisible sphere, project them onto a canvas or with CSS transforms, and scale and fade each icon by its depth so the back ones look farther away. Rotate the sphere slowly, let a drag spin it toward the pointer direction, and ease back to idle after release. Provide a visible pause button that stays respected even after dragging, stop the loop off screen, and list the same tools in text for screen readers. With prefers-reduced-motion, start paused. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "split-unit-text-entrance", category: "interface-style", aspect: null, prompt: "Apply a split text entrance to [which heading or paragraph]. Break the text into letters, words or lines, choosing the unit that suits the copy, by wrapping each piece in a span, and slide each piece up from below with a fade and a slight rotation, staggered by about 30 milliseconds for letters or 80 for words, finishing within one second. Play it once when the text first scrolls into view; whenever the container width changes, undo the previous split and split again so line breaks stay correct. Keep the original sentence available to screen readers with an aria-label on the container and aria-hidden on the pieces. With prefers-reduced-motion, show the text immediately without movement. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "spring-count-up-number-ticker", category: "interface-style", aspect: null, prompt: "Add a count-up number ticker to [which figures, e.g. the stats row]. Each number starts from zero (or from a start value) and eases toward its real target over about 1.5 seconds with a soft spring-like settle, formatted with thousands separators and any prefix or suffix such as % or +. Start the count only once the figure scrolls into view, run it once, and use tabular figures so the digits do not jitter in width. Put the final value in the markup so screen readers and copy-paste always get the true number, and under prefers-reduced-motion show the final value immediately. Build it with plain HTML, CSS and vanilla JavaScript using IntersectionObserver and requestAnimationFrame, with no external libraries, CDNs, fonts or network assets." },
  { id: "stack-to-gallery-transition", category: "interface-style", aspect: null, prompt: "Add a stack to gallery unfold to [which project or collection]: show the images first as a neat, slightly offset stack, and when the stack is clicked, deal the images out into a horizontal gallery row while a panel of descriptive text slides in beside it.\nAnimate each image from its stacked spot to its gallery spot over about 0.9 seconds with a short stagger, and offer previous, next and close controls inside the open view.\nClose the gallery and restack the images when the user presses the close button, presses Escape or scrolls away, but never while an animation is still running.\nRespect prefers-reduced-motion by crossfading between stack and gallery, move focus into the open view and back to the stack on close, and keep the text readable in both states.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "stacked-card-deck-carousel", category: "interface-style", aspect: null, prompt: "Add a stacked card deck to [where it goes, e.g. the testimonials section]. Show three to five cards on top of each other, each one behind offset a little lower, scaled down slightly and dimmed, so the pile has depth. A Next button (and the right arrow key when the deck is focused) slides the front card up and away, then tucks it behind the pile while the others step forward over about 500ms; update the order from the current index immediately so fast clicks always land on the right card. Hide the back cards from assistive tech and show a '2 of 5' style counter. With prefers-reduced-motion, change the front card with a simple fade. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "staggered-batch-fade-reveal", category: "interface-style", aspect: null, prompt: "Add a staggered reveal to [which items, e.g. the image cards]. Watch the items with IntersectionObserver and collect the ones that enter the viewport at the same moment into a batch; animate each batch so its items fade from transparent and rise about 24px into place over 1s, with a 0.2s delay between neighbors. Run the reveal once per item and do not hide items again when they leave. Make sure items stay visible if JavaScript fails by adding the hidden starting state only from script. With prefers-reduced-motion, show everything immediately. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "staggered-column-grid-scroll", category: "interface-style", aspect: null, prompt: "Add staggered column motion to [which image grid, e.g. the portfolio gallery]. While the grid passes through the viewport, shift each column vertically by an amount proportional to its index so neighboring columns drift against each other, and give every image a small extra offset tied to its own entry and exit. For wide layouts, offer a variant where rows slide horizontally in opposite directions instead. Keep the motion scroll-scrubbed and subtle, around 10 to 20 percent of a tile's height, and clip images so edges never show gaps. Respect prefers-reduced-motion by leaving the grid static, and keep every image's link and alt text intact. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "staggered-letter-entrance-text", category: "interface-style", aspect: null, prompt: "Apply a staggered letter entrance to [which text, e.g. the hero title].\nSplit the text into letter spans (keeping words together so lines never break mid-word) and animate each letter from slightly below with zero opacity and a touch of blur into place, starting each about 30 ms after the previous one with a total run under one second.\nPlay it when the text first enters the viewport, and add a small replay button for the demo; leaving the viewport or stopping motion finishes the animation so every letter is visible.\nKeep the full sentence available to screen readers and hide the letter spans, and with prefers-reduced-motion show the text immediately.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "stepped-noise-contour-background", category: "interface-style", aspect: null, prompt: "Add a stepped noise contour background to [where to apply it, e.g. the features section]. In a WebGL fragment shader, blend two layers of smooth simplex-style noise into organic shapes, then map the value onto three or four palette colors with a few extra in-between steps per color, giving crisp topographic bands with a slightly softened edge.\nAdvance the noise slowly over time so the bands creep and reshape on a calm loop, without any sudden jumps.\nKeep the layer behind the content, choose band colors close enough in value that overlaid text keeps its contrast, and pause rendering when off screen.\nUnder prefers-reduced-motion, render one still frame; if WebGL is unavailable, fall back to a flat palette color.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "sticky-column-grid-reveal", category: "interface-style", aspect: null, prompt: "Add a sticky column grid to [which section, e.g. the about section]. Inside a tall scroll track, pin a three-column image grid and group the images by column. As the user scrolls, play it in stages: first the outer columns slide in from opposite vertical directions while the middle column holds, then the whole grid scales down slightly to make room, and finally a heading, short description and button fade in over it. Keep the text and button reachable by keyboard before they are revealed, revealing them at once when focused. With prefers-reduced-motion, show the final layout without pinning. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "sticky-section-exit-transition", category: "interface-style", aspect: null, prompt: "Apply a stacked sticky-section exit to [which sections, e.g. the three feature chapters]. Make each section stick to the top so the following section slides up over it, and while it is being covered, scale it down to about 0.9, darken it with a black overlay growing to around 60 percent, and move its inner image upward with a small rotation, all scrubbed by scroll position. If a section's content is taller than the viewport, let the user scroll through that content first and start the exit only after its end. Leave the last section untouched so the page ends on a clean, readable state. Respect prefers-reduced-motion by removing the sticky stacking and overlays so sections read as normal blocks, and keep links inside them clickable at all times. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "striped-drift-shadow-text", category: "interface-style", aspect: null, prompt: "Apply a striped drift shadow to [which word, e.g. the key word in the hero title].\nBehind the real text, draw a decorative copy offset a few pixels down and right, filled with thin diagonal stripes in a color taken from the page palette (adjusting for light and dark themes), and mark that copy as decorative so it is never read twice.\nAnimate the stripe pattern so it slides steadily along its diagonal in a seamless loop of about 15 seconds; hovering the word can speed the drift up slightly.\nWith prefers-reduced-motion, keep the striped shadow still, and make sure the foreground text keeps strong contrast against the background with or without the shadow.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "sun-moon-morph-toggle", category: "interface-style", aspect: null, prompt: "Add a light and dark theme toggle button to [where to apply it, e.g. the top navigation]. Stack a sun icon and a moon icon drawn in inline SVG in the same spot; when the state changes, the outgoing icon shrinks, turns slightly and fades while the incoming one grows back to full size, taking about 250 milliseconds. Make the button really switch a theme attribute on the root element, remember the choice in local storage, and update aria-pressed plus an accessible label that names the next action. Give it a soft hover background and a clear focus ring, and keep the tap target at least 44 pixels on touch screens. With prefers-reduced-motion, swap the icons instantly without scaling. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "svg-clip-scroll-typography", category: "interface-style", aspect: null, prompt: "Add clip path scroll typography to [which section, e.g. a poster-style divider]. Show one or two large words filled with an image or a bold gradient, cut out by two SVG clip paths that slide horizontally by different amounts as the section passes through the viewport, while the fill inside drifts slightly the other way for a parallax feel. Keep the mask motion and the inner fill motion as separate transforms. Scrolling back reverses everything smoothly. Keep the words as real text in the page for screen readers and search, hiding the decorative SVG copy. Under prefers-reduced-motion, show the words fully revealed and still. Build it with plain HTML, CSS and vanilla JavaScript using inline SVG and requestAnimationFrame, with no external libraries, CDNs, fonts or network assets." },
  { id: "svg-path-curved-marquee", category: "interface-style", aspect: null, prompt: "Add an infinite marquee that follows a curve across [where to apply it, e.g. the section below the hero], with logos, words or small cards spaced evenly along it.\nDefine the curve as an SVG path used only for geometry and sample it with getPointAtLength. Each frame, paint the items along the curve on a canvas sized to the band and sharp at the device pixel ratio, rotating each one to the path tangent, and give the canvas role=\"img\" with an aria-label that lists the items, so no readable text or logo ever sits half-clipped at an edge.\nMove the items at a slow steady pace, wrapping from the end of the path back to the start, and rescale the curve with the section width so it fits any screen.\nLet pointer movement or a drag briefly speed up or reverse the flow, easing back to the base speed afterward, and pause on hover.\nUnder prefers-reduced-motion, stop the movement and show the items as a plain list in document order.\nBuild it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "sweeping-shine-gradient-border", category: "interface-style", aspect: null, prompt: "Add a sweeping shine border to [which card, e.g. the pricing or signup card]. Paint an oversized multicolor gradient from the palette behind the card and use a mask that excludes the content box so only a 1 to 2px ring shows; keep the inner surface opaque.\nSlide the gradient's background position on a smooth 8 to 14 second loop so the shine travels around the edge in both directions, and brighten it slightly on hover or focus.\nMake clear the shine is decoration, not a loading or success state, and keep all inputs and labels inside fully usable.\nUnder prefers-reduced-motion, freeze the gradient in place.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "swirling-sprite-particle-field", category: "interface-style", aspect: null, prompt: "Add a swirling particle field to [where to apply it, e.g. the hero section]: about one hundred small shapes (dots, rings or a simple mark drawn once to an offscreen canvas) scattered around a center point.\nEach particle orbits, rotates and grows or shrinks on its own staggered loop of a few seconds; draw them every frame sorted by scale so larger ones appear in front, giving a sense of depth.\nNudge the swirl a little toward the pointer on hover, and recompute the canvas size and orbit radius on resize at the device pixel ratio.\nWith prefers-reduced-motion, draw a single still frame, and stop the animation loop entirely while the canvas is off screen; keep content above it fully readable.\nBuild it with plain HTML, CSS, canvas and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "swirling-warp-pattern-background", category: "interface-style", aspect: null, prompt: "Add a swirling warp pattern to [where to apply it, e.g. a bold promo banner]. In a fragment shader, start from a simple base pattern such as checks or stripes in two or three palette colors, then bend it with smooth noise and a few stacked swirl passes so the shapes melt into flowing curls.\nAnimate the distortion slowly on a continuous loop, and on hover speed up the swirl a little and ease back over about a second.\nKeep the pattern as a decorative backdrop, put text on a solid panel above it, and avoid fast high-contrast flicker.\nUnder prefers-reduced-motion, show one still frame; if WebGL fails, show the undistorted base pattern in CSS.\nBuild it with plain HTML, CSS and vanilla JavaScript, writing the shader in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "synthwave-horizon-grid-background", category: "interface-style", aspect: null, prompt: "Add a synthwave horizon grid to [where to apply it, e.g. the hero section]. Build a large grid of thin neon lines on a CSS plane tilted back with perspective so it vanishes at a horizon line, fade the far rows into a dusky gradient sky, and place a low glowing sun disc with horizontal cut-out stripes behind the horizon.\nScroll the grid toward the viewer by exactly one cell on a seamless 1 to 2 second loop to create a feeling of forward travel, while the sun and headline stay fixed.\nKeep the headline above the sun with strong contrast and keep the grid decorative with pointer-events: none.\nUnder prefers-reduced-motion, stop the grid in place and keep the still scene.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "thermal-heatmap-shape-glow", category: "interface-style", aspect: null, prompt: "Add a thermal heatmap glow to [which shape, e.g. the brand mark in the hero]: turn the shape's silhouette into a thermal-camera look, cool blues at the edges warming to yellow and white at its hottest, with bands of heat sweeping across it.\nPreprocess the shape once into an outline, an inner blur and an outer blur, then in a WebGL fragment shader map a moving intensity wave through a thermal color ramp, with controls for contour strength, inner and outer glow and sweep angle.\nOn hover, let the heat gather toward the pointer.\nThis is decoration, not data: do not label it as a chart. With prefers-reduced-motion, show one still frame; give the shape an accessible label and a plain fallback.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "three-d-flip-card", category: "interface-style", aspect: null, prompt: "Add 3D flip cards to [where they go, e.g. the team member cards]. Give each card a front and back face stacked in the same space with backface-visibility hidden, a perspective of about 1000px on the wrapper, and rotate the inner element 180 degrees on the Y axis over about 600ms when the card's toggle button is pressed. Update aria-pressed and hide the face that is turned away from assistive tech the moment the button is pressed, so state never waits for the animation, and let repeat clicks reverse the turn midway. Keep both faces the same size. With prefers-reduced-motion, crossfade between the faces instead of rotating. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "thumbnail-expand-morph-transition", category: "interface-style", aspect: null, prompt: "Add a thumbnail-to-full-view morph to [which images, e.g. the product gallery thumbnails]. When a thumbnail is clicked, record its bounding box, show the large version in its final position, then use the FLIP technique (first, last, invert, play) with transforms to animate it from the thumbnail's box to the large one over about 450ms with an ease-in-out curve; clicking the large image or pressing Escape plays it back into the thumbnail. Move keyboard focus to the expanded view and return it to the thumbnail when it closes, and dim the page behind with a fading backdrop. With prefers-reduced-motion, open and close the large view with a quick fade instead. Build it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "tilted-color-panels-background", category: "interface-style", aspect: null, prompt: "Add a tilted color panel background to [where to apply it, e.g. the hero section]: long translucent panels, each with a gradient between two or more page colors, fanned at different angles and overlapping so their colors mix where they cross.\nRender it in a WebGL fragment shader with uniforms for the two tilt angles, panel density, panel length, edge blur and fade in/out at the ends.\nRotate the arrangement very slowly, one full turn over a minute or more, and let pointer movement shift the angles slightly.\nWith prefers-reduced-motion, render one still frame; keep a calm area behind text so headlines keep strong contrast.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "tilted-hexagon-tile-backdrop", category: "interface-style", aspect: null, prompt: "Add a hexagon tile pattern behind [where to apply it, e.g. the pricing section]: a seamless honeycomb of thin outlines drawn with an inline SVG pattern, rotated a few degrees and faded toward the edges with a mask.\nFill a handful of hexagons with a soft accent tint, aligned to the same spacing as the outlines; with a dashed stroke, make sure shared edges are drawn once so dashes do not double up.\nOn hover over the section, let the highlighted cells brighten slightly over about 250ms; on touch, leave them at rest.\nThe pattern is decorative only: keep pointer-events off, keep it low contrast behind text, and with prefers-reduced-motion skip the hover change.\nUse plain HTML, CSS, inline SVG and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "tiny-grid-expand-transition", category: "interface-style", aspect: null, prompt: "Apply a grid expand transition to [where to apply it, e.g. the works section]. Show a compact cluster of small thumbnails; when the user opens it, record each tile's current position and size, switch the grid into the large layout, then animate every tile from its old box to its new one with transforms over about 0.7 seconds and a gentle stagger. Closing plays the same motion in reverse, and a new open or close request cancels the running one and continues from wherever the tiles are now. Use a real button to open and close, move focus into the expanded view and back again, and let Escape close it. Hover lifts a tile slightly; on touch a tap simply opens. With prefers-reduced-motion, swap layouts instantly or with a quick fade. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "tooltip-to-gallery-transition", category: "interface-style", aspect: null, prompt: "Add a tooltip to gallery transition to [where to apply it, e.g. the project names in the hero]. Hovering or focusing a name shows a small floating thumbnail that quietly cycles through a few images; clicking it morphs that thumbnail into a grid gallery, and clicking a grid image expands it to fill the screen. Animate each step by measuring the start and end boxes and transforming between them over about 700ms with an ease-out curve. Stop the thumbnail cycle as soon as the pointer leaves, and offer a visible close button plus Escape to step back, returning focus to the trigger. With prefers-reduced-motion, cross-fade between states instead of moving. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "traveling-edge-beam-border", category: "interface-style", aspect: null, prompt: "Add a traveling edge beam to [which card, e.g. the featured plan or login card]. Draw a 1 to 2px border track in a faint tone and a short bright beam, a gradient from transparent to the accent color, that moves along the border path; clip it to the border with a mask so it never spills over the content.\nLoop the beam around the full perimeter every 6 to 10 seconds at an even speed, and optionally speed it up slightly while the card is hovered or focused.\nGive the beam layer pointer-events: none so every input and button inside stays fully usable, and keep the card text static.\nUnder prefers-reduced-motion, stop the beam and show a still glowing segment on one corner.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "twinkling-cell-grid-background", category: "interface-style", aspect: null, prompt: "Add a twinkling cell grid behind [where to apply it, e.g. the hero section]: a thin line grid in a muted tone of the page palette, with about thirty cells at a time gently filling with a soft tint.\nEach lit cell fades in over roughly a second, holds briefly, fades out, then reappears at a new random spot, so the pattern never settles into a loop; rebuild the cell layout when the container resizes.\nKeep the grid behind content with pointer-events: none and fade its edges with a radial mask so text in the middle stays clear.\nWith prefers-reduced-motion, show a fixed handful of tinted cells and no animation, and pause the loop when the section is off screen.\nBuild it with plain HTML, CSS and vanilla JavaScript (inline SVG is fine), with no external libraries, CDNs, fonts or network assets." },
  { id: "twinkling-star-field-background", category: "interface-style", aspect: null, prompt: "Add a twinkling star field to [where to apply it, e.g. a dark hero or footer]. Scatter about 40 to 60 small dots at random positions with varied sizes from 1 to 3px and slightly different warm and cool whites over a deep sky gradient.\nGive each star its own slow twinkle of 2 to 6 seconds that gently changes brightness and size, with random delays so no two pulse together, and keep the change soft rather than flashing.\nHide the stars from assistive technology, keep them behind the content with pointer-events: none, and keep text contrast steady.\nUnder prefers-reduced-motion, stop the twinkle and leave the stars still.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "twinkling-star-sparkle-text", category: "interface-style", aspect: null, prompt: "Add twinkling stars around [which text, e.g. a key word in the headline].\nPlace about ten small four-point star shapes drawn in inline SVG at random spots over and around the text, in two colors taken from the page palette; each star scales up, rotates a little and fades out over about 0.8 seconds, and when its short life ends it reappears at a fresh random position so the sparkle never looks like a fixed pattern.\nUse a single timer or animation loop for all stars, pause it when the text is off screen or the tab is hidden, and keep stars from covering the letters heavily.\nThe stars are decorative and hidden from assistive tech; with prefers-reduced-motion show a few static stars only.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "type-window-image-expand", category: "interface-style", aspect: null, prompt: "Add a type window image expand to [which section, e.g. the intro headline], placing a small image inline between two words of a large headline.\nAs the section scrolls through a pinned range of about one and a half viewport heights, the image grows smoothly until it covers the viewport while the surrounding words slide apart and fade, then the following content scrolls in over it.\nTie the progress directly to scroll position so scrolling back reverses it, measure positions again on resize, and keep the headline readable as normal text at the start.\nWith prefers-reduced-motion, show the headline and a full-width image stacked without pinning or scaling, and give the image meaningful alt text or mark it decorative.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "typed-terminal-sequence-window", category: "interface-style", aspect: null, prompt: "Add a typed terminal window to [where to apply it, e.g. the getting-started section]. Draw a dark rounded panel with three small window dots and a monospace body, then play a scripted sequence: the first command types out character by character at about 40 ms per character, and each following output line fades in only after the previous step finishes. Use a blinking caret while typing and color success lines with the page's accent. Start when the panel scrolls into view, and offer a small replay control. Keep the full text in the DOM so it can be read and copied, and under prefers-reduced-motion show all lines at once. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "velocity-marquee-text", category: "interface-style", aspect: null, prompt: "Add velocity-reactive marquee text to [where to apply it, e.g. a band between the hero and the features]. Repeat a short phrase in large type across one or two rows that drift horizontally at a slow base speed, with rows moving in opposite directions, and wrap the position seamlessly so the loop never shows a gap. Measure scroll velocity each frame and use it to multiply the speed and flip the direction when the user scrolls up, easing back to the base speed within about half a second after scrolling stops. Draw the moving band on a canvas sized to the band and sharp at the device pixel ratio, painting the phrase each frame, and give the canvas role=\"img\" with an aria-label that lists them, so no readable text or logo ever sits half-clipped at an edge. Respect prefers-reduced-motion by stopping the movement entirely and showing the phrase once as static text, not just removing the velocity boost. Build it with plain HTML, CSS and vanilla JavaScript only, no external libraries, CDNs, fonts or network assets." },
  { id: "wavy-scroll-image-carousel", category: "interface-style", aspect: null, prompt: "Add a wavy scroll carousel to [where to apply it, e.g. the work gallery]: a horizontal strip of images that loops endlessly, wrapping each image back around once it passes the total strip width.\nTrack scroll or drag velocity with smoothing; feed it to a WebGL vertex shader so each image bends into a sine wave whose amplitude grows with speed and relaxes back to flat within about half a second after stopping.\nOn hover, an image can straighten and lift slightly; arrow keys and visible buttons also move the strip.\nWith prefers-reduced-motion, keep images flat and move them without the wave; image alt text and captions stay in the HTML so the content works without the effect.\nUse plain HTML, CSS and vanilla JavaScript with WebGL written in the page, with no external libraries, CDNs, fonts or network assets." },
  { id: "wavy-still-mesh-gradient", category: "interface-style", aspect: null, prompt: "Add a wavy still gradient to [where to apply it, e.g. the pricing section or a cover card]. Place four or five palette colors at seeded points, blend them smoothly in a fragment shader or a canvas render, and bend the coordinates with sine waves along each axis so the color fields curve like silk; render it once.\nLet the user-facing look stay fixed, with no time-based animation, and redraw only when the element resizes or the theme changes.\nCheck that text over every region of the gradient keeps enough contrast, and set a solid background color underneath as the fallback.\nBecause nothing moves, it already suits prefers-reduced-motion.\nBuild it with plain HTML, CSS and vanilla JavaScript with no external libraries, CDNs, fonts or network assets." },
  { id: "waypoint-traveling-scroll-element", category: "interface-style", aspect: null, prompt: "Add a waypoint traveling element to [which image or object, e.g. the product shot]. Mark an empty placeholder slot in each section, then as the visitor scrolls between sections, move and resize the single element from one slot's position and shape to the next, scrubbing with scroll progress so it can stop halfway or reverse. Remeasure all slots on resize. Keep the element's alt text meaningful and make sure each section reads fine without it. Under prefers-reduced-motion, place a static copy of the element in each slot instead. Build it with plain HTML, CSS and vanilla JavaScript, with no external libraries, CDNs, fonts or network assets." },
  { id: "weight-wave-hover-text", category: "interface-style", aspect: null, prompt: "Apply a weight-wave hover effect to [which text, e.g. the main heading].\nSplit the text into letter spans (hidden from assistive tech, with the full text kept once for screen readers) and, when the pointer is over a letter, raise its font weight to the heaviest available value while its two neighbors step up halfway, all easing in about 200 ms.\nUse the page's existing font, falling back to synthetic weight shifts via a light text-stroke if it has no variable weights, and make sure line breaks happen between words, never inside them.\nOn touch, a tap triggers the same swell for a moment before settling back.\nWith prefers-reduced-motion, change weight instantly with no easing, and the text must read normally when the effect is off.\nBuild it with plain HTML, CSS and vanilla JavaScript only, with no external libraries, CDNs, fonts or network assets." },
  { id: "wind-swept-grass-background", category: "interface-style", aspect: null, prompt: "Add a wind-swept grass field to [where to apply it, e.g. the bottom of the hero section]: draw thousands of thin, tapered blades with a soft gradient from a deep base color to a sunlit tip, tinted to suit the page palette.\nAnimate a slow breeze that rolls across the field in waves every few seconds, with each blade bending a little differently so it feels alive rather than mechanical.\nWhen the pointer moves over the field, gently part the nearby blades as if a hand were brushing through them; on touch, do the same along the finger path.\nRespect prefers-reduced-motion by freezing the grass in a natural resting pose, keep text over it readable with a subtle shade behind it, and lower the blade count on small screens to stay smooth.\nBuild it with plain HTML, CSS and vanilla JavaScript using WebGL or canvas written in the page, with no external libraries, CDNs, fonts or network assets." },
];
